window.ExtraBibleBooks=window.ExtraBibleBooks||{};window.ExtraBibleBooks["JOB"]={"book":"JOB","editions":{"epo-londona":[[1,1,"Estis iu homo en la lando Uc, lia nomo estis Ijob. Tiu homo estis honesta, justa, diotima, kaj li evitadis malbonon.","Estis iu homo en la lando Uc, lia nomo estis Ijob. Tiu homo estis honesta, justa, diotima, kaj li evitadis malbonon."],[1,2,"Al li naskiĝis sep filoj kaj tri filinoj.","Al li naskiĝis sep filoj kaj tri filinoj."],[1,3,"Lia brutaro konsistis el sep mil ŝafoj, tri mil kameloj, kvincent paroj da bovoj, kvincent azeninoj, kaj li havis tre multe da servistoj; kaj tiu homo estis pli eminenta, ol ĉiuj filoj de la oriento.","Lia brutaro konsistis el sep mil ŝafoj, tri mil kameloj, kvincent paroj da bovoj, kvincent azeninoj, kaj li havis tre multe da servistoj; kaj tiu homo estis pli eminenta, ol ĉiuj filoj de la oriento."],[1,4,"Liaj filoj havis la kutimon faradi festenon en la domo de ĉiu el ili, ĉiu en sia tago; kaj ili invitadis siajn tri fratinojn, por manĝi kaj trinki kun ili.","Liaj filoj havis la kutimon faradi festenon en la domo de ĉiu el ili, ĉiu en sia tago; kaj ili invitadis siajn tri fratinojn, por manĝi kaj trinki kun ili."],[1,5,"Kaj ĉiufoje, kiam la rondo de la festenaj tagoj estis finita, Ijob sendis, por sanktigi ilin, kaj li leviĝis frue matene kaj alportis bruloferojn laŭ la nombro de ili ĉiuj; ĉar, diris Ijob: Eble miaj filoj pekis kaj blasfemis Dion en sia koro. Tiel agadis Ijob ĉiam.","Kaj ĉiufoje, kiam la rondo de la festenaj tagoj estis finita, Ijob sendis, por sanktigi ilin, kaj li leviĝis frue matene kaj alportis bruloferojn laŭ la nombro de ili ĉiuj; ĉar, diris Ijob: Eble miaj filoj pekis kaj blasfemis Dion en sia koro. Tiel agadis Ijob ĉiam."],[1,6,"Unu tagon, kiam la filoj de Dio venis, por stariĝi antaŭ la Eternulo, venis inter ili ankaŭ Satano.","Unu tagon, kiam la filoj de Dio venis, por stariĝi antaŭ la Eternulo, venis inter ili ankaŭ Satano."],[1,7,"Kaj la Eternulo diris al Satano: De kie vi venas? Kaj Satano respondis al la Eternulo, kaj diris: Mi vagadis sur la tero kaj rondiradis sur ĝi.","Kaj la Eternulo diris al Satano: De kie vi venas? Kaj Satano respondis al la Eternulo, kaj diris: Mi vagadis sur la tero kaj rondiradis sur ĝi."],[1,8,"Kaj la Eternulo diris al Satano: Ĉu vi atentis Mian servanton Ijob? ne ekzistas ja sur la tero homo simila al li, tiel honesta, justa, diotima, kaj evitanta malbonon.","Kaj la Eternulo diris al Satano: Ĉu vi atentis Mian servanton Ijob? ne ekzistas ja sur la tero homo simila al li, tiel honesta, justa, diotima, kaj evitanta malbonon."],[1,9,"Kaj Satano respondis al la Eternulo, kaj diris: Ĉu vane Ijob timas Dion?","Kaj Satano respondis al la Eternulo, kaj diris: Ĉu vane Ijob timas Dion?"],[1,10,"Vi ŝirmis ja ĉiuflanke lin kaj lian domon, kaj ĉion, kio apartenas al li; la farojn de liaj manoj Vi benis, kaj liaj brutaroj disvastiĝis sur la tero.","Vi ŝirmis ja ĉiuflanke lin kaj lian domon, kaj ĉion, kio apartenas al li; la farojn de liaj manoj Vi benis, kaj liaj brutaroj disvastiĝis sur la tero."],[1,11,"Sed etendu nur Vian manon, kaj ektuŝu ĉion, kion li havas; Vi vidos, ĉu li ne blasfemos Vin antaŭ Via vizaĝo.","Sed etendu nur Vian manon, kaj ektuŝu ĉion, kion li havas; Vi vidos, ĉu li ne blasfemos Vin antaŭ Via vizaĝo."],[1,12,"Tiam la Eternulo diris al Satano: Jen ĉio, kion li havas, estas transdonata en vian manon; nur sur lin mem ne etendu vian manon. Kaj Satano foriris de antaŭ la Eternulo.","Tiam la Eternulo diris al Satano: Jen ĉio, kion li havas, estas transdonata en vian manon; nur sur lin mem ne etendu vian manon. Kaj Satano foriris de antaŭ la Eternulo."],[1,13,"Unu tagon, kiam liaj filoj kaj liaj filinoj estis manĝantaj kaj trinkantaj vinon en la domo de ilia unuenaskita frato,","Unu tagon, kiam liaj filoj kaj liaj filinoj estis manĝantaj kaj trinkantaj vinon en la domo de ilia unuenaskita frato,"],[1,14,"venis sendito al Ijob, kaj diris: Dum la bovoj estis plugantaj kaj la azeninoj estis paŝtiĝantaj apud ili,","venis sendito al Ijob, kaj diris: Dum la bovoj estis plugantaj kaj la azeninoj estis paŝtiĝantaj apud ili,"],[1,15,"superfalis ilin la Ŝebaanoj, kaj forprenis ilin; kaj la servistojn ili mortigis per glavo; saviĝis nur mi sola, por raporti al vi.","superfalis ilin la Ŝebaanoj, kaj forprenis ilin; kaj la servistojn ili mortigis per glavo; saviĝis nur mi sola, por raporti al vi."],[1,16,"Kiam ankoraŭ tiu parolis, venis alia, kaj diris: Fajro de Dio falis el la ĉielo, bruligis la ŝafojn kaj la servistojn, kaj ekstermis ilin; saviĝis nur mi sola, por raporti al vi.","Kiam ankoraŭ tiu parolis, venis alia, kaj diris: Fajro de Dio falis el la ĉielo, bruligis la ŝafojn kaj la servistojn, kaj ekstermis ilin; saviĝis nur mi sola, por raporti al vi."],[1,17,"Kiam tiu ankoraŭ parolis, venis alia, kaj diris: La Ĥaldeoj aranĝis tri taĉmentojn, atakis la kamelojn kaj forprenis ilin, kaj la servistojn ili mortigis per glavo; saviĝis nur mi sola, por raporti al vi.","Kiam tiu ankoraŭ parolis, venis alia, kaj diris: La Ĥaldeoj aranĝis tri taĉmentojn, atakis la kamelojn kaj forprenis ilin, kaj la servistojn ili mortigis per glavo; saviĝis nur mi sola, por raporti al vi."],[1,18,"Dum tiu ankoraŭ parolis, venis alia, kaj diris: Viaj filoj kaj viaj filinoj estis manĝantaj kaj trinkantaj vinon en la domo de ilia unuenaskita frato;","Dum tiu ankoraŭ parolis, venis alia, kaj diris: Viaj filoj kaj viaj filinoj estis manĝantaj kaj trinkantaj vinon en la domo de ilia unuenaskita frato;"],[1,19,"kaj jen granda vento leviĝis de la flanko de la dezerto, puŝis la kvar angulojn de la domo, kaj ĉi tiu falis sur la junulojn, kaj ili mortis; saviĝis nur mi sola, por raporti al vi.","kaj jen granda vento leviĝis de la flanko de la dezerto, puŝis la kvar angulojn de la domo, kaj ĉi tiu falis sur la junulojn, kaj ili mortis; saviĝis nur mi sola, por raporti al vi."],[1,20,"Tiam Ijob leviĝis, disŝiris sian veston, pritondis sian kapon, ĵetis sin sur la teron, kaj adorkliniĝis;","Tiam Ijob leviĝis, disŝiris sian veston, pritondis sian kapon, ĵetis sin sur la teron, kaj adorkliniĝis;"],[1,21,"kaj li diris: Nuda mi eliris el la ventro de mia patrino, kaj nuda mi revenos tien; la Eternulo donis, kaj la Eternulo prenis; la nomo de la Eternulo estu benata.","kaj li diris: Nuda mi eliris el la ventro de mia patrino, kaj nuda mi revenos tien; la Eternulo donis, kaj la Eternulo prenis; la nomo de la Eternulo estu benata."],[1,22,"Malgraŭ ĉio ĉi tio Ijob ne pekis, kaj ne eldiris blasfemon kontraŭ Dio.","Malgraŭ ĉio ĉi tio Ijob ne pekis, kaj ne eldiris blasfemon kontraŭ Dio."],[2,1,"Unu tagon, kiam la filoj de Dio venis, por stariĝi antaŭ la Eternulo, venis ankaŭ Satano inter ili, por stariĝi antaŭ la Eternulo.","Unu tagon, kiam la filoj de Dio venis, por stariĝi antaŭ la Eternulo, venis ankaŭ Satano inter ili, por stariĝi antaŭ la Eternulo."],[2,2,"Kaj la Eternulo diris al Satano: De kie vi venas? Kaj Satano respondis al la Eternulo, kaj diris: Mi vagadis sur la tero kaj rondiradis sur ĝi.","Kaj la Eternulo diris al Satano: De kie vi venas? Kaj Satano respondis al la Eternulo, kaj diris: Mi vagadis sur la tero kaj rondiradis sur ĝi."],[2,3,"Kaj la Eternulo diris al Satano: Ĉu vi atentis Mian servanton Ijob? ne ekzistas sur la tero homo simila al li, tiel honesta, justa, diotima, kaj evitanta malbonon; kaj li ĝis nun ankoraŭ estas firma en sia virteco, kvankam vi ekscitis Min kontraŭ li, por pereigi lin senkulpe.","Kaj la Eternulo diris al Satano: Ĉu vi atentis Mian servanton Ijob? ne ekzistas sur la tero homo simila al li, tiel honesta, justa, diotima, kaj evitanta malbonon; kaj li ĝis nun ankoraŭ estas firma en sia virteco, kvankam vi ekscitis Min kontraŭ li, por pereigi lin senkulpe."],[2,4,"Tiam Satano respondis al la Eternulo, kaj diris: Haŭto pro haŭto; kaj ĉion, kion homo posedas, li fordonus pro sia vivo.","Tiam Satano respondis al la Eternulo, kaj diris: Haŭto pro haŭto; kaj ĉion, kion homo posedas, li fordonus pro sia vivo."],[2,5,"Sed etendu Vian manon, kaj tuŝu liajn ostojn kaj lian karnon; tiam Vi vidos, ke li blasfemos Vin antaŭ Via vizaĝo.","Sed etendu Vian manon, kaj tuŝu liajn ostojn kaj lian karnon; tiam Vi vidos, ke li blasfemos Vin antaŭ Via vizaĝo."],[2,6,"La Eternulo diris al Satano: Jen li estas transdonata en vian manon; nur lian vivon konservu.","La Eternulo diris al Satano: Jen li estas transdonata en vian manon; nur lian vivon konservu."],[2,7,"Satano foriris de antaŭ la vizaĝo de la Eternulo, kaj frapis Ijobon per turmentaj abscesoj de la plando de lia piedo ĝis lia verto.","Satano foriris de antaŭ la vizaĝo de la Eternulo, kaj frapis Ijobon per turmentaj abscesoj de la plando de lia piedo ĝis lia verto."],[2,8,"Li prenis potpecon, por skrapadi sin per ĝi, sidante meze de cindro.","Li prenis potpecon, por skrapadi sin per ĝi, sidante meze de cindro."],[2,9,"Kaj lia edzino diris al li: Vi ĉiam ankoraŭ estas firma en via virteco! blasfemu Dion, kaj mortu.","Kaj lia edzino diris al li: Vi ĉiam ankoraŭ estas firma en via virteco! blasfemu Dion, kaj mortu."],[2,10,"Sed li diris al ŝi: Vi parolas tiel, kiel parolas iu el la malsaĝulinoj; ĉu bonon ni akceptu de Dio, kaj malbonon ni ne akceptu? Malgraŭ ĉio ĉi tio Ijob ne pekis per siaj lipoj.","Sed li diris al ŝi: Vi parolas tiel, kiel parolas iu el la malsaĝulinoj; ĉu bonon ni akceptu de Dio, kaj malbonon ni ne akceptu? Malgraŭ ĉio ĉi tio Ijob ne pekis per siaj lipoj."],[2,11,"Kiam la tri amikoj de Ijob aŭdis pri tiu tuta malfeliĉo, kiu trafis lin, ili iris ĉiu de sia loko, Elifaz, la Temanano, Bildad, la Ŝuĥano, kaj Cofar, la Naamano, kaj kunvenis kune, por iri plori kun li kaj konsoli lin.","Kiam la tri amikoj de Ijob aŭdis pri tiu tuta malfeliĉo, kiu trafis lin, ili iris ĉiu de sia loko, Elifaz, la Temanano, Bildad, la Ŝuĥano, kaj Cofar, la Naamano, kaj kunvenis kune, por iri plori kun li kaj konsoli lin."],[2,12,"Kiam ili levis siajn okulojn de malproksime, ili ne rekonis lin; kaj ili levis sian voĉon kaj ekploris; kaj ĉiu el ili disŝiris sian veston, kaj ĵetis teron sur sian kapon, turnante sin al la ĉielo.","Kiam ili levis siajn okulojn de malproksime, ili ne rekonis lin; kaj ili levis sian voĉon kaj ekploris; kaj ĉiu el ili disŝiris sian veston, kaj ĵetis teron sur sian kapon, turnante sin al la ĉielo."],[2,13,"Kaj ili sidis kun li sur la tero dum sep tagoj kaj sep noktoj, kaj ne parolis al li eĉ unu vorton; ĉar ili vidis, ke la suferado estas tre granda.","Kaj ili sidis kun li sur la tero dum sep tagoj kaj sep noktoj, kaj ne parolis al li eĉ unu vorton; ĉar ili vidis, ke la suferado estas tre granda."],[3,1,"Poste Ijob malfermis sian buŝon, kaj malbenis sian tagon.","Poste Ijob malfermis sian buŝon, kaj malbenis sian tagon."],[3,2,"Kaj Ijob ekparolis, kaj diris:","Kaj Ijob ekparolis, kaj diris:"],[3,3,"Pereu la tago, en kiu mi naskiĝis, Kaj la nokto, kiu diris: Embriiĝis homo.","Pereu la tago, en kiu mi naskiĝis, Kaj la nokto, kiu diris: Embriiĝis homo."],[3,4,"Tiu tago estu malluma; Dio de supre ne rigardu ĝin, Neniu lumo ekbrilu super ĝi.","Tiu tago estu malluma; Dio de supre ne rigardu ĝin, Neniu lumo ekbrilu super ĝi."],[3,5,"Mallumo kaj tomba ombro ekposedu ĝin; Nubo ĝin kovru; Eklipsoj de tago faru ĝin terura.","Mallumo kaj tomba ombro ekposedu ĝin; Nubo ĝin kovru; Eklipsoj de tago faru ĝin terura."],[3,6,"Tiun nokton prenu mallumego; Ĝi ne alkalkuliĝu al la tagoj de la jaro, Ĝi ne eniru en la kalkulon de la monatoj.","Tiun nokton prenu mallumego; Ĝi ne alkalkuliĝu al la tagoj de la jaro, Ĝi ne eniru en la kalkulon de la monatoj."],[3,7,"Ho, tiu nokto estu soleca; Neniu ĝojkrio aŭdiĝu en ĝi.","Ho, tiu nokto estu soleca; Neniu ĝojkrio aŭdiĝu en ĝi."],[3,8,"Malbenu ĝin la malbenantoj de la tago, Tiuj, kiuj estas pretaj eksciti levjatanon.","Malbenu ĝin la malbenantoj de la tago, Tiuj, kiuj estas pretaj eksciti levjatanon."],[3,9,"Mallumiĝu la steloj de ĝia krepusko; Ĝi atendu lumon, kaj ĉi tiu ne aperu; Kaj la palpebrojn de matenruĝo ĝi ne ekvidu;","Mallumiĝu la steloj de ĝia krepusko; Ĝi atendu lumon, kaj ĉi tiu ne aperu; Kaj la palpebrojn de matenruĝo ĝi ne ekvidu;"],[3,10,"Pro tio, ke ĝi ne fermis la pordon de la utero de mia patrino Kaj ne kaŝis per tio la malfeliĉon antaŭ miaj okuloj.","Pro tio, ke ĝi ne fermis la pordon de la utero de mia patrino Kaj ne kaŝis per tio la malfeliĉon antaŭ miaj okuloj."],[3,11,"Kial mi ne mortis tuj el la utero, Ne senviviĝis post la eliro el la ventro?","Kial mi ne mortis tuj el la utero, Ne senviviĝis post la eliro el la ventro?"],[3,12,"Kial akceptis min la genuoj? Por kio estis la mamoj, ke mi suĉu?","Kial akceptis min la genuoj? Por kio estis la mamoj, ke mi suĉu?"],[3,13,"Mi nun kuŝus kaj estus trankvila; Mi dormus kaj havus ripozon,","Mi nun kuŝus kaj estus trankvila; Mi dormus kaj havus ripozon,"],[3,14,"Kune kun la reĝoj kaj la konsilistoj sur la tero, Kiuj konstruas al si izolejojn,","Kune kun la reĝoj kaj la konsilistoj sur la tero, Kiuj konstruas al si izolejojn,"],[3,15,"Aŭ kun la potenculoj, kiuj havas oron, Kiuj plenigas siajn domojn per arĝento;","Aŭ kun la potenculoj, kiuj havas oron, Kiuj plenigas siajn domojn per arĝento;"],[3,16,"Aŭ kiel abortitaĵo kaŝita mi ne ekzistus, Simile al la infanoj, kiuj ne vidis lumon.","Aŭ kiel abortitaĵo kaŝita mi ne ekzistus, Simile al la infanoj, kiuj ne vidis lumon."],[3,17,"Tie la malpiuloj ĉesas tumulti; Kaj tie ripozas tiuj, kies fortoj konsumiĝis.","Tie la malpiuloj ĉesas tumulti; Kaj tie ripozas tiuj, kies fortoj konsumiĝis."],[3,18,"Tie la malliberuloj kune havas ripozon; Ili ne aŭdas la voĉon de premanto.","Tie la malliberuloj kune havas ripozon; Ili ne aŭdas la voĉon de premanto."],[3,19,"Malgranduloj kaj granduloj, tie ili estas; Kaj sklavo estas libera de sia sinjoro.","Malgranduloj kaj granduloj, tie ili estas; Kaj sklavo estas libera de sia sinjoro."],[3,20,"Por kio al suferanto estas donita la lumo, Kaj la vivo al tiuj, kiuj havas maldolĉan animon,","Por kio al suferanto estas donita la lumo, Kaj la vivo al tiuj, kiuj havas maldolĉan animon,"],[3,21,"Kiuj atendas la morton, kaj ĝi ne aperas, Kiuj elfosus ĝin pli volonte ol trezorojn,","Kiuj atendas la morton, kaj ĝi ne aperas, Kiuj elfosus ĝin pli volonte ol trezorojn,"],[3,22,"Kiuj ekĝojus kaj estus ravitaj, Se ili trovus tombon?","Kiuj ekĝojus kaj estus ravitaj, Se ili trovus tombon?"],[3,23,"Al la homo, kies vojo estas kaŝita, Kaj antaŭ kiu Dio starigis barilon?","Al la homo, kies vojo estas kaŝita, Kaj antaŭ kiu Dio starigis barilon?"],[3,24,"Antaŭ ol mi ekmanĝas panon, mi devas ĝemi, Kaj mia plorkriado verŝiĝas kiel akvo;","Antaŭ ol mi ekmanĝas panon, mi devas ĝemi, Kaj mia plorkriado verŝiĝas kiel akvo;"],[3,25,"Ĉar teruraĵo, kiun mi timis, trafis min, Kaj tio, pri kio mi estis maltrankvila, venis al mi.","Ĉar teruraĵo, kiun mi timis, trafis min, Kaj tio, pri kio mi estis maltrankvila, venis al mi."],[3,26,"Mi ne havas trankvilon, mi ne havas kvieton, mi ne havas ripozon; Trafis min kolero.","Mi ne havas trankvilon, mi ne havas kvieton, mi ne havas ripozon; Trafis min kolero."],[4,1,"Kaj ekparolis Elifaz, la Temanano, kaj diris:","Kaj ekparolis Elifaz, la Temanano, kaj diris:"],[4,2,"Se oni provos diri al vi vorton, tio eble estos por vi turmenta? Sed kiu povas deteni sin de parolado?","Se oni provos diri al vi vorton, tio eble estos por vi turmenta? Sed kiu povas deteni sin de parolado?"],[4,3,"Jen vi multajn instruis, Kaj manojn senfortiĝintajn vi refortigis;","Jen vi multajn instruis, Kaj manojn senfortiĝintajn vi refortigis;"],[4,4,"Falantojn restarigis viaj vortoj, Kaj fleksiĝantajn genuojn vi fortigis;","Falantojn restarigis viaj vortoj, Kaj fleksiĝantajn genuojn vi fortigis;"],[4,5,"Kaj nun, kiam tio trafis vin, vi perdis la forton; Ĝi ektuŝis vin, kaj vi ektimis.","Kaj nun, kiam tio trafis vin, vi perdis la forton; Ĝi ektuŝis vin, kaj vi ektimis."],[4,6,"Ĉu ne via timo antaŭ Dio estas via konsolo? Ĉu la virteco de viaj vojoj ne estas via espero?","Ĉu ne via timo antaŭ Dio estas via konsolo? Ĉu la virteco de viaj vojoj ne estas via espero?"],[4,7,"Rememoru do, ĉu pereis iu senkulpa? Kaj kie virtuloj estis ekstermitaj?","Rememoru do, ĉu pereis iu senkulpa? Kaj kie virtuloj estis ekstermitaj?"],[4,8,"Kiel mi vidis, tiuj, kiuj plugis pekojn kaj semis malbonagojn, Tiuj ilin rikoltas;","Kiel mi vidis, tiuj, kiuj plugis pekojn kaj semis malbonagojn, Tiuj ilin rikoltas;"],[4,9,"De la ekblovo de Dio ili pereas, Kaj de la ekspiro de Lia kolero ili malaperas.","De la ekblovo de Dio ili pereas, Kaj de la ekspiro de Lia kolero ili malaperas."],[4,10,"La kriado de leono kaj la voĉo de leopardo silentiĝis, Kaj la dentoj de junaj leonoj rompiĝis;","La kriado de leono kaj la voĉo de leopardo silentiĝis, Kaj la dentoj de junaj leonoj rompiĝis;"],[4,11,"Leono pereis pro manko de manĝaĵo, Kaj idoj de leonino diskuris.","Leono pereis pro manko de manĝaĵo, Kaj idoj de leonino diskuris."],[4,12,"Kaj al mi kaŝe alvenis vorto, Kaj mia orelo kaptis parteton de ĝi.","Kaj al mi kaŝe alvenis vorto, Kaj mia orelo kaptis parteton de ĝi."],[4,13,"Dum meditado pri la vizioj de la nokto, Kiam profunda dormo falas sur la homojn,","Dum meditado pri la vizioj de la nokto, Kiam profunda dormo falas sur la homojn,"],[4,14,"Atakis min teruro kaj tremo, Kaj ĉiuj miaj ostoj eksentis timon.","Atakis min teruro kaj tremo, Kaj ĉiuj miaj ostoj eksentis timon."],[4,15,"Kaj spirito traflugis antaŭ mi, Kaj la haroj sur mia korpo rigidiĝis.","Kaj spirito traflugis antaŭ mi, Kaj la haroj sur mia korpo rigidiĝis."],[4,16,"Staris bildo antaŭ miaj okuloj, sed mi ne povis rekoni ĝian aspekton; Estis silento, kaj mi ekaŭdis voĉon, dirantan:","Staris bildo antaŭ miaj okuloj, sed mi ne povis rekoni ĝian aspekton; Estis silento, kaj mi ekaŭdis voĉon, dirantan:"],[4,17,"Ĉu homo estas pli justa ol Dio? Ĉu viro estas pli pura ol lia Kreinto?","Ĉu homo estas pli justa ol Dio? Ĉu viro estas pli pura ol lia Kreinto?"],[4,18,"Vidu, al Siaj servantoj Li ne konfidas, Kaj Siajn anĝelojn Li trovas mallaŭdindaj:","Vidu, al Siaj servantoj Li ne konfidas, Kaj Siajn anĝelojn Li trovas mallaŭdindaj:"],[4,19,"Des pli koncerne tiujn, Kiuj loĝas en argilaj dometoj, Fonditaj sur tero, Kaj kiujn formanĝas vermoj.","Des pli koncerne tiujn, Kiuj loĝas en argilaj dometoj, Fonditaj sur tero, Kaj kiujn formanĝas vermoj."],[4,20,"De la mateno ĝis la vespero ili disfalas, Pereas por ĉiam, kaj neniu tion atentas.","De la mateno ĝis la vespero ili disfalas, Pereas por ĉiam, kaj neniu tion atentas."],[4,21,"La fadeno de ilia vivo estas distranĉita; Ili mortas, kaj ne en saĝeco.","La fadeno de ilia vivo estas distranĉita; Ili mortas, kaj ne en saĝeco."],[5,1,"Voku do! ĉu iu respondos al vi? Kaj al kiu el la sanktuloj vi vin turnos?","Voku do! ĉu iu respondos al vi? Kaj al kiu el la sanktuloj vi vin turnos?"],[5,2,"Malsaĝulon mortigas la kolero, Kaj sensenculon pereigas la incitiĝemeco.","Malsaĝulon mortigas la kolero, Kaj sensenculon pereigas la incitiĝemeco."],[5,3,"Mi vidis malsaĝulon, kiu enradikiĝis, Kaj mi malbenis subite lian loĝejon.","Mi vidis malsaĝulon, kiu enradikiĝis, Kaj mi malbenis subite lian loĝejon."],[5,4,"Malproksimaj de savo estos liaj filoj; Oni disbatos ilin ĉe la pordego, Kaj neniu ilin savos.","Malproksimaj de savo estos liaj filoj; Oni disbatos ilin ĉe la pordego, Kaj neniu ilin savos."],[5,5,"Lian rikoltaĵon formanĝos malsatulo, El inter la dornoj li ĝin prenos, Kaj soifantoj englutos lian havaĵon.","Lian rikoltaĵon formanĝos malsatulo, El inter la dornoj li ĝin prenos, Kaj soifantoj englutos lian havaĵon."],[5,6,"Ne el la polvo eliras malpiaĵo, Kaj ne el la tero elkreskas malbonago.","Ne el la polvo eliras malpiaĵo, Kaj ne el la tero elkreskas malbonago."],[5,7,"Sed homo naskiĝas por suferoj, Kiel birdoj por flugado supren.","Sed homo naskiĝas por suferoj, Kiel birdoj por flugado supren."],[5,8,"Sed mi min turnus al Dio, Kaj al Li mi transdonus mian aferon;","Sed mi min turnus al Dio, Kaj al Li mi transdonus mian aferon;"],[5,9,"Al Tiu, kiu faras grandaĵojn, kiujn neniu povas esplori, Mirindaĵojn, kiujn neniu povas kalkuli;","Al Tiu, kiu faras grandaĵojn, kiujn neniu povas esplori, Mirindaĵojn, kiujn neniu povas kalkuli;"],[5,10,"Kiu donas pluvon sur la teron Kaj sendas akvon sur la kampojn,","Kiu donas pluvon sur la teron Kaj sendas akvon sur la kampojn,"],[5,11,"Por starigi malaltulojn alte, Ke la afliktitoj leviĝu savite.","Por starigi malaltulojn alte, Ke la afliktitoj leviĝu savite."],[5,12,"Li detruas la intencojn de ruzuloj, Ke iliaj manoj ne plenumas sian entreprenon.","Li detruas la intencojn de ruzuloj, Ke iliaj manoj ne plenumas sian entreprenon."],[5,13,"Li kaptas la saĝulojn per ilia ruzaĵo; Kaj la decido de maliculoj fariĝas senvalora.","Li kaptas la saĝulojn per ilia ruzaĵo; Kaj la decido de maliculoj fariĝas senvalora."],[5,14,"En la tago ili renkontas mallumon, Kaj en tagmezo ili palpas, kiel en nokto.","En la tago ili renkontas mallumon, Kaj en tagmezo ili palpas, kiel en nokto."],[5,15,"Li savas kontraŭ glavo, Kontraŭ la buŝo kaj mano de potenculo Li savas malriĉulon.","Li savas kontraŭ glavo, Kontraŭ la buŝo kaj mano de potenculo Li savas malriĉulon."],[5,16,"Al la senhavulo aperas espero, Kaj la malboneco fermas sian buŝon.","Al la senhavulo aperas espero, Kaj la malboneco fermas sian buŝon."],[5,17,"Feliĉa estas la homo, kiun punas Dio; Kaj la moralinstruon de la Plejpotenculo ne malŝatu;","Feliĉa estas la homo, kiun punas Dio; Kaj la moralinstruon de la Plejpotenculo ne malŝatu;"],[5,18,"Ĉar Li vundas, sed ankaŭ bandaĝas; Li batas, sed Liaj manoj ankaŭ resanigas.","Ĉar Li vundas, sed ankaŭ bandaĝas; Li batas, sed Liaj manoj ankaŭ resanigas."],[5,19,"En ses malfeliĉoj Li vin savos; En la sepa ne tuŝos vin la malbono.","En ses malfeliĉoj Li vin savos; En la sepa ne tuŝos vin la malbono."],[5,20,"En tempo de malsato Li savos vin de la morto, Kaj en milito el la mano de glavo.","En tempo de malsato Li savos vin de la morto, Kaj en milito el la mano de glavo."],[5,21,"Kontraŭ la vipo de lango vi estos kaŝita; Kaj vi ne timos ruinigon, kiam ĝi venos.","Kontraŭ la vipo de lango vi estos kaŝita; Kaj vi ne timos ruinigon, kiam ĝi venos."],[5,22,"Dum ruinigo kaj malsato vi ridos; Kaj la bestojn de la tero vi ne timos;","Dum ruinigo kaj malsato vi ridos; Kaj la bestojn de la tero vi ne timos;"],[5,23,"Ĉar kun la ŝtonoj de la kampo vi havos interligon, Kaj la bestoj de la kampo havos pacon kun vi.","Ĉar kun la ŝtonoj de la kampo vi havos interligon, Kaj la bestoj de la kampo havos pacon kun vi."],[5,24,"Kaj vi ekscios, ke paco estas en via tendo; Vi esploros vian loĝejon, kaj nenio mankos.","Kaj vi ekscios, ke paco estas en via tendo; Vi esploros vian loĝejon, kaj nenio mankos."],[5,25,"Kaj vi ekscios, ke grandnombra estas via idaro Kaj via naskitaro estas kiel la herbo de la tero.","Kaj vi ekscios, ke grandnombra estas via idaro Kaj via naskitaro estas kiel la herbo de la tero."],[5,26,"En maljuneco vi iros en la tombon, Kiel envenas garbaro en sia tempo.","En maljuneco vi iros en la tombon, Kiel envenas garbaro en sia tempo."],[5,27,"Vidu, ni tion esploris, kaj tiel ĝi estas; Atentu tion, kaj sciu tion.","Vidu, ni tion esploris, kaj tiel ĝi estas; Atentu tion, kaj sciu tion."],[6,1,"Ijob respondis kaj diris:","Ijob respondis kaj diris:"],[6,2,"Se estus pesita mia ĉagreno, Kaj samtempe estus metita sur la pesilon mia suferado,","Se estus pesita mia ĉagreno, Kaj samtempe estus metita sur la pesilon mia suferado,"],[6,3,"Ĝi estus nun pli peza, ol la sablo ĉe la maroj; Pro tio miaj vortoj estas plenaj de plendo.","Ĝi estus nun pli peza, ol la sablo ĉe la maroj; Pro tio miaj vortoj estas plenaj de plendo."],[6,4,"Ĉar la sagoj de la Plejpotenculo estas en mi, Ilian venenon trinkas mia spirito; La teruraĵoj de Dio direktiĝis sur min.","Ĉar la sagoj de la Plejpotenculo estas en mi, Ilian venenon trinkas mia spirito; La teruraĵoj de Dio direktiĝis sur min."],[6,5,"Ĉu krias sovaĝa azeno sur herbo? Ĉu bovo blekas kolere ĉe sia manĝaĵo?","Ĉu krias sovaĝa azeno sur herbo? Ĉu bovo blekas kolere ĉe sia manĝaĵo?"],[6,6,"Ĉu oni manĝas sengustaĵon sen salo? Ĉu havas guston la albumeno de ovo?","Ĉu oni manĝas sengustaĵon sen salo? Ĉu havas guston la albumeno de ovo?"],[6,7,"Kion ne volis tuŝi mia animo, Tio nun estas abomeninde mia manĝaĵo.","Kion ne volis tuŝi mia animo, Tio nun estas abomeninde mia manĝaĵo."],[6,8,"Ho, se mia peto plenumiĝus, Kaj se Dio donus al mi tion, kion mi esperas!","Ho, se mia peto plenumiĝus, Kaj se Dio donus al mi tion, kion mi esperas!"],[6,9,"Ho, se Dio komencus kaj disbatus min, Donus liberecon al Sia mano kaj frakasus min!","Ho, se Dio komencus kaj disbatus min, Donus liberecon al Sia mano kaj frakasus min!"],[6,10,"Tio estus ankoraŭ konsolo por mi; Kaj mi ĝojus, se en la turmento Li ne kompatus, Ĉar mi ne forpuŝis ja la vortojn de la Sanktulo.","Tio estus ankoraŭ konsolo por mi; Kaj mi ĝojus, se en la turmento Li ne kompatus, Ĉar mi ne forpuŝis ja la vortojn de la Sanktulo."],[6,11,"Kio estas mia forto, ke mi persistu? Kaj kia estas mia fino, ke mi havu paciencon?","Kio estas mia forto, ke mi persistu? Kaj kia estas mia fino, ke mi havu paciencon?"],[6,12,"Ĉu mia forto estas forto de ŝtonoj? Ĉu mia karno estas kupro?","Ĉu mia forto estas forto de ŝtonoj? Ĉu mia karno estas kupro?"],[6,13,"Mi havas ja nenian helpon, Kaj savo estas forpuŝita for de mi.","Mi havas ja nenian helpon, Kaj savo estas forpuŝita for de mi."],[6,14,"Al malfeliĉulo decas kompato de amiko, Eĉ se li forlasas la timon antaŭ la Plejpotenculo.","Al malfeliĉulo decas kompato de amiko, Eĉ se li forlasas la timon antaŭ la Plejpotenculo."],[6,15,"Miaj fratoj trompas kiel torento, Kiel akvaj fluegoj, kiuj pasas,","Miaj fratoj trompas kiel torento, Kiel akvaj fluegoj, kiuj pasas,"],[6,16,"Kiuj estas malklaraj pro glacio, En kiuj kaŝas sin neĝo;","Kiuj estas malklaraj pro glacio, En kiuj kaŝas sin neĝo;"],[6,17,"En la tempo de degelo ili malaperas, En la tempo de varmego ili forŝoviĝas de sia loko.","En la tempo de degelo ili malaperas, En la tempo de varmego ili forŝoviĝas de sia loko."],[6,18,"Ili forklinas la direkton de sia vojo, Iras en la dezerton, kaj malaperas.","Ili forklinas la direkton de sia vojo, Iras en la dezerton, kaj malaperas."],[6,19,"Serĉas ilin per sia rigardo la vojoj de Tema, Esperas je ili la karavanoj el Ŝeba;","Serĉas ilin per sia rigardo la vojoj de Tema, Esperas je ili la karavanoj el Ŝeba;"],[6,20,"Sed ili hontas pro sia fido; Ili aliras, kaj ruĝiĝas de honto.","Sed ili hontas pro sia fido; Ili aliras, kaj ruĝiĝas de honto."],[6,21,"Nun vi neniiĝis; Vi ekvidis teruraĵon, kaj ektimis.","Nun vi neniiĝis; Vi ekvidis teruraĵon, kaj ektimis."],[6,22,"Ĉu mi diris: Donu al mi, El via havaĵo donacu pro mi,","Ĉu mi diris: Donu al mi, El via havaĵo donacu pro mi,"],[6,23,"Savu min el la mano de premanto, Aŭ liberigu min el la mano de turmentantoj?","Savu min el la mano de premanto, Aŭ liberigu min el la mano de turmentantoj?"],[6,24,"Instruu min, kaj mi eksilentos; Komprenigu al mi, per kio mi pekis.","Instruu min, kaj mi eksilentos; Komprenigu al mi, per kio mi pekis."],[6,25,"Kial vi mallaŭdas pravajn vortojn? Kaj kion povas instrui la moralinstruanto el vi?","Kial vi mallaŭdas pravajn vortojn? Kaj kion povas instrui la moralinstruanto el vi?"],[6,26,"Ĉu vi intencas riproĉi pro vortoj? Sed paroloj de malesperanto iras al la vento.","Ĉu vi intencas riproĉi pro vortoj? Sed paroloj de malesperanto iras al la vento."],[6,27,"Eĉ orfon vi atakus, Kaj sub via amiko vi fosus.","Eĉ orfon vi atakus, Kaj sub via amiko vi fosus."],[6,28,"Nun, ĉar vi komencis, rigardu min; Ĉu mi mensogos antaŭ via vizaĝo?","Nun, ĉar vi komencis, rigardu min; Ĉu mi mensogos antaŭ via vizaĝo?"],[6,29,"Rigardu denove, vi ne trovos malpiaĵon; Ripetu, vi trovos mian pravecon en la afero.","Rigardu denove, vi ne trovos malpiaĵon; Ripetu, vi trovos mian pravecon en la afero."],[6,30,"Ĉu estas peko sur mia lango? Ĉu mia palato ne komprenas tion, kio estas malbona?","Ĉu estas peko sur mia lango? Ĉu mia palato ne komprenas tion, kio estas malbona?"],[7,1,"Difinita estas ja por la homo la limtempo sur la tero, Kaj liaj tagoj estas kiel la tagoj de dungito.","Difinita estas ja por la homo la limtempo sur la tero, Kaj liaj tagoj estas kiel la tagoj de dungito."],[7,2,"Kiel sklavo, kiu sopiras al ombro, Kaj kiel dungito, kiu atendas sian pagon,","Kiel sklavo, kiu sopiras al ombro, Kaj kiel dungito, kiu atendas sian pagon,"],[7,3,"Tiel mi ricevis sorte monatojn vantajn, Kaj noktoj turmentaj estas nombritaj al mi.","Tiel mi ricevis sorte monatojn vantajn, Kaj noktoj turmentaj estas nombritaj al mi."],[7,4,"Kiam mi kuŝiĝas, mi diras: Kiam mi leviĝos? Sed la vespero fariĝas longa, kaj mi satiĝas de maltrankvileco ĝis la tagiĝo.","Kiam mi kuŝiĝas, mi diras: Kiam mi leviĝos? Sed la vespero fariĝas longa, kaj mi satiĝas de maltrankvileco ĝis la tagiĝo."],[7,5,"Mia korpo estas kovrita de vermoj kaj de pecoj da tero; Mia haŭto krevis kaj putras.","Mia korpo estas kovrita de vermoj kaj de pecoj da tero; Mia haŭto krevis kaj putras."],[7,6,"Miaj tagoj forflugis pli facile, ol bobeno de teksisto, Kaj pasis, lasinte nenian esperon.","Miaj tagoj forflugis pli facile, ol bobeno de teksisto, Kaj pasis, lasinte nenian esperon."],[7,7,"Memoru, ke mia vivo estas bloveto, Ke miaj okuloj ne plu revidos bonon;","Memoru, ke mia vivo estas bloveto, Ke miaj okuloj ne plu revidos bonon;"],[7,8,"Ne plu revidos min okulo de vidanto; Vi volos ekrigardi min, sed mi jam ne ekzistos.","Ne plu revidos min okulo de vidanto; Vi volos ekrigardi min, sed mi jam ne ekzistos."],[7,9,"Nubo pasas kaj foriras; Tiel ne plu revenas tiu, kiu iris en Ŝeolon;","Nubo pasas kaj foriras; Tiel ne plu revenas tiu, kiu iris en Ŝeolon;"],[7,10,"Li ne plu revenas en sian domon; Lia loko ne plu rekonos lin.","Li ne plu revenas en sian domon; Lia loko ne plu rekonos lin."],[7,11,"Tial mi ne detenos mian buŝon; Mi parolos en la premiteco de mia spirito, Mi plendos en la maldolĉeco de mia animo.","Tial mi ne detenos mian buŝon; Mi parolos en la premiteco de mia spirito, Mi plendos en la maldolĉeco de mia animo."],[7,12,"Ĉu mi estas maro aŭ mara monstro, Ke Vi starigis gardon por mi?","Ĉu mi estas maro aŭ mara monstro, Ke Vi starigis gardon por mi?"],[7,13,"Kiam mi pensas, ke mia lito min konsolos, Ke mia kuŝejo plifaciligos mian suferadon,","Kiam mi pensas, ke mia lito min konsolos, Ke mia kuŝejo plifaciligos mian suferadon,"],[7,14,"Tiam Vi teruras min per sonĝoj, Timigas min per vizioj;","Tiam Vi teruras min per sonĝoj, Timigas min per vizioj;"],[7,15,"Kaj mia animo deziras sufokiĝon, Miaj ostoj la morton.","Kaj mia animo deziras sufokiĝon, Miaj ostoj la morton."],[7,16,"Tedis al mi; ne eterne mi vivu; Forlasu min, ĉar miaj tagoj estas vantaĵo.","Tedis al mi; ne eterne mi vivu; Forlasu min, ĉar miaj tagoj estas vantaĵo."],[7,17,"Kio estas homo, ke Vi faras lin granda, Ke Vi zorgas pri li,","Kio estas homo, ke Vi faras lin granda, Ke Vi zorgas pri li,"],[7,18,"Ke Vi rememoras lin ĉiumatene, Elprovas lin ĉiumomente?","Ke Vi rememoras lin ĉiumatene, Elprovas lin ĉiumomente?"],[7,19,"Kial Vi ne deturnas Vin de mi, Ne lasas min libera eĉ tiom, ke mi povu engluti mian salivon?","Kial Vi ne deturnas Vin de mi, Ne lasas min libera eĉ tiom, ke mi povu engluti mian salivon?"],[7,20,"Se mi pekis, kion mi per tio faris al Vi, ho gardanto de la homoj? Kial Vi faris min celo de Viaj atakoj, Ke mi fariĝis ŝarĝo por mi mem?","Se mi pekis, kion mi per tio faris al Vi, ho gardanto de la homoj? Kial Vi faris min celo de Viaj atakoj, Ke mi fariĝis ŝarĝo por mi mem?"],[7,21,"Kaj kial Vi ne deprenas mian pekon, ne pardonas mian malbonagon? Jen mi ja baldaŭ kuŝos en la tero; Kaj kiam Vi morgaŭ serĉos min, mi ne ekzistos.","Kaj kial Vi ne deprenas mian pekon, ne pardonas mian malbonagon? Jen mi ja baldaŭ kuŝos en la tero; Kaj kiam Vi morgaŭ serĉos min, mi ne ekzistos."],[8,1,"Kaj ekparolis Bildad, la Ŝuĥano, kaj diris:","Kaj ekparolis Bildad, la Ŝuĥano, kaj diris:"],[8,2,"Kiel longe vi tiel parolos, Kaj la vortoj de via buŝo estos kiel forta vento?","Kiel longe vi tiel parolos, Kaj la vortoj de via buŝo estos kiel forta vento?"],[8,3,"Ĉu Dio falsas la juĝon? Ĉu la Plejpotenculo falsas la justecon?","Ĉu Dio falsas la juĝon? Ĉu la Plejpotenculo falsas la justecon?"],[8,4,"Se viaj filoj pekis kontraŭ Li, Li forpuŝis ilin pro ilia malbonago.","Se viaj filoj pekis kontraŭ Li, Li forpuŝis ilin pro ilia malbonago."],[8,5,"Se vi serĉas Dion Kaj petegas la Plejpotenculon,","Se vi serĉas Dion Kaj petegas la Plejpotenculon,"],[8,6,"Se vi estas pura kaj pia, Li maldormos super vi, Kaj restarigos la bonstaton en via virta loĝejo.","Se vi estas pura kaj pia, Li maldormos super vi, Kaj restarigos la bonstaton en via virta loĝejo."],[8,7,"Kaj se via komenco estis malgranda, Via estonteco forte kreskos.","Kaj se via komenco estis malgranda, Via estonteco forte kreskos."],[8,8,"Ĉar demandu la antaŭajn generaciojn, Kaj primeditu tion, kion esploris iliaj patroj;","Ĉar demandu la antaŭajn generaciojn, Kaj primeditu tion, kion esploris iliaj patroj;"],[8,9,"Ĉar ni estas de hieraŭ, kaj ni nenion scias; Nia vivo sur la tero estas nur ombro.","Ĉar ni estas de hieraŭ, kaj ni nenion scias; Nia vivo sur la tero estas nur ombro."],[8,10,"Ili instruos vin, diros al vi, Kaj el sia koro elirigos vortojn.","Ili instruos vin, diros al vi, Kaj el sia koro elirigos vortojn."],[8,11,"Ĉu povas kreski kano sen malsekeco? Ĉu kreskas junko sen akvo?","Ĉu povas kreski kano sen malsekeco? Ĉu kreskas junko sen akvo?"],[8,12,"En tia okazo ĝi velksekiĝas pli frue ol ĉiu herbo, Kiam ĝi estas ankoraŭ en sia freŝeco, Kiam ĝi ankoraŭ ne estas detranĉita.","En tia okazo ĝi velksekiĝas pli frue ol ĉiu herbo, Kiam ĝi estas ankoraŭ en sia freŝeco, Kiam ĝi ankoraŭ ne estas detranĉita."],[8,13,"Tiaj estas la vojoj de ĉiuj, kiuj forgesas Dion; Kaj pereas la espero de hipokritulo,","Tiaj estas la vojoj de ĉiuj, kiuj forgesas Dion; Kaj pereas la espero de hipokritulo,"],[8,14,"Kies fido dehakiĝas, Kaj kies espero estas araneaĵo.","Kies fido dehakiĝas, Kaj kies espero estas araneaĵo."],[8,15,"Li apogas sin al sia domo, sed ne restos staranta; Li ekkaptos ĝin, sed ne povos sin teni.","Li apogas sin al sia domo, sed ne restos staranta; Li ekkaptos ĝin, sed ne povos sin teni."],[8,16,"Li estis verda antaŭ la suno, Kaj super lia ĝardeno etendiĝas liaj branĉoj;","Li estis verda antaŭ la suno, Kaj super lia ĝardeno etendiĝas liaj branĉoj;"],[8,17,"Amase plektiĝas liaj radikoj, Inter ŝtonoj ili tenas sin forte;","Amase plektiĝas liaj radikoj, Inter ŝtonoj ili tenas sin forte;"],[8,18,"Sed kiam oni elŝiras lin el lia loko, Ĝi malkonfesas lin: Mi vin ne vidis.","Sed kiam oni elŝiras lin el lia loko, Ĝi malkonfesas lin: Mi vin ne vidis."],[8,19,"Tia estas la ĝojo de lia vivo; Kaj el la tero kreskas aliaj.","Tia estas la ĝojo de lia vivo; Kaj el la tero kreskas aliaj."],[8,20,"Vidu, Dio ne forpuŝas virtulon Kaj ne subtenas la manon de malpiuloj.","Vidu, Dio ne forpuŝas virtulon Kaj ne subtenas la manon de malpiuloj."],[8,21,"Li plenigos ankoraŭ vian buŝon per rido Kaj viajn lipojn per ĝojkrioj.","Li plenigos ankoraŭ vian buŝon per rido Kaj viajn lipojn per ĝojkrioj."],[8,22,"Viaj malamantoj kovriĝos per honto; Sed la tendo de malpiuloj malaperos.","Viaj malamantoj kovriĝos per honto; Sed la tendo de malpiuloj malaperos."],[9,1,"Ijob respondis kaj diris:","Ijob respondis kaj diris:"],[9,2,"Certe, mi scias, ke tiel estas; Kaj kiel povas homo esti prava koncerne Dion?","Certe, mi scias, ke tiel estas; Kaj kiel povas homo esti prava koncerne Dion?"],[9,3,"Se li volus havi kun Li juĝan disputon, Li ne povus respondi al Li eĉ unu kontraŭ mil.","Se li volus havi kun Li juĝan disputon, Li ne povus respondi al Li eĉ unu kontraŭ mil."],[9,4,"Li estas saĝa per Sia koro kaj potenca per Sia forto; Kiu kuraĝus stari kontraŭ Li kaj restus sendifekta?","Li estas saĝa per Sia koro kaj potenca per Sia forto; Kiu kuraĝus stari kontraŭ Li kaj restus sendifekta?"],[9,5,"Li forŝovas montojn, kaj ili eĉ ne rimarkas, Ke Li renversis ilin en Sia kolero;","Li forŝovas montojn, kaj ili eĉ ne rimarkas, Ke Li renversis ilin en Sia kolero;"],[9,6,"Li skuas la teron de ĝia loko, Ke ĝiaj kolonoj tremas;","Li skuas la teron de ĝia loko, Ke ĝiaj kolonoj tremas;"],[9,7,"Li diras al la suno, kaj ĝi ne leviĝas, Kaj la stelojn Li sigelfermas;","Li diras al la suno, kaj ĝi ne leviĝas, Kaj la stelojn Li sigelfermas;"],[9,8,"Li sola etendas la ĉielon, Kaj Li iras sur la altaĵoj de la maro;","Li sola etendas la ĉielon, Kaj Li iras sur la altaĵoj de la maro;"],[9,9,"Li kreis la Grandan Ursinon, Orionon, kaj Plejadojn, Kaj la stelojn de la sudo;","Li kreis la Grandan Ursinon, Orionon, kaj Plejadojn, Kaj la stelojn de la sudo;"],[9,10,"Li faras neesploreblajn grandaĵojn, Kaj nekalkuleblajn mirindaĵojn.","Li faras neesploreblajn grandaĵojn, Kaj nekalkuleblajn mirindaĵojn."],[9,11,"Jen Li preteriros preter mi, kaj mi tion eĉ ne vidos; Li pasos, kaj mi eĉ ne rimarkos Lin.","Jen Li preteriros preter mi, kaj mi tion eĉ ne vidos; Li pasos, kaj mi eĉ ne rimarkos Lin."],[9,12,"Kiam Li kaptas, kiu malpermesus al Li? Kiu dirus al Li: Kion Vi faras?","Kiam Li kaptas, kiu malpermesus al Li? Kiu dirus al Li: Kion Vi faras?"],[9,13,"Li estas Dio, kaj Lian koleron oni ne povas haltigi; Sub Li fleksiĝas la helpantoj de Rahab.","Li estas Dio, kaj Lian koleron oni ne povas haltigi; Sub Li fleksiĝas la helpantoj de Rahab."],[9,14,"Des pli ĉu mi povus respondi al Li, Ĉu mi povus elekti vortojn kontraŭ Li?","Des pli ĉu mi povus respondi al Li, Ĉu mi povus elekti vortojn kontraŭ Li?"],[9,15,"Eĉ se mi estus prava, mi ne respondus; Sed mi nur petegus mian juĝanton.","Eĉ se mi estus prava, mi ne respondus; Sed mi nur petegus mian juĝanton."],[9,16,"Se mi vokus kaj Li respondus, Mi ne kredus, ke Li aŭdis mian voĉon,","Se mi vokus kaj Li respondus, Mi ne kredus, ke Li aŭdis mian voĉon,"],[9,17,"Li, kiu povas frakasi min per ventego Kaj fari al mi senkulpe multe da vundoj.","Li, kiu povas frakasi min per ventego Kaj fari al mi senkulpe multe da vundoj."],[9,18,"Li ne permesas al mi trankviligi mian spiriton, Sed Li satigas min per maldolĉo.","Li ne permesas al mi trankviligi mian spiriton, Sed Li satigas min per maldolĉo."],[9,19,"Se oni volas forton, Li estas potenca; Se oni volas juĝon, kiu alvokos min?","Se oni volas forton, Li estas potenca; Se oni volas juĝon, kiu alvokos min?"],[9,20,"Se mi montros mian pravecon, mia propra buŝo min kondamnos; Se mi montros min virtulo, Li montros min malbonagulo.","Se mi montros mian pravecon, mia propra buŝo min kondamnos; Se mi montros min virtulo, Li montros min malbonagulo."],[9,21,"Mi estas senkulpa; mi ne zorgas pri mia animo, Mi abomenas mian vivon.","Mi estas senkulpa; mi ne zorgas pri mia animo, Mi abomenas mian vivon."],[9,22,"Ĉio estas egala; tial mi diras: Senkulpulon kaj malpiulon Li ambaŭ pereigas.","Ĉio estas egala; tial mi diras: Senkulpulon kaj malpiulon Li ambaŭ pereigas."],[9,23,"Kiam vipo subite ekbatas, Li ridas ĉe la elprovado de senkulpuloj.","Kiam vipo subite ekbatas, Li ridas ĉe la elprovado de senkulpuloj."],[9,24,"La tero estas transdonita en la manon de malpiulo; La vizaĝon de ĝiaj juĝistoj Li kovras. Se ne Li, tiam kiu?","La tero estas transdonita en la manon de malpiulo; La vizaĝon de ĝiaj juĝistoj Li kovras. Se ne Li, tiam kiu?"],[9,25,"Miaj tagoj estis pli rapidpiedaj ol kuristo; Ili forkuris, ne vidis bonon;","Miaj tagoj estis pli rapidpiedaj ol kuristo; Ili forkuris, ne vidis bonon;"],[9,26,"Ili forkuris, kiel ŝipetoj el kano, Kiel aglo flugas al manĝotaĵo.","Ili forkuris, kiel ŝipetoj el kano, Kiel aglo flugas al manĝotaĵo."],[9,27,"Se mi ekpensas: Mi forgesos mian plendon, Mi farlasos mian mienon, kaj mi min gajigos:","Se mi ekpensas: Mi forgesos mian plendon, Mi farlasos mian mienon, kaj mi min gajigos:"],[9,28,"Tiam mi ektremas pro ĉiuj miaj suferoj; Mi scias, ke Vi ne rigardos min kiel senkulpan.","Tiam mi ektremas pro ĉiuj miaj suferoj; Mi scias, ke Vi ne rigardos min kiel senkulpan."],[9,29,"Mi restos ja malprava; Por kio do mi vane min turmentas?","Mi restos ja malprava; Por kio do mi vane min turmentas?"],[9,30,"Se mi lavus min per neĝa akvo Kaj purigus miajn manojn per lesivo,","Se mi lavus min per neĝa akvo Kaj purigus miajn manojn per lesivo,"],[9,31,"Eĉ tiam Vi trempus min en koto, Kaj miaj vestoj min abomenus.","Eĉ tiam Vi trempus min en koto, Kaj miaj vestoj min abomenus."],[9,32,"Ĉar Li ne estas homo simile al mi, Ke mi povu respondi al Li, Ke ni povu ambaŭ iri al juĝo.","Ĉar Li ne estas homo simile al mi, Ke mi povu respondi al Li, Ke ni povu ambaŭ iri al juĝo."],[9,33,"Ne ekzistas inter ni arbitracianto, Kiu povus meti sian manon sur nin ambaŭ.","Ne ekzistas inter ni arbitracianto, Kiu povus meti sian manon sur nin ambaŭ."],[9,34,"Li forigu de mi Sian vergon, Kaj Lia teruro ne timigu min;","Li forigu de mi Sian vergon, Kaj Lia teruro ne timigu min;"],[9,35,"Tiam mi ekparolos, kaj ne timos Lin, Ĉar ne tia mi estas en mi mem.","Tiam mi ekparolos, kaj ne timos Lin, Ĉar ne tia mi estas en mi mem."],[10,1,"Tedis al mia animo mia vivo; Mi fordonos min al mia plendado; Mi parolos en la malĝojeco de mia animo.","Tedis al mia animo mia vivo; Mi fordonos min al mia plendado; Mi parolos en la malĝojeco de mia animo."],[10,2,"Mi diros al Dio: Ne kondamnu min, Sciigu al mi, pro kio Vi malpacas kontraŭ mi.","Mi diros al Dio: Ne kondamnu min, Sciigu al mi, pro kio Vi malpacas kontraŭ mi."],[10,3,"Ĉu Vi trovas tion bona, ke Vi turmentas, Ke Vi forpuŝas la laboritaĵon de Viaj manoj, Sendas brilon sur la entreprenon de malpiuloj?","Ĉu Vi trovas tion bona, ke Vi turmentas, Ke Vi forpuŝas la laboritaĵon de Viaj manoj, Sendas brilon sur la entreprenon de malpiuloj?"],[10,4,"Ĉu Vi havas okulojn karnajn, Kaj ĉu Vi rigardas, kiel homo rigardas?","Ĉu Vi havas okulojn karnajn, Kaj ĉu Vi rigardas, kiel homo rigardas?"],[10,5,"Ĉu Viaj tagoj estas kiel la tagoj de homo, Aŭ ĉu Viaj jaroj estas kiel la vivtempo de homo,","Ĉu Viaj tagoj estas kiel la tagoj de homo, Aŭ ĉu Viaj jaroj estas kiel la vivtempo de homo,"],[10,6,"Ke Vi serĉas mian kulpon Kaj penas trovi mian pekon,","Ke Vi serĉas mian kulpon Kaj penas trovi mian pekon,"],[10,7,"Kvankam Vi scias, ke mi ne estas malbonagulo, Sed el Via mano neniu povas savi?","Kvankam Vi scias, ke mi ne estas malbonagulo, Sed el Via mano neniu povas savi?"],[10,8,"Viaj manoj min formis kaj faris min tutan ĉirkaŭe, Kaj tamen Vi min pereigas!","Viaj manoj min formis kaj faris min tutan ĉirkaŭe, Kaj tamen Vi min pereigas!"],[10,9,"Rememoru, ke kiel argilon Vi min prilaboris; Kaj Vi returne faros min polvo.","Rememoru, ke kiel argilon Vi min prilaboris; Kaj Vi returne faros min polvo."],[10,10,"Vi elverŝis ja min kiel lakton, Kaj kiel fromaĝon Vi min kundensigis.","Vi elverŝis ja min kiel lakton, Kaj kiel fromaĝon Vi min kundensigis."],[10,11,"Per haŭto kaj karno Vi min vestis, Per ostoj kaj tendenoj Vi min plektis.","Per haŭto kaj karno Vi min vestis, Per ostoj kaj tendenoj Vi min plektis."],[10,12,"Vivon kaj bonon Vi donis al mi, Kaj Via prizorgado gardis mian spiriton.","Vivon kaj bonon Vi donis al mi, Kaj Via prizorgado gardis mian spiriton."],[10,13,"Sed ĉi tion Vi kaŝis en Via koro; Mi scias, ke Vi tion intencis:","Sed ĉi tion Vi kaŝis en Via koro; Mi scias, ke Vi tion intencis:"],[10,14,"Se mi pekos, Vi tion rimarkos sur mi, Kaj mian pekon Vi ne lasos senpuna.","Se mi pekos, Vi tion rimarkos sur mi, Kaj mian pekon Vi ne lasos senpuna."],[10,15,"Se mi agis malbone, ve al mi! Se mi estas prava, mi ne povas tamen levi mian kapon, Estante tute humiligita Kaj vidante mian mizeron.","Se mi agis malbone, ve al mi! Se mi estas prava, mi ne povas tamen levi mian kapon, Estante tute humiligita Kaj vidante mian mizeron."],[10,16,"Se ĝi leviĝas, Vi ĉasas min kiel leono, Kaj denove montras sur mi Vian mirindan potencon.","Se ĝi leviĝas, Vi ĉasas min kiel leono, Kaj denove montras sur mi Vian mirindan potencon."],[10,17,"Vi elmetas kontraŭ mi novajn atestojn, Plifortigas Vian koleron kontraŭ mi; Nova armeo min atakas.","Vi elmetas kontraŭ mi novajn atestojn, Plifortigas Vian koleron kontraŭ mi; Nova armeo min atakas."],[10,18,"Por kio Vi elirigis min el la ventro? Ho, se mi estus pereinta, ke nenies okulo min vidu!","Por kio Vi elirigis min el la ventro? Ho, se mi estus pereinta, ke nenies okulo min vidu!"],[10,19,"Tiam mi estus kiel ne estinta; El la ventro mi estus transportita en la tombon.","Tiam mi estus kiel ne estinta; El la ventro mi estus transportita en la tombon."],[10,20,"Mia vivo estas ja mallonga; Ĉesu do, lasu min libera, por ke mi iom revigliĝu,","Mia vivo estas ja mallonga; Ĉesu do, lasu min libera, por ke mi iom revigliĝu,"],[10,21,"Antaŭ ol mi foriros senrevene En la landon de mallumo kaj de morta ombro,","Antaŭ ol mi foriros senrevene En la landon de mallumo kaj de morta ombro,"],[10,22,"En la landon, kie la lumo estas kiel mallumo, Kie estas morta ombro kaj senordeco, Kie estas lume kiel en mallumego.","En la landon, kie la lumo estas kiel mallumo, Kie estas morta ombro kaj senordeco, Kie estas lume kiel en mallumego."],[11,1,"Kaj ekparolis Cofar, la Naamano, kaj diris:","Kaj ekparolis Cofar, la Naamano, kaj diris:"],[11,2,"Ĉu kontraŭ multe da vortoj oni ne povas doni respondon? Kaj ĉu tiu, kiu multe parolas, estas prava?","Ĉu kontraŭ multe da vortoj oni ne povas doni respondon? Kaj ĉu tiu, kiu multe parolas, estas prava?"],[11,3,"Ĉu via senenhava parolado devas silentigi la homojn, Por ke vi mokinsultu kaj neniu vin hontigu?","Ĉu via senenhava parolado devas silentigi la homojn, Por ke vi mokinsultu kaj neniu vin hontigu?"],[11,4,"Vi diras: Mia opinio estas ĝusta, Kaj mi estas pura antaŭ Viaj okuloj.","Vi diras: Mia opinio estas ĝusta, Kaj mi estas pura antaŭ Viaj okuloj."],[11,5,"Sed ho, se Dio ekparolus, Kaj malfermus antaŭ vi Siajn lipojn,","Sed ho, se Dio ekparolus, Kaj malfermus antaŭ vi Siajn lipojn,"],[11,6,"Kaj malkaŝus antaŭ vi la sekretojn de la saĝo, Kiu havas multoblan forton! Sciu, ke ne ĉiujn viajn pekojn Dio rememoras.","Kaj malkaŝus antaŭ vi la sekretojn de la saĝo, Kiu havas multoblan forton! Sciu, ke ne ĉiujn viajn pekojn Dio rememoras."],[11,7,"Ĉu vi povas eltrovi la esencon de Dio? Ĉu vi povas plene kompreni la perfektecon de la Plejpotenculo?","Ĉu vi povas eltrovi la esencon de Dio? Ĉu vi povas plene kompreni la perfektecon de la Plejpotenculo?"],[11,8,"Tio estas pli alta ol la ĉielo; Kion vi povas fari? Tio estas pli profunda ol Ŝeol; Kion vi povas ekscii?","Tio estas pli alta ol la ĉielo; Kion vi povas fari? Tio estas pli profunda ol Ŝeol; Kion vi povas ekscii?"],[11,9,"Pli longa ol la tero estas ĝia mezuro, Kaj pli larĝa ol la maro.","Pli longa ol la tero estas ĝia mezuro, Kaj pli larĝa ol la maro."],[11,10,"Se Li preteriros, kaj fermos, kaj faros juĝon, Tiam kiu repuŝos Lin?","Se Li preteriros, kaj fermos, kaj faros juĝon, Tiam kiu repuŝos Lin?"],[11,11,"Ĉar Li konas la homojn malvirtajn; Li vidas la malbonagojn, kiujn oni ne rimarkas.","Ĉar Li konas la homojn malvirtajn; Li vidas la malbonagojn, kiujn oni ne rimarkas."],[11,12,"Eĉ vanta homo devas kompreni, Eĉ homo, kiu naskiĝis sovaĝulo.","Eĉ vanta homo devas kompreni, Eĉ homo, kiu naskiĝis sovaĝulo."],[11,13,"Se vi aranĝas vian koron Kaj etendas al Li viajn manojn;","Se vi aranĝas vian koron Kaj etendas al Li viajn manojn;"],[11,14,"Se vi forigas la malvirton, kiu estas en via mano, Kaj vi ne permesos al malbonaĵoj resti en via tendo:","Se vi forigas la malvirton, kiu estas en via mano, Kaj vi ne permesos al malbonaĵoj resti en via tendo:"],[11,15,"Tiam vi povos levi vian vizaĝon sen difekto; Vi estos firma kaj ne timos.","Tiam vi povos levi vian vizaĝon sen difekto; Vi estos firma kaj ne timos."],[11,16,"Tiam vi forgesos mizeron; Vi rememoros ĝin kiel forfluintan akvon.","Tiam vi forgesos mizeron; Vi rememoros ĝin kiel forfluintan akvon."],[11,17,"Kaj via vivo leviĝos pli hele ol la tagmezo, La mallumo fariĝos kiel mateno.","Kaj via vivo leviĝos pli hele ol la tagmezo, La mallumo fariĝos kiel mateno."],[11,18,"Kaj vi estos trankvila, ĉar ekzistas espero; Vi rigardos ĉirkaŭen, kaj iros dormi en sendanĝereco.","Kaj vi estos trankvila, ĉar ekzistas espero; Vi rigardos ĉirkaŭen, kaj iros dormi en sendanĝereco."],[11,19,"Vi kuŝos, kaj neniu vin timigos; Kaj multaj serĉos vian favoron.","Vi kuŝos, kaj neniu vin timigos; Kaj multaj serĉos vian favoron."],[11,20,"Sed la okuloj de malpiuloj konsumiĝos, Pereos por ili la rifuĝo, Kaj ilia espero elspiros sian vivon.","Sed la okuloj de malpiuloj konsumiĝos, Pereos por ili la rifuĝo, Kaj ilia espero elspiros sian vivon."],[12,1,"Kaj Ijob respondis kaj diris:","Kaj Ijob respondis kaj diris:"],[12,2,"Certe, vi solaj estas homoj, Kaj kun vi mortos la saĝo.","Certe, vi solaj estas homoj, Kaj kun vi mortos la saĝo."],[12,3,"Mi ankaŭ havas koron, kiel vi; Mi ne estas malpli valora ol vi; Kiu ne povas paroli tiele?","Mi ankaŭ havas koron, kiel vi; Mi ne estas malpli valora ol vi; Kiu ne povas paroli tiele?"],[12,4,"Mi fariĝis mokataĵo por mia amiko, Mi, kiu vokadis al Dio kaj estis aŭskultata; Virtulo kaj senkulpulo fariĝis mokataĵo;","Mi fariĝis mokataĵo por mia amiko, Mi, kiu vokadis al Dio kaj estis aŭskultata; Virtulo kaj senkulpulo fariĝis mokataĵo;"],[12,5,"Malestimata lucerneto li estas antaŭ la pensoj de feliĉuloj, Pretigita por migrantoj.","Malestimata lucerneto li estas antaŭ la pensoj de feliĉuloj, Pretigita por migrantoj."],[12,6,"Bonstataj estas la tendoj de rabistoj, Kaj sendanĝerecon havas la incitantoj de Dio, Tiuj, kiuj portas Dion en sia mano.","Bonstataj estas la tendoj de rabistoj, Kaj sendanĝerecon havas la incitantoj de Dio, Tiuj, kiuj portas Dion en sia mano."],[12,7,"Vere, demandu la brutojn, kaj ili instruos vin; La birdojn de la ĉielo, kaj ili diros al vi;","Vere, demandu la brutojn, kaj ili instruos vin; La birdojn de la ĉielo, kaj ili diros al vi;"],[12,8,"Aŭ parolu kun la tero, kaj ĝi klarigos al vi; Kaj rakontos al vi la fiŝoj de la maro.","Aŭ parolu kun la tero, kaj ĝi klarigos al vi; Kaj rakontos al vi la fiŝoj de la maro."],[12,9,"Kiu ne ekscius el ĉio ĉi tio, Ke la mano de la Eternulo tion faris,","Kiu ne ekscius el ĉio ĉi tio, Ke la mano de la Eternulo tion faris,"],[12,10,"De Tiu, en kies mano estas la animo de ĉio vivanta Kaj la spirito de ĉiu homa karno?","De Tiu, en kies mano estas la animo de ĉio vivanta Kaj la spirito de ĉiu homa karno?"],[12,11,"La orelo esploras ja la parolon, Kaj la palato gustumas al si la manĝaĵon.","La orelo esploras ja la parolon, Kaj la palato gustumas al si la manĝaĵon."],[12,12,"La maljunuloj posedas saĝon, Kaj la grandaĝuloj kompetentecon.","La maljunuloj posedas saĝon, Kaj la grandaĝuloj kompetentecon."],[12,13,"Ĉe Li estas la saĝo kaj la forto; Ĉe Li estas konsilo kaj kompetenteco.","Ĉe Li estas la saĝo kaj la forto; Ĉe Li estas konsilo kaj kompetenteco."],[12,14,"Kion Li detruas, tio ne rekonstruiĝas; Kiun Li enŝlosos, tiu ne liberiĝos.","Kion Li detruas, tio ne rekonstruiĝas; Kiun Li enŝlosos, tiu ne liberiĝos."],[12,15,"Kiam Li digas la akvon, ĝi elsekiĝas; Kiam Li fluigas ĝin, ĝi renversas la teron.","Kiam Li digas la akvon, ĝi elsekiĝas; Kiam Li fluigas ĝin, ĝi renversas la teron."],[12,16,"Ĉe Li estas potenco kaj forto; Lia estas tiu, kiu eraras, kaj tiu, kiu erarigas.","Ĉe Li estas potenco kaj forto; Lia estas tiu, kiu eraras, kaj tiu, kiu erarigas."],[12,17,"Li irigas konsilistojn kiel erarvagantojn, Kaj la juĝistojn Li faras malsaĝaj.","Li irigas konsilistojn kiel erarvagantojn, Kaj la juĝistojn Li faras malsaĝaj."],[12,18,"La ligilojn de reĝoj Li malligas, Kaj Li ligas per zono iliajn lumbojn.","La ligilojn de reĝoj Li malligas, Kaj Li ligas per zono iliajn lumbojn."],[12,19,"Li erarvagigas la pastrojn Kaj faligas la potenculojn.","Li erarvagigas la pastrojn Kaj faligas la potenculojn."],[12,20,"Li mutigas la lipojn de fidinduloj Kaj forprenas de maljunuloj la prudenton.","Li mutigas la lipojn de fidinduloj Kaj forprenas de maljunuloj la prudenton."],[12,21,"Li verŝas honton sur eminentulojn Kaj malfirmigas la zonon de potenculoj.","Li verŝas honton sur eminentulojn Kaj malfirmigas la zonon de potenculoj."],[12,22,"Li malkovras profundaĵon el meze de mallumo, Kaj mortan ombron Li elirigas en la lumon.","Li malkovras profundaĵon el meze de mallumo, Kaj mortan ombron Li elirigas en la lumon."],[12,23,"Li grandigas naciojn kaj pereigas ilin, Disvastigas naciojn kaj forpelas ilin.","Li grandigas naciojn kaj pereigas ilin, Disvastigas naciojn kaj forpelas ilin."],[12,24,"Li senkuraĝigas la ĉefojn de la popolo de la lando Kaj erarvagigas ilin en dezerto senvoja;","Li senkuraĝigas la ĉefojn de la popolo de la lando Kaj erarvagigas ilin en dezerto senvoja;"],[12,25,"Ili palpas en mallumo, en senlumeco; Kaj Li ŝanceliĝigas ilin kiel ebriuloj.","Ili palpas en mallumo, en senlumeco; Kaj Li ŝanceliĝigas ilin kiel ebriuloj."],[13,1,"Ĉion ĉi tion mia okulo vidis, Mia orelo aŭdis kaj komprenis.","Ĉion ĉi tion mia okulo vidis, Mia orelo aŭdis kaj komprenis."],[13,2,"Kion vi scias, mi ankaŭ scias; Kaj mi ne estas malpli valora ol vi.","Kion vi scias, mi ankaŭ scias; Kaj mi ne estas malpli valora ol vi."],[13,3,"Sed mi volus paroli kun la Plejpotenculo, Mi dezirus disputi kun Dio.","Sed mi volus paroli kun la Plejpotenculo, Mi dezirus disputi kun Dio."],[13,4,"Tamen vi komentarias malvere, Vi ĉiuj estas senutilaj kuracistoj.","Tamen vi komentarias malvere, Vi ĉiuj estas senutilaj kuracistoj."],[13,5,"Ho, se vi silentus, Tio estus saĝeco de via flanko.","Ho, se vi silentus, Tio estus saĝeco de via flanko."],[13,6,"Aŭskultu do mian moralinstruon, Kaj atentu la defendan parolon de mia buŝo.","Aŭskultu do mian moralinstruon, Kaj atentu la defendan parolon de mia buŝo."],[13,7,"Ĉu pro Dio vi volas paroli malveron, Kaj pro Li paroli falsaĵon?","Ĉu pro Dio vi volas paroli malveron, Kaj pro Li paroli falsaĵon?"],[13,8,"Ĉu vi volas esti personfavoraj al Li, Aŭ pro Dio vi volas disputi?","Ĉu vi volas esti personfavoraj al Li, Aŭ pro Dio vi volas disputi?"],[13,9,"Ĉu estos bone, kiam Li esploros vin? Ĉu vi volas trompi Lin, kiel oni trompas homon?","Ĉu estos bone, kiam Li esploros vin? Ĉu vi volas trompi Lin, kiel oni trompas homon?"],[13,10,"Li certe vin punos, Se vi sekrete estos personfavoraj.","Li certe vin punos, Se vi sekrete estos personfavoraj."],[13,11,"Ĉu Lia majesto ne konfuzas vin? Ĉu ne falas sur vin timo antaŭ Li?","Ĉu Lia majesto ne konfuzas vin? Ĉu ne falas sur vin timo antaŭ Li?"],[13,12,"Viaj memorigoj estas sentencoj polvaj, Via bastionoj estas amasoj da argilo.","Viaj memorigoj estas sentencoj polvaj, Via bastionoj estas amasoj da argilo."],[13,13,"Silentu antaŭ mi, kaj parolos mi, Kio ajn trafos min.","Silentu antaŭ mi, kaj parolos mi, Kio ajn trafos min."],[13,14,"Por kio mi portu mian karnon en miaj dentoj Kaj metu mian animon en mian manon?","Por kio mi portu mian karnon en miaj dentoj Kaj metu mian animon en mian manon?"],[13,15,"Li ja mortigos min, kaj mi ne havas esperon; Sed pri mia konduto mi volas disputi antaŭ Li.","Li ja mortigos min, kaj mi ne havas esperon; Sed pri mia konduto mi volas disputi antaŭ Li."],[13,16,"Tio jam estos savo por mi, Ĉar ne hipokritulo venos antaŭ Lin.","Tio jam estos savo por mi, Ĉar ne hipokritulo venos antaŭ Lin."],[13,17,"Aŭskultu mian parolon Kaj mian klarigon antaŭ viaj oreloj.","Aŭskultu mian parolon Kaj mian klarigon antaŭ viaj oreloj."],[13,18,"Jen mi pretigis juĝan aferon; Mi scias, ke mi montriĝos prava.","Jen mi pretigis juĝan aferon; Mi scias, ke mi montriĝos prava."],[13,19,"Kiu povas procesi kontraŭ mi? Tiam mi eksilentus kaj mortus.","Kiu povas procesi kontraŭ mi? Tiam mi eksilentus kaj mortus."],[13,20,"Nur du aferojn ne faru al mi, Tiam mi ne kaŝos min antaŭ Via vizaĝo:","Nur du aferojn ne faru al mi, Tiam mi ne kaŝos min antaŭ Via vizaĝo:"],[13,21,"Malproksimigu de mi Vian manon, Kaj Via teruro ne timigu min.","Malproksimigu de mi Vian manon, Kaj Via teruro ne timigu min."],[13,22,"Tiam voku, kaj mi respondos; Aŭ mi parolos, kaj Vi respondu al mi.","Tiam voku, kaj mi respondos; Aŭ mi parolos, kaj Vi respondu al mi."],[13,23,"Kiom da malbonagoj kaj pekoj estas sur mi? Sciigu al mi miajn krimojn kaj pekojn.","Kiom da malbonagoj kaj pekoj estas sur mi? Sciigu al mi miajn krimojn kaj pekojn."],[13,24,"Kial Vi kaŝas Vian vizaĝon Kaj rigardas min kiel Vian malamikon?","Kial Vi kaŝas Vian vizaĝon Kaj rigardas min kiel Vian malamikon?"],[13,25,"Ĉu Vi volas montri Vian forton kontraŭ deŝirita folio? Kaj ĉu sekiĝintan pajleron Vi volas persekuti?","Ĉu Vi volas montri Vian forton kontraŭ deŝirita folio? Kaj ĉu sekiĝintan pajleron Vi volas persekuti?"],[13,26,"Ĉar Vi skribas kontraŭ mi maldolĉaĵon Kaj venigas sur min la pekojn de mia juneco.","Ĉar Vi skribas kontraŭ mi maldolĉaĵon Kaj venigas sur min la pekojn de mia juneco."],[13,27,"Vi metis miajn piedojn en ŝtipon, Vi observas ĉiujn miajn vojojn, Kaj Vi observas la plandojn de miaj piedoj;","Vi metis miajn piedojn en ŝtipon, Vi observas ĉiujn miajn vojojn, Kaj Vi observas la plandojn de miaj piedoj;"],[13,28,"Dum mi ja disfalas kiel putraĵo, Kiel vesto dismanĝita de tineoj.","Dum mi ja disfalas kiel putraĵo, Kiel vesto dismanĝita de tineoj."],[14,1,"Homo, naskita de virino, Havas mallongan vivon kaj abundon da afliktoj.","Homo, naskita de virino, Havas mallongan vivon kaj abundon da afliktoj."],[14,2,"Kiel floro li elkreskas kaj velkas; Li forkuras kiel ombro kaj ne restas.","Kiel floro li elkreskas kaj velkas; Li forkuras kiel ombro kaj ne restas."],[14,3,"Kaj kontraŭ tia Vi malfermas Viajn okulojn, Kaj min Vi vokas al juĝo kun Vi!","Kaj kontraŭ tia Vi malfermas Viajn okulojn, Kaj min Vi vokas al juĝo kun Vi!"],[14,4,"Ĉu povas purulo deveni de malpurulo? Neniu.","Ĉu povas purulo deveni de malpurulo? Neniu."],[14,5,"Se liaj tagoj estas difinitaj, la nombro de liaj monatoj estas ĉe Vi; Vi difinis lian limon, kiun li ne transpasos.","Se liaj tagoj estas difinitaj, la nombro de liaj monatoj estas ĉe Vi; Vi difinis lian limon, kiun li ne transpasos."],[14,6,"Deturnu do Vin de li, ke li estu trankvila, Ĝis venos lia tempo, kiun li sopiras kiel dungito.","Deturnu do Vin de li, ke li estu trankvila, Ĝis venos lia tempo, kiun li sopiras kiel dungito."],[14,7,"Arbo havas esperon, se ĝi estas dehakita, ke ĝi denove ŝanĝiĝos, Kaj ĝi ne ĉesos kreskigi branĉojn.","Arbo havas esperon, se ĝi estas dehakita, ke ĝi denove ŝanĝiĝos, Kaj ĝi ne ĉesos kreskigi branĉojn."],[14,8,"Se ĝia radiko maljuniĝis en la tero, Kaj ĝia trunko mortas en polvo,","Se ĝia radiko maljuniĝis en la tero, Kaj ĝia trunko mortas en polvo,"],[14,9,"Tamen, eksentinte la odoron de akvo, ĝi denove verdiĝas, Kaj kreskas plue, kvazaŭ ĵus plantita.","Tamen, eksentinte la odoron de akvo, ĝi denove verdiĝas, Kaj kreskas plue, kvazaŭ ĵus plantita."],[14,10,"Sed homo mortas kaj malaperas; Kiam la homo finiĝis, kie li estas?","Sed homo mortas kaj malaperas; Kiam la homo finiĝis, kie li estas?"],[14,11,"Forfluas la akvo el lago, Kaj rivero elĉerpiĝas kaj elsekiĝas:","Forfluas la akvo el lago, Kaj rivero elĉerpiĝas kaj elsekiĝas:"],[14,12,"Tiel homo kuŝiĝas, kaj ne plu leviĝas; Tiel longe, kiel la ĉielo ekzistas, ili ne plu vekiĝos, Nek revigliĝos el sia dormado.","Tiel homo kuŝiĝas, kaj ne plu leviĝas; Tiel longe, kiel la ĉielo ekzistas, ili ne plu vekiĝos, Nek revigliĝos el sia dormado."],[14,13,"Ho, se Vi kaŝus min en Ŝeol, Se Vi kaŝus min ĝis la momento, kiam pasos Via kolero, Se Vi difinus por mi templimon kaj poste rememorus min!","Ho, se Vi kaŝus min en Ŝeol, Se Vi kaŝus min ĝis la momento, kiam pasos Via kolero, Se Vi difinus por mi templimon kaj poste rememorus min!"],[14,14,"Kiam homo mortas, ĉu li poste povas reviviĝi? Dum la tuta tempo de mia batalado mi atendus, Ĝi venos mia forŝanĝo.","Kiam homo mortas, ĉu li poste povas reviviĝi? Dum la tuta tempo de mia batalado mi atendus, Ĝi venos mia forŝanĝo."],[14,15,"Vi vokus, kaj mi respondus al Vi; Vi ekdezirus la faritaĵon de Viaj manoj.","Vi vokus, kaj mi respondus al Vi; Vi ekdezirus la faritaĵon de Viaj manoj."],[14,16,"Nun Vi kalkulas miajn paŝojn; Ne konservu mian pekon;","Nun Vi kalkulas miajn paŝojn; Ne konservu mian pekon;"],[14,17,"Sigelu en paketo miajn malbonagojn, Kaj kovru mian kulpon.","Sigelu en paketo miajn malbonagojn, Kaj kovru mian kulpon."],[14,18,"Sed monto, kiu falas, malaperas; Kaj roko forŝoviĝas de sia loko;","Sed monto, kiu falas, malaperas; Kaj roko forŝoviĝas de sia loko;"],[14,19,"Ŝtonojn forlavas la akvo, Kaj ĝia disverŝiĝo fordronigas la polvon de la tero: Tiel Vi pereigas la esperon de homo.","Ŝtonojn forlavas la akvo, Kaj ĝia disverŝiĝo fordronigas la polvon de la tero: Tiel Vi pereigas la esperon de homo."],[14,20,"Vi premas lin ĝis fino, kaj li foriras; Li ŝanĝas sian vizaĝon, kaj Vi forigas lin.","Vi premas lin ĝis fino, kaj li foriras; Li ŝanĝas sian vizaĝon, kaj Vi forigas lin."],[14,21,"Se liaj infanoj estas honorataj, li tion ne scias; Se ili estas humiligataj, li tion ne rimarkas.","Se liaj infanoj estas honorataj, li tion ne scias; Se ili estas humiligataj, li tion ne rimarkas."],[14,22,"Nur lia propra korpo lin doloras, Nur pri sia propra animo li suferas.","Nur lia propra korpo lin doloras, Nur pri sia propra animo li suferas."],[15,1,"Ekparolis Elifaz, la Temanano, kaj diris:","Ekparolis Elifaz, la Temanano, kaj diris:"],[15,2,"Ĉu saĝulo povas respondi per ventaj opinioj, Kaj plenigi sian ventron per sensencaĵoj?","Ĉu saĝulo povas respondi per ventaj opinioj, Kaj plenigi sian ventron per sensencaĵoj?"],[15,3,"Vi disputas per vortoj senutilaj, Kaj per paroloj, kiuj nenion helpas.","Vi disputas per vortoj senutilaj, Kaj per paroloj, kiuj nenion helpas."],[15,4,"Vi forigas la timon, Kaj senvalorigas preĝon antaŭ Dio.","Vi forigas la timon, Kaj senvalorigas preĝon antaŭ Dio."],[15,5,"Ĉar via malbonago instigas vian buŝon, Kaj vi elektis stilon de maliculoj.","Ĉar via malbonago instigas vian buŝon, Kaj vi elektis stilon de maliculoj."],[15,6,"Vin kondamnas via buŝo, ne mi; Kaj viaj lipoj atestas kontraŭ vi.","Vin kondamnas via buŝo, ne mi; Kaj viaj lipoj atestas kontraŭ vi."],[15,7,"Ĉu vi naskiĝis la unua homo? Ĉu vi estas kreita pli frue ol la altaĵoj?","Ĉu vi naskiĝis la unua homo? Ĉu vi estas kreita pli frue ol la altaĵoj?"],[15,8,"Ĉu vi aŭdis la sekretan decidon de Dio, Kaj alkaptis al vi la saĝon?","Ĉu vi aŭdis la sekretan decidon de Dio, Kaj alkaptis al vi la saĝon?"],[15,9,"Kion vi scias tian, kion ni ne scias? Kion vi komprenas tian, kio al ni mankas?","Kion vi scias tian, kion ni ne scias? Kion vi komprenas tian, kio al ni mankas?"],[15,10,"Inter ni estas grizuloj kaj maljunuloj, Kiuj vivis pli longe ol via patro.","Inter ni estas grizuloj kaj maljunuloj, Kiuj vivis pli longe ol via patro."],[15,11,"Ĉu tiel malmulte valoras por vi la konsoloj de Dio Kaj vorto kvieta?","Ĉu tiel malmulte valoras por vi la konsoloj de Dio Kaj vorto kvieta?"],[15,12,"Kial vin tiel levas via koro, Kaj kial tiel palpebrumas viaj okuloj,","Kial vin tiel levas via koro, Kaj kial tiel palpebrumas viaj okuloj,"],[15,13,"Ke vi direktas kontraŭ Dion vian koleron, Kaj elirigis el via buŝo tiajn vortojn?","Ke vi direktas kontraŭ Dion vian koleron, Kaj elirigis el via buŝo tiajn vortojn?"],[15,14,"Kio estas homo, ke li povus esti pura Kaj ke naskito de virino povus esti prava?","Kio estas homo, ke li povus esti pura Kaj ke naskito de virino povus esti prava?"],[15,15,"Vidu, inter Liaj sanktuloj ne ĉiuj estas fidindaj, Kaj la ĉielo ne estas pura en Liaj okuloj:","Vidu, inter Liaj sanktuloj ne ĉiuj estas fidindaj, Kaj la ĉielo ne estas pura en Liaj okuloj:"],[15,16,"Des pli homo, abomeninda kaj malbona, Kiu trinkas malbonagojn kiel akvon.","Des pli homo, abomeninda kaj malbona, Kiu trinkas malbonagojn kiel akvon."],[15,17,"Mi montros al vi, aŭskultu min; Kaj kion mi vidis, tion mi rakontos,","Mi montros al vi, aŭskultu min; Kaj kion mi vidis, tion mi rakontos,"],[15,18,"Kion saĝuloj diris kaj ne kaŝis antaŭ siaj patroj,","Kion saĝuloj diris kaj ne kaŝis antaŭ siaj patroj,"],[15,19,"Al kiuj, al ili solaj, estis donita la tero, Kaj fremdulo ne trairis meze de ili:","Al kiuj, al ili solaj, estis donita la tero, Kaj fremdulo ne trairis meze de ili:"],[15,20,"Dum sia tuta vivo malpiulo estas maltrankvila, Kaj la nombro de la jaroj de tirano estas kaŝita antaŭ li;","Dum sia tuta vivo malpiulo estas maltrankvila, Kaj la nombro de la jaroj de tirano estas kaŝita antaŭ li;"],[15,21,"Teruroj sonas en liaj oreloj; Meze de paco venas sur lin rabisto.","Teruroj sonas en liaj oreloj; Meze de paco venas sur lin rabisto."],[15,22,"Li ne esperas, ke li saviĝos el mallumo; Kaj li serĉas ĉirkaŭe glavon.","Li ne esperas, ke li saviĝos el mallumo; Kaj li serĉas ĉirkaŭe glavon."],[15,23,"Li vagadas, serĉante panon; Li scias, ke preta estas en lia mano la tago de mallumo.","Li vagadas, serĉante panon; Li scias, ke preta estas en lia mano la tago de mallumo."],[15,24,"Teruras lin mizero kaj premateco, Venkobatas lin kiel reĝo, pretiĝinta por batalo;","Teruras lin mizero kaj premateco, Venkobatas lin kiel reĝo, pretiĝinta por batalo;"],[15,25,"Pro tio, ke li etendis sian manon kontraŭ Dion Kaj kontraŭstaris al la Plejpotenculo,","Pro tio, ke li etendis sian manon kontraŭ Dion Kaj kontraŭstaris al la Plejpotenculo,"],[15,26,"Kuris kontraŭ Lin kun fiera kolo, Kun dikaj dorsoj de siaj ŝildoj.","Kuris kontraŭ Lin kun fiera kolo, Kun dikaj dorsoj de siaj ŝildoj."],[15,27,"Li kovris sian vizaĝon per graso Kaj metis sebon sur siajn lumbojn.","Li kovris sian vizaĝon per graso Kaj metis sebon sur siajn lumbojn."],[15,28,"Li loĝas en urboj ruinigitaj, En domoj ne loĝataj, Destinitaj esti ŝtonamasoj.","Li loĝas en urboj ruinigitaj, En domoj ne loĝataj, Destinitaj esti ŝtonamasoj."],[15,29,"Li ne restos riĉa, lia bonstato ne teniĝos, Kaj lia havaĵo ne disvastiĝos sur la tero.","Li ne restos riĉa, lia bonstato ne teniĝos, Kaj lia havaĵo ne disvastiĝos sur la tero."],[15,30,"Li ne forkliniĝos de mallumo; Flamo velksekigos liajn branĉojn, Kaj Li forigos lin per la blovo de Sia buŝo.","Li ne forkliniĝos de mallumo; Flamo velksekigos liajn branĉojn, Kaj Li forigos lin per la blovo de Sia buŝo."],[15,31,"La erarinto ne fidu vantaĵon, Ĉar vanta estos lia rekompenco.","La erarinto ne fidu vantaĵon, Ĉar vanta estos lia rekompenco."],[15,32,"Antaŭtempe li finiĝos, Kaj lia branĉo ne estos verda.","Antaŭtempe li finiĝos, Kaj lia branĉo ne estos verda."],[15,33,"Lia nematura bero estos deŝirita, kiel ĉe vinbertrunko; Kaj lia floro defalos, kiel ĉe olivarbo.","Lia nematura bero estos deŝirita, kiel ĉe vinbertrunko; Kaj lia floro defalos, kiel ĉe olivarbo."],[15,34,"Ĉar la anaro de la hipokrituloj senhomiĝos; Kaj fajro ekstermos la tendojn de tiuj, kiuj prenas subaĉeton.","Ĉar la anaro de la hipokrituloj senhomiĝos; Kaj fajro ekstermos la tendojn de tiuj, kiuj prenas subaĉeton."],[15,35,"Ili gravediĝis per malpiaĵo kaj naskis pekon, Kaj ilia ventro pretigas malicaĵon.","Ili gravediĝis per malpiaĵo kaj naskis pekon, Kaj ilia ventro pretigas malicaĵon."],[16,1,"Ijob respondis kaj diris:","Ijob respondis kaj diris:"],[16,2,"Mi aŭdis multe da similaj aferoj; Tedaj konsolantoj vi ĉiuj estas.","Mi aŭdis multe da similaj aferoj; Tedaj konsolantoj vi ĉiuj estas."],[16,3,"Ĉu estos fino al la ventaj vortoj? Kaj kio vin incitis, ke vi tiel parolas?","Ĉu estos fino al la ventaj vortoj? Kaj kio vin incitis, ke vi tiel parolas?"],[16,4,"Mi ankaŭ povus paroli, kiel vi. Se vi estus sur mia loko, Mi konsolus vin per vortoj Kaj balancus pri vi mian kapon.","Mi ankaŭ povus paroli, kiel vi. Se vi estus sur mia loko, Mi konsolus vin per vortoj Kaj balancus pri vi mian kapon."],[16,5,"Mi fortigus vin per mia buŝo Kaj konsolus vin per paroloj de miaj lipoj.","Mi fortigus vin per mia buŝo Kaj konsolus vin per paroloj de miaj lipoj."],[16,6,"Se mi parolos, mia doloro ne kvietiĝos; Se mi ĉesos, kio foriros de mi?","Se mi parolos, mia doloro ne kvietiĝos; Se mi ĉesos, kio foriros de mi?"],[16,7,"Sed nun Li lacigis min, Li detruis mian tutan esencon.","Sed nun Li lacigis min, Li detruis mian tutan esencon."],[16,8,"Vi faris al mi sulkojn, tio fariĝis atesto; Mia senfortiĝo staras antaŭ mia vizaĝo, kaj parolas.","Vi faris al mi sulkojn, tio fariĝis atesto; Mia senfortiĝo staras antaŭ mia vizaĝo, kaj parolas."],[16,9,"Lia kolero disŝiras; Mia malamanto grincigas kontraŭ mi siajn dentojn; Mia premanto briligas kontraŭ mi siajn okulojn.","Lia kolero disŝiras; Mia malamanto grincigas kontraŭ mi siajn dentojn; Mia premanto briligas kontraŭ mi siajn okulojn."],[16,10,"Ili malfermegis kontraŭ mi sian buŝon, insulte batas min sur la vangojn; Ĉiuj kune kontentigis sur mi sian koleron.","Ili malfermegis kontraŭ mi sian buŝon, insulte batas min sur la vangojn; Ĉiuj kune kontentigis sur mi sian koleron."],[16,11,"Dio transdonis min al maljustulo, Ĵetis min en la manojn de malbonuloj.","Dio transdonis min al maljustulo, Ĵetis min en la manojn de malbonuloj."],[16,12,"Mi estis trankvila; sed Li frakasis min, Li kaptis min je la kolo, disbatis min, Kaj Li faris min por Si celo.","Mi estis trankvila; sed Li frakasis min, Li kaptis min je la kolo, disbatis min, Kaj Li faris min por Si celo."],[16,13,"Liaj pafistoj min ĉirkaŭis; Li dishakas miajn internaĵojn kaj ne kompatas, Li elverŝas sur la teron mian galon.","Liaj pafistoj min ĉirkaŭis; Li dishakas miajn internaĵojn kaj ne kompatas, Li elverŝas sur la teron mian galon."],[16,14,"Li faras en mi breĉon post breĉo, Li kuras kontraŭ min kiel batalisto.","Li faras en mi breĉon post breĉo, Li kuras kontraŭ min kiel batalisto."],[16,15,"Sakaĵon mi kudris sur mian korpon, Kaj en polvo mi kaŝis mian kornon.","Sakaĵon mi kudris sur mian korpon, Kaj en polvo mi kaŝis mian kornon."],[16,16,"Mia vizaĝo ŝvelis de plorado, Kaj sur miaj palpebroj estas morta ombro;","Mia vizaĝo ŝvelis de plorado, Kaj sur miaj palpebroj estas morta ombro;"],[16,17,"Kvankam ne troviĝas perfortaĵo en miaj manoj, Kaj mia preĝo estas pura.","Kvankam ne troviĝas perfortaĵo en miaj manoj, Kaj mia preĝo estas pura."],[16,18,"Ho tero, ne kovru mian sangon, Kaj mia kriado ne trovu haltejon.","Ho tero, ne kovru mian sangon, Kaj mia kriado ne trovu haltejon."],[16,19,"Vidu, en la ĉielo estas mia atestanto, Kaj mia konanto estas en la altaj sferoj.","Vidu, en la ĉielo estas mia atestanto, Kaj mia konanto estas en la altaj sferoj."],[16,20,"Parolistoj estas por mi miaj amikoj; Sed mia okulo larmas al Dio,","Parolistoj estas por mi miaj amikoj; Sed mia okulo larmas al Dio,"],[16,21,"Ke Li decidu inter homo kaj Dio, Inter homo kaj lia amiko.","Ke Li decidu inter homo kaj Dio, Inter homo kaj lia amiko."],[16,22,"Ĉar la nombro de la jaroj pasos, Kaj mi iros sur vojon nereveneblan.","Ĉar la nombro de la jaroj pasos, Kaj mi iros sur vojon nereveneblan."],[17,1,"Mia spirito senfortiĝis, miaj tagoj mallongiĝis, Tomboj estas antaŭ mi.","Mia spirito senfortiĝis, miaj tagoj mallongiĝis, Tomboj estas antaŭ mi."],[17,2,"Mokado min ĉirkaŭas; En aflikto pro tio restas mia okulo.","Mokado min ĉirkaŭas; En aflikto pro tio restas mia okulo."],[17,3,"Estu Vi mem mia garantianto antaŭ Vi; Alie kiu donos la manon pro mi?","Estu Vi mem mia garantianto antaŭ Vi; Alie kiu donos la manon pro mi?"],[17,4,"Ĉar ilian koron Vi kovris kontraŭ prudento; Tial Vi ne donos al ili triumfon.","Ĉar ilian koron Vi kovris kontraŭ prudento; Tial Vi ne donos al ili triumfon."],[17,5,"Se iu fanfaronas antaŭ siaj amikoj pri sia parto, La okuloj de liaj infanoj konsumiĝos.","Se iu fanfaronas antaŭ siaj amikoj pri sia parto, La okuloj de liaj infanoj konsumiĝos."],[17,6,"Li faris min proverbo por la popoloj; Kaj mi fariĝis homo, al kiu oni kraĉas en la vizaĝon.","Li faris min proverbo por la popoloj; Kaj mi fariĝis homo, al kiu oni kraĉas en la vizaĝon."],[17,7,"Mia okulo mallumiĝis de ĉagreno, Kaj ĉiuj miaj membroj fariĝis kiel ombro.","Mia okulo mallumiĝis de ĉagreno, Kaj ĉiuj miaj membroj fariĝis kiel ombro."],[17,8,"La justuloj eksentos teruron pro tio, Kaj la senkulpulo ekscitiĝos kontraŭ la hipokritulo.","La justuloj eksentos teruron pro tio, Kaj la senkulpulo ekscitiĝos kontraŭ la hipokritulo."],[17,9,"Tamen la virtulo forte konservos sian vojon, Kaj la purmanulo pli firmiĝos.","Tamen la virtulo forte konservos sian vojon, Kaj la purmanulo pli firmiĝos."],[17,10,"Kaj kiom ajn vi ĉiuj revenos, Mi ne trovos inter vi saĝulon.","Kaj kiom ajn vi ĉiuj revenos, Mi ne trovos inter vi saĝulon."],[17,11,"Miaj tagoj forpasis, pereis miaj intencoj, Kiujn havis mia koro.","Miaj tagoj forpasis, pereis miaj intencoj, Kiujn havis mia koro."],[17,12,"La nokton ili volas fari tago, La lumon alproksimigi al la mallumo.","La nokton ili volas fari tago, La lumon alproksimigi al la mallumo."],[17,13,"Se mi atendas, tamen Ŝeol estas mia domo, En la mallumo estas pretigita mia lito.","Se mi atendas, tamen Ŝeol estas mia domo, En la mallumo estas pretigita mia lito."],[17,14,"Al la kavo mi diras: Vi estas mia patro; La vermojn mi nomas mia patrino kaj mia fratino.","Al la kavo mi diras: Vi estas mia patro; La vermojn mi nomas mia patrino kaj mia fratino."],[17,15,"Kion mi devas atendi? Kiu atentos mian esperon?","Kion mi devas atendi? Kiu atentos mian esperon?"],[17,16,"En la profundon de Ŝeol ĝi malsupreniros, Ni ambaŭ kune kuŝos en la polvo.","En la profundon de Ŝeol ĝi malsupreniros, Ni ambaŭ kune kuŝos en la polvo."],[18,1,"Ekparolis Bildad, la Ŝuĥano, kaj diris:","Ekparolis Bildad, la Ŝuĥano, kaj diris:"],[18,2,"Kiam vi ĉesos ĵetadi vortojn? Pripensu, kaj poste ni parolos.","Kiam vi ĉesos ĵetadi vortojn? Pripensu, kaj poste ni parolos."],[18,3,"Kial ni estu rigardataj kiel brutoj, Kaj ni estu malpuruloj en viaj okuloj?","Kial ni estu rigardataj kiel brutoj, Kaj ni estu malpuruloj en viaj okuloj?"],[18,4,"Ho vi, kiu disŝiras sian animon en sia kolero, Ĉu por vi estu forlasata la tero, Kaj roko forŝoviĝu de sia loko?","Ho vi, kiu disŝiras sian animon en sia kolero, Ĉu por vi estu forlasata la tero, Kaj roko forŝoviĝu de sia loko?"],[18,5,"La lumo de la malpiulo estingiĝos, Kaj ne brilos la flamo de lia fajro.","La lumo de la malpiulo estingiĝos, Kaj ne brilos la flamo de lia fajro."],[18,6,"La lumo mallumiĝos en lia tendo, Kaj lia lucerno super li estingiĝos.","La lumo mallumiĝos en lia tendo, Kaj lia lucerno super li estingiĝos."],[18,7,"Mallongiĝos liaj fortaj paŝoj, Kaj lia propra intenco lin faligos.","Mallongiĝos liaj fortaj paŝoj, Kaj lia propra intenco lin faligos."],[18,8,"Ĉar li trafis per siaj piedoj en reton, Kaj li moviĝas en kaptilo.","Ĉar li trafis per siaj piedoj en reton, Kaj li moviĝas en kaptilo."],[18,9,"La maŝo enkroĉigos lian kalkanon, Kaj pereo lin atakos.","La maŝo enkroĉigos lian kalkanon, Kaj pereo lin atakos."],[18,10,"Kaŝita en la tero estas lia falilo, Kaj kaptiloj kontraŭ li estas sur la vojo.","Kaŝita en la tero estas lia falilo, Kaj kaptiloj kontraŭ li estas sur la vojo."],[18,11,"De ĉiuj flankoj timigos lin teruroj Kaj atakos liajn piedojn.","De ĉiuj flankoj timigos lin teruroj Kaj atakos liajn piedojn."],[18,12,"Malsato konsumos lian forton, Kaj pereo estas preparita por liaj flankoj.","Malsato konsumos lian forton, Kaj pereo estas preparita por liaj flankoj."],[18,13,"Konsumiĝos la membroj de lia korpo, Liajn membrojn konsumos la unuenaskito de la morto.","Konsumiĝos la membroj de lia korpo, Liajn membrojn konsumos la unuenaskito de la morto."],[18,14,"Lia espero estos elŝirita el lia tendo, Kaj ĝi pelos lin al la reĝo de teruroj.","Lia espero estos elŝirita el lia tendo, Kaj ĝi pelos lin al la reĝo de teruroj."],[18,15,"Nenio restos en lia tendo; Sur lian loĝejon ŝutiĝos sulfuro.","Nenio restos en lia tendo; Sur lian loĝejon ŝutiĝos sulfuro."],[18,16,"Malsupre sekiĝos liaj radikoj, Kaj supre detranĉiĝos liaj branĉoj.","Malsupre sekiĝos liaj radikoj, Kaj supre detranĉiĝos liaj branĉoj."],[18,17,"La memoro pri li malaperos de sur la tero, Kaj sur la stratoj li ne havos nomon.","La memoro pri li malaperos de sur la tero, Kaj sur la stratoj li ne havos nomon."],[18,18,"Li estos elpelita el lumo en mallumon, Kaj el la mondo li estos elpuŝita.","Li estos elpelita el lumo en mallumon, Kaj el la mondo li estos elpuŝita."],[18,19,"Nek filon nek nepon li havos en sia popolo, Kaj neniu restos ĉe li en lia loĝloko.","Nek filon nek nepon li havos en sia popolo, Kaj neniu restos ĉe li en lia loĝloko."],[18,20,"La posteuloj sentos teruron pri lia tago, Kaj la antaŭulojn kaptos timo.","La posteuloj sentos teruron pri lia tago, Kaj la antaŭulojn kaptos timo."],[18,21,"Tia estas la loĝejo de maljustulo, Kaj tia estas la loko de tiu, kiu ne konas Dion.","Tia estas la loĝejo de maljustulo, Kaj tia estas la loko de tiu, kiu ne konas Dion."],[19,1,"Ijob respondis kaj diris:","Ijob respondis kaj diris:"],[19,2,"Ĝis kiam vi afliktados mian animon Kaj turmentados min per paroloj?","Ĝis kiam vi afliktados mian animon Kaj turmentados min per paroloj?"],[19,3,"Jen jam dek fojojn vi malhonoras min; Vi ne hontas premi min.","Jen jam dek fojojn vi malhonoras min; Vi ne hontas premi min."],[19,4,"Se mi efektive eraris, Mia eraro restos ĉe mi.","Se mi efektive eraris, Mia eraro restos ĉe mi."],[19,5,"Se efektive vi volas montri vin pli grandaj ol mi, Kaj vi riproĉas al mi hontindaĵon,","Se efektive vi volas montri vin pli grandaj ol mi, Kaj vi riproĉas al mi hontindaĵon,"],[19,6,"Tiam sciu, ke Dio faris al mi maljustaĵon, Kaj ĉirkaŭis min per Sia reto.","Tiam sciu, ke Dio faris al mi maljustaĵon, Kaj ĉirkaŭis min per Sia reto."],[19,7,"Jen mi krias pri maljusteco, sed mi ne ricevas respondon; Mi vokas, sed mi ne ricevas juĝon.","Jen mi krias pri maljusteco, sed mi ne ricevas respondon; Mi vokas, sed mi ne ricevas juĝon."],[19,8,"Mian vojon Li baris, ke mi ne povas transiri, Kaj sur mian irejon Li metis mallumon.","Mian vojon Li baris, ke mi ne povas transiri, Kaj sur mian irejon Li metis mallumon."],[19,9,"Mian honoron Li detiris de mi, Kaj deprenis la kronon de mia kapo.","Mian honoron Li detiris de mi, Kaj deprenis la kronon de mia kapo."],[19,10,"Li disbatis min ĉirkaŭe tiel, ke mi pereas; Mian esperon Li elŝiris kiel arbon.","Li disbatis min ĉirkaŭe tiel, ke mi pereas; Mian esperon Li elŝiris kiel arbon."],[19,11,"Ekflamis kontraŭ mi Lia kolero, Kaj Li rigardas min kiel Lian malamikon.","Ekflamis kontraŭ mi Lia kolero, Kaj Li rigardas min kiel Lian malamikon."],[19,12,"Kune venis Liaj taĉmentoj, kaj ebenigis kontraŭ mi sian vojon Kaj stariĝis sieĝe ĉirkaŭ mia tendo.","Kune venis Liaj taĉmentoj, kaj ebenigis kontraŭ mi sian vojon Kaj stariĝis sieĝe ĉirkaŭ mia tendo."],[19,13,"Miajn fratojn Li malproksimigis de mi, Kaj miaj konatoj forfremdiĝis de mi.","Miajn fratojn Li malproksimigis de mi, Kaj miaj konatoj forfremdiĝis de mi."],[19,14,"Miaj parencoj fortiriĝis, Kaj miaj konantoj forgesis min.","Miaj parencoj fortiriĝis, Kaj miaj konantoj forgesis min."],[19,15,"La loĝantoj de mia domo kaj miaj servistinoj rigardas min kiel fremdulon; En iliaj okuloj mi fariĝis aligentulo.","La loĝantoj de mia domo kaj miaj servistinoj rigardas min kiel fremdulon; En iliaj okuloj mi fariĝis aligentulo."],[19,16,"Mian sklavon mi vokas, kaj li ne respondas; Per mia buŝo mi devas petegi lin.","Mian sklavon mi vokas, kaj li ne respondas; Per mia buŝo mi devas petegi lin."],[19,17,"Mia spiro fariĝis abomenata por mia edzino, Kaj mia petado por la filoj de mia ventro.","Mia spiro fariĝis abomenata por mia edzino, Kaj mia petado por la filoj de mia ventro."],[19,18,"Eĉ la malgrandaj infanoj malestimas min; Kiam mi leviĝas, ili parolas kontraŭ mi.","Eĉ la malgrandaj infanoj malestimas min; Kiam mi leviĝas, ili parolas kontraŭ mi."],[19,19,"Abomenas min ĉiuj miaj intimuloj; Kaj tiuj, kiujn mi amis, turnis sin kontraŭ mi.","Abomenas min ĉiuj miaj intimuloj; Kaj tiuj, kiujn mi amis, turnis sin kontraŭ mi."],[19,20,"Kun mia haŭto kaj kun mia karno kunkreskis miaj ostoj, Mi restis nur kun haŭto sur miaj dentoj.","Kun mia haŭto kaj kun mia karno kunkreskis miaj ostoj, Mi restis nur kun haŭto sur miaj dentoj."],[19,21,"Kompatu min, kompatu min, miaj amikoj; Ĉar la mano de Dio frapis min.","Kompatu min, kompatu min, miaj amikoj; Ĉar la mano de Dio frapis min."],[19,22,"Kial vi persekutas min, kiel Dio, Kaj ne povas satiĝi de mia karno?","Kial vi persekutas min, kiel Dio, Kaj ne povas satiĝi de mia karno?"],[19,23,"Ho, se miaj vortoj estus enskribitaj, Ho, se ili estus gravuritaj en libro,","Ho, se miaj vortoj estus enskribitaj, Ho, se ili estus gravuritaj en libro,"],[19,24,"Per fera skribilo kun plumbo, Gravuritaj por eterne sur roko!","Per fera skribilo kun plumbo, Gravuritaj por eterne sur roko!"],[19,25,"Sed mi scias, ke mia Liberigonto vivas, Kaj fine Li leviĝos super la polvo.","Sed mi scias, ke mia Liberigonto vivas, Kaj fine Li leviĝos super la polvo."],[19,26,"Kaj post kiam mia haŭto estos tiel detruita Kaj mi estos senkorpa, mi vidos Dion;","Kaj post kiam mia haŭto estos tiel detruita Kaj mi estos senkorpa, mi vidos Dion;"],[19,27,"Lin vidos mi, kaj miaj okuloj vidos, ne fremdaj; Pri tio sopiregas mia interno en mia brusto.","Lin vidos mi, kaj miaj okuloj vidos, ne fremdaj; Pri tio sopiregas mia interno en mia brusto."],[19,28,"Se vi diros: Kiel ni lin persekutu, Kaj ni trovu kontraŭ li la radikon de la afero,","Se vi diros: Kiel ni lin persekutu, Kaj ni trovu kontraŭ li la radikon de la afero,"],[19,29,"Tiam timu glavon; Ĉar furioza estas la glavo kontraŭ malbonagoj, Por ke vi sciu, ke ekzistas juĝo.","Tiam timu glavon; Ĉar furioza estas la glavo kontraŭ malbonagoj, Por ke vi sciu, ke ekzistas juĝo."],[20,1,"Ekparolis Cofar, la Naamano, kaj diris:","Ekparolis Cofar, la Naamano, kaj diris:"],[20,2,"Pro tio miaj pensoj devigas min respondi, Pro tio, kion mi sentas.","Pro tio miaj pensoj devigas min respondi, Pro tio, kion mi sentas."],[20,3,"Hontindan riproĉon mi aŭdis, Kaj la spirito de mia prudento respondos por mi.","Hontindan riproĉon mi aŭdis, Kaj la spirito de mia prudento respondos por mi."],[20,4,"Ĉu vi scias, ke tiel estis de eterne, De post la apero de homo sur la tero,","Ĉu vi scias, ke tiel estis de eterne, De post la apero de homo sur la tero,"],[20,5,"Ke la triumfado de malvirtuloj estas mallongatempa, Kaj la ĝojo de hipokritulo estas nur momenta?","Ke la triumfado de malvirtuloj estas mallongatempa, Kaj la ĝojo de hipokritulo estas nur momenta?"],[20,6,"Se lia grandeco eĉ atingus ĝis la ĉielo, Kaj lia kapo tuŝus la nubon,","Se lia grandeco eĉ atingus ĝis la ĉielo, Kaj lia kapo tuŝus la nubon,"],[20,7,"Li tamen pereos por ĉiam, kiel lia sterko; Tiuj, kiuj lin vidis, diros: Kie li estas?","Li tamen pereos por ĉiam, kiel lia sterko; Tiuj, kiuj lin vidis, diros: Kie li estas?"],[20,8,"Kiel sonĝo li forflugos, kaj oni lin ne trovos; Li malaperos, kiel nokta vizio.","Kiel sonĝo li forflugos, kaj oni lin ne trovos; Li malaperos, kiel nokta vizio."],[20,9,"Okulo, kiu rigardis lin, ne plu vidos lin; Lia loko lin ne plu vidos.","Okulo, kiu rigardis lin, ne plu vidos lin; Lia loko lin ne plu vidos."],[20,10,"Liaj filoj kurados almozpetante, Kaj liaj manoj redonos lian havaĵon.","Liaj filoj kurados almozpetante, Kaj liaj manoj redonos lian havaĵon."],[20,11,"Liaj ostoj estos punitaj pro la pekoj de lia juneco, Kaj tio kuŝiĝos kune kun li en la polvo.","Liaj ostoj estos punitaj pro la pekoj de lia juneco, Kaj tio kuŝiĝos kune kun li en la polvo."],[20,12,"Se la malbono estas dolĉa en lia buŝo, Li kaŝas ĝin sub sia lango,","Se la malbono estas dolĉa en lia buŝo, Li kaŝas ĝin sub sia lango,"],[20,13,"Li flegas ĝin kaj ne forlasas ĝin, Kaj retenas ĝin sur sia palato:","Li flegas ĝin kaj ne forlasas ĝin, Kaj retenas ĝin sur sia palato:"],[20,14,"Tiam lia manĝaĵo renversiĝos en liaj internaĵoj, Fariĝos galo de aspidoj interne de li.","Tiam lia manĝaĵo renversiĝos en liaj internaĵoj, Fariĝos galo de aspidoj interne de li."],[20,15,"Li englutis havaĵon, sed li ĝin elvomos; El lia ventro Dio ĝin elpelos.","Li englutis havaĵon, sed li ĝin elvomos; El lia ventro Dio ĝin elpelos."],[20,16,"Venenon de aspidoj li suĉos; Lango de vipuro lin mortigos.","Venenon de aspidoj li suĉos; Lango de vipuro lin mortigos."],[20,17,"Li ne vidos fluojn nek riverojn, Torentojn de mielo kaj de butero.","Li ne vidos fluojn nek riverojn, Torentojn de mielo kaj de butero."],[20,18,"Li redonos tion, kion li pene akiris, kaj li tion ne englutos; Kiel ajn granda estas lia havaĵo, li ĝin fordonos kaj ne ĝuos ĝin.","Li redonos tion, kion li pene akiris, kaj li tion ne englutos; Kiel ajn granda estas lia havaĵo, li ĝin fordonos kaj ne ĝuos ĝin."],[20,19,"Ĉar li premis kaj forlasis la senhavulojn, Li rabis al si domon, kiun li ne konstruis.","Ĉar li premis kaj forlasis la senhavulojn, Li rabis al si domon, kiun li ne konstruis."],[20,20,"Ĉar lia interno ne estis trankvila, Tial li ne savos tion, kio estis por li kara.","Ĉar lia interno ne estis trankvila, Tial li ne savos tion, kio estis por li kara."],[20,21,"Nenion restigis lia manĝemeco; Tial lia bonstato ne estos longedaŭra.","Nenion restigis lia manĝemeco; Tial lia bonstato ne estos longedaŭra."],[20,22,"Malgraŭ lia abundeco, li estos premata; Ĉiaspecaj suferoj trafos lin.","Malgraŭ lia abundeco, li estos premata; Ĉiaspecaj suferoj trafos lin."],[20,23,"Por plenigi lian ventron, Li sendos sur lin la flamon de Sia kolero, Kaj pluvigos sur lin Sian furiozon.","Por plenigi lian ventron, Li sendos sur lin la flamon de Sia kolero, Kaj pluvigos sur lin Sian furiozon."],[20,24,"Se li forkuros de batalilo fera, Trafos lin pafarko kupra.","Se li forkuros de batalilo fera, Trafos lin pafarko kupra."],[20,25,"Nudigita glavo trairos lian korpon, Kaj la fulmo de lia turmentilo venos sur lin kun teruro.","Nudigita glavo trairos lian korpon, Kaj la fulmo de lia turmentilo venos sur lin kun teruro."],[20,26,"Nenia mallumo povos kaŝi liajn trezorojn; Lin konsumos fajro ne disblovata; Malbone estos al tiu, kiu restos en lia tendo.","Nenia mallumo povos kaŝi liajn trezorojn; Lin konsumos fajro ne disblovata; Malbone estos al tiu, kiu restos en lia tendo."],[20,27,"La ĉielo malkovros liajn malbonagojn, Kaj la tero leviĝos kontraŭ lin.","La ĉielo malkovros liajn malbonagojn, Kaj la tero leviĝos kontraŭ lin."],[20,28,"Malaperos la greno el lia domo, Disŝutita ĝi estos en la tago de Lia kolero.","Malaperos la greno el lia domo, Disŝutita ĝi estos en la tago de Lia kolero."],[20,29,"Tia estas de Dio la sorto de homo malpia, Kaj la heredaĵo destinita por li de Dio.","Tia estas de Dio la sorto de homo malpia, Kaj la heredaĵo destinita por li de Dio."],[21,1,"Ijob respondis kaj diris:","Ijob respondis kaj diris:"],[21,2,"Aŭskultu mian parolon; Kaj ĝi estu anstataŭ viaj konsoloj.","Aŭskultu mian parolon; Kaj ĝi estu anstataŭ viaj konsoloj."],[21,3,"Toleru, ke mi parolu; Kaj kiam mi finos mian paroladon, tiam moku.","Toleru, ke mi parolu; Kaj kiam mi finos mian paroladon, tiam moku."],[21,4,"Ĉu kontraŭ homo mi disputas? Kaj kial mi ne estu malpacienca?","Ĉu kontraŭ homo mi disputas? Kaj kial mi ne estu malpacienca?"],[21,5,"Turnu vin al mi, kaj vi eksentos teruron, Kaj vi metos la manon sur la buŝon.","Turnu vin al mi, kaj vi eksentos teruron, Kaj vi metos la manon sur la buŝon."],[21,6,"Kiam mi ekpensas pri tio, min atakas teruro, Kaj tremo kaptas mian korpon.","Kiam mi ekpensas pri tio, min atakas teruro, Kaj tremo kaptas mian korpon."],[21,7,"Kial malpiuloj vivas, Atingas maljunecon, akiras grandan havaĵon?","Kial malpiuloj vivas, Atingas maljunecon, akiras grandan havaĵon?"],[21,8,"Ilia idaro estas bone aranĝita antaŭ ili, kune kun ili, Kaj ilia devenantaro estas antaŭ iliaj okuloj.","Ilia idaro estas bone aranĝita antaŭ ili, kune kun ili, Kaj ilia devenantaro estas antaŭ iliaj okuloj."],[21,9,"Iliaj domoj estas en paco, sen timo; Kaj la vergo de Dio ne estas sur ili.","Iliaj domoj estas en paco, sen timo; Kaj la vergo de Dio ne estas sur ili."],[21,10,"Ilia bovo naskigas kaj ne estas forpuŝata; Ilia bovino gravediĝas kaj ne abortas.","Ilia bovo naskigas kaj ne estas forpuŝata; Ilia bovino gravediĝas kaj ne abortas."],[21,11,"Siajn malgrandajn infanojn ili elirigas kiel ŝafaron, Kaj iliaj knaboj saltas.","Siajn malgrandajn infanojn ili elirigas kiel ŝafaron, Kaj iliaj knaboj saltas."],[21,12,"Ili ĝojkrias sub la sonoj de tamburino kaj harpo, Ili estas gajaj sub la sonoj de fluto.","Ili ĝojkrias sub la sonoj de tamburino kaj harpo, Ili estas gajaj sub la sonoj de fluto."],[21,13,"Ili pasigas siajn tagojn en bonstato, Kaj iras en Ŝeolon momente.","Ili pasigas siajn tagojn en bonstato, Kaj iras en Ŝeolon momente."],[21,14,"Kaj tamen ili diras al Dio: Foriru de ni, Ni ne deziras koni Viajn vojojn;","Kaj tamen ili diras al Dio: Foriru de ni, Ni ne deziras koni Viajn vojojn;"],[21,15,"Kio estas la Plejpotenculo, ke ni servu al Li? Kaj kian utilon ni havos, se ni turnos nin al Li?","Kio estas la Plejpotenculo, ke ni servu al Li? Kaj kian utilon ni havos, se ni turnos nin al Li?"],[21,16,"Sed ne de ili dependas ilia bonstato; La pensmaniero de la malpiuloj estas malproksima de mi.","Sed ne de ili dependas ilia bonstato; La pensmaniero de la malpiuloj estas malproksima de mi."],[21,17,"Ĝis kiam? La lumilo de la malpiuloj estingiĝu, Kaj ilia pereo venu sur ilin; Suferojn Li partodonu al ili en Sia kolero.","Ĝis kiam? La lumilo de la malpiuloj estingiĝu, Kaj ilia pereo venu sur ilin; Suferojn Li partodonu al ili en Sia kolero."],[21,18,"Ili estu kiel pajlero antaŭ vento, Kaj kiel grenventumaĵo, kiun forportas ventego.","Ili estu kiel pajlero antaŭ vento, Kaj kiel grenventumaĵo, kiun forportas ventego."],[21,19,"Dio konservas lian malfeliĉon por liaj infanoj; Li repagu al li mem, ke li sciu;","Dio konservas lian malfeliĉon por liaj infanoj; Li repagu al li mem, ke li sciu;"],[21,20,"Liaj propraj okuloj vidu lian malfeliĉon, Kaj el la kolero de la Plejpotenculo li trinku.","Liaj propraj okuloj vidu lian malfeliĉon, Kaj el la kolero de la Plejpotenculo li trinku."],[21,21,"Ĉar kiom interesas lin lia domo post li, Kiam la nombro de liaj monatoj finiĝis?","Ĉar kiom interesas lin lia domo post li, Kiam la nombro de liaj monatoj finiĝis?"],[21,22,"Ĉu oni povas instrui scion al Dio, Kiu juĝas ja plej altajn?","Ĉu oni povas instrui scion al Dio, Kiu juĝas ja plej altajn?"],[21,23,"Unu mortas meze de sia abundeco, Tute trankvila kaj kontenta;","Unu mortas meze de sia abundeco, Tute trankvila kaj kontenta;"],[21,24,"Lia brusto estas plena de lakto, Kaj liaj ostoj estas saturitaj de medolo.","Lia brusto estas plena de lakto, Kaj liaj ostoj estas saturitaj de medolo."],[21,25,"Alia mortas kun animo suferanta, Kaj li ne ĝuis bonon.","Alia mortas kun animo suferanta, Kaj li ne ĝuis bonon."],[21,26,"Sed ambaŭ kune ili kuŝas en la tero, Kaj vermoj ilin kovras.","Sed ambaŭ kune ili kuŝas en la tero, Kaj vermoj ilin kovras."],[21,27,"Vidu, mi scias viajn pensojn, Kaj la argumentojn, kiujn vi malice kolektas kontraŭ mi;","Vidu, mi scias viajn pensojn, Kaj la argumentojn, kiujn vi malice kolektas kontraŭ mi;"],[21,28,"Vi diros: Kie estas la domo de la nobelo? Kaj kie estas la tendo, en kiu loĝis la malpiuloj?","Vi diros: Kie estas la domo de la nobelo? Kaj kie estas la tendo, en kiu loĝis la malpiuloj?"],[21,29,"Sed demandu la vojaĝantojn, Kaj ne malatentu iliajn atestojn:","Sed demandu la vojaĝantojn, Kaj ne malatentu iliajn atestojn:"],[21,30,"En tago de malfeliĉo la malpiulo estas ŝirmata, En tago de kolero li estas metata flanken.","En tago de malfeliĉo la malpiulo estas ŝirmata, En tago de kolero li estas metata flanken."],[21,31,"Kiu montros antaŭ lia vizaĝo lian konduton? Kiu repagos al li, se li ion faris?","Kiu montros antaŭ lia vizaĝo lian konduton? Kiu repagos al li, se li ion faris?"],[21,32,"Kaj li estas akompanata al la tomboj, Kaj sur la tomba altaĵeto estas starigataj gardistoj.","Kaj li estas akompanata al la tomboj, Kaj sur la tomba altaĵeto estas starigataj gardistoj."],[21,33,"Dolĉaj estas por li la terbuloj de la valo, Kaj post li treniĝas ĉiuj homoj, Kaj sennombraj estas tiuj, kiuj iris antaŭ li.","Dolĉaj estas por li la terbuloj de la valo, Kaj post li treniĝas ĉiuj homoj, Kaj sennombraj estas tiuj, kiuj iris antaŭ li."],[21,34,"Kiel do vi volas konsoli min per vantaĵo, Kaj viaj respondoj enhavas nur malĝustaĵojn?","Kiel do vi volas konsoli min per vantaĵo, Kaj viaj respondoj enhavas nur malĝustaĵojn?"],[22,1,"Ekparolis Elifaz, la Temanano, kaj diris:","Ekparolis Elifaz, la Temanano, kaj diris:"],[22,2,"Ĉu Dion povas instrui homo? Ĉu povas Lin instrui eĉ saĝulo?","Ĉu Dion povas instrui homo? Ĉu povas Lin instrui eĉ saĝulo?"],[22,3,"Ĉu por la Plejpotenculo tio estas utila, se vi estas virta? Kaj ĉu Li havas profiton de tio, se via konduto estas pia?","Ĉu por la Plejpotenculo tio estas utila, se vi estas virta? Kaj ĉu Li havas profiton de tio, se via konduto estas pia?"],[22,4,"Ĉu pro timo antaŭ vi Li disputos kun vi, Iros kun vi al juĝo?","Ĉu pro timo antaŭ vi Li disputos kun vi, Iros kun vi al juĝo?"],[22,5,"Via malvirteco estas ja granda, Kaj viaj malbonagoj ne havas finon.","Via malvirteco estas ja granda, Kaj viaj malbonagoj ne havas finon."],[22,6,"Vi prenis de viaj fratoj garantiaĵon vane, De preskaŭ-nuduloj vi deprenis la vestojn;","Vi prenis de viaj fratoj garantiaĵon vane, De preskaŭ-nuduloj vi deprenis la vestojn;"],[22,7,"Al laculo vi ne donis akvon por trinki, Kaj al malsatulo vi rifuzis panon;","Al laculo vi ne donis akvon por trinki, Kaj al malsatulo vi rifuzis panon;"],[22,8,"Per forta brako vi akiris teron, Kaj dank' al eminenteco vi loĝis sur ĝi;","Per forta brako vi akiris teron, Kaj dank' al eminenteco vi loĝis sur ĝi;"],[22,9,"Vidvinojn vi foririgis kun nenio, Kaj la brakojn de orfoj vi frakasis.","Vidvinojn vi foririgis kun nenio, Kaj la brakojn de orfoj vi frakasis."],[22,10,"Pro tio ĉirkaŭe de vi estas kaptiloj, Kaj subita teruro vin timigas.","Pro tio ĉirkaŭe de vi estas kaptiloj, Kaj subita teruro vin timigas."],[22,11,"Aŭ pro mallumo vi nenion vidas, Kaj multego da akvo vin kovris?","Aŭ pro mallumo vi nenion vidas, Kaj multego da akvo vin kovris?"],[22,12,"Ĉu ne estas Dio tie alte en la ĉielo? Rigardu la stelojn, kiel alte ili estas.","Ĉu ne estas Dio tie alte en la ĉielo? Rigardu la stelojn, kiel alte ili estas."],[22,13,"Kaj vi diras: Kion scias Dio? Ĉu Li povas juĝi en mallumo?","Kaj vi diras: Kion scias Dio? Ĉu Li povas juĝi en mallumo?"],[22,14,"La nuboj kovras Lin, kaj Li ne vidas; Kaj Li nur rondiras en la rondo de la ĉielo.","La nuboj kovras Lin, kaj Li ne vidas; Kaj Li nur rondiras en la rondo de la ĉielo."],[22,15,"Ĉu vi konservas la vojon antikvan, Kiun iradis homoj malpiaj,","Ĉu vi konservas la vojon antikvan, Kiun iradis homoj malpiaj,"],[22,16,"Kiuj estis kaptitaj antaŭtempe, Kaj kies grundo disverŝiĝis kiel rivero,","Kiuj estis kaptitaj antaŭtempe, Kaj kies grundo disverŝiĝis kiel rivero,"],[22,17,"Kiuj parolis al Dio: Foriru de ni! Kion povas fari al ni la Plejpotenculo?","Kiuj parolis al Dio: Foriru de ni! Kion povas fari al ni la Plejpotenculo?"],[22,18,"Kvankam Li plenigis iliajn domojn per bonaĵo. Sed la pensmaniero de malvirtuloj estas malproksima de mi.","Kvankam Li plenigis iliajn domojn per bonaĵo. Sed la pensmaniero de malvirtuloj estas malproksima de mi."],[22,19,"La virtuloj vidos kaj ĝojos; La senkulpulo mokos ilin:","La virtuloj vidos kaj ĝojos; La senkulpulo mokos ilin:"],[22,20,"Certe malaperis nia kontraŭulo, Kaj kio restis, tion ekstermis fajro.","Certe malaperis nia kontraŭulo, Kaj kio restis, tion ekstermis fajro."],[22,21,"Interkonsentu do kun Li, kaj vi havos pacon; Per tio venos al vi bono.","Interkonsentu do kun Li, kaj vi havos pacon; Per tio venos al vi bono."],[22,22,"Prenu el Lia buŝo instruon, Kaj metu Liajn vortojn en vian koron.","Prenu el Lia buŝo instruon, Kaj metu Liajn vortojn en vian koron."],[22,23,"Se vi revenos al la Plejpotenculo, vi estos konstruita; Forigu malpiaĵon el via tendo.","Se vi revenos al la Plejpotenculo, vi estos konstruita; Forigu malpiaĵon el via tendo."],[22,24,"Ĵetu en la polvon la multekostan metalon, Kaj la Ofiran oron sur la ŝtonojn de la torentoj;","Ĵetu en la polvon la multekostan metalon, Kaj la Ofiran oron sur la ŝtonojn de la torentoj;"],[22,25,"Tiam la Plejpotenculo estos via oro kaj via brilanta arĝento;","Tiam la Plejpotenculo estos via oro kaj via brilanta arĝento;"],[22,26,"Ĉar tiam vi havos vian plezuron en la Plejpotenculo, Kaj vi levos al Dio vian vizaĝon;","Ĉar tiam vi havos vian plezuron en la Plejpotenculo, Kaj vi levos al Dio vian vizaĝon;"],[22,27,"Vi preĝos al Li, kaj Li vin aŭskultos; Kaj viajn sanktajn promesojn vi plenumos;","Vi preĝos al Li, kaj Li vin aŭskultos; Kaj viajn sanktajn promesojn vi plenumos;"],[22,28,"Se vi ion decidos, ĝi plenumiĝos ĉe vi; Kaj super viaj vojoj brilos lumo.","Se vi ion decidos, ĝi plenumiĝos ĉe vi; Kaj super viaj vojoj brilos lumo."],[22,29,"Ĉar tiujn, kiuj humiliĝis, Li altigos; Kaj kiu mallevas la okulojn, tiu estos savita.","Ĉar tiujn, kiuj humiliĝis, Li altigos; Kaj kiu mallevas la okulojn, tiu estos savita."],[22,30,"Ankaŭ tiun, kiu ne estis senkulpa, Li savos; Tia estos savita pro la pureco de viaj manoj.","Ankaŭ tiun, kiu ne estis senkulpa, Li savos; Tia estos savita pro la pureco de viaj manoj."],[23,1,"Ijob respondis kaj diris:","Ijob respondis kaj diris:"],[23,2,"Eĉ hodiaŭ mia parolado restas maldolĉa; Mia suferado estas pli peza, ol miaj ĝemoj.","Eĉ hodiaŭ mia parolado restas maldolĉa; Mia suferado estas pli peza, ol miaj ĝemoj."],[23,3,"Ho, se mi scius, kiamaniere mi povas Lin trovi, Veni al Lia trono!","Ho, se mi scius, kiamaniere mi povas Lin trovi, Veni al Lia trono!"],[23,4,"Mi prezentus al Li juĝan aferon, Kaj mian buŝon mi plenigus per argumentoj.","Mi prezentus al Li juĝan aferon, Kaj mian buŝon mi plenigus per argumentoj."],[23,5,"Mi ekscius la vortojn, kiujn Li respondus al mi; Mi komprenus, kion Li dirus al mi.","Mi ekscius la vortojn, kiujn Li respondus al mi; Mi komprenus, kion Li dirus al mi."],[23,6,"Ĉu en la grandeco de Sia forto Li luktus kontraŭ mi? Ne, Li nur atentu min;","Ĉu en la grandeco de Sia forto Li luktus kontraŭ mi? Ne, Li nur atentu min;"],[23,7,"Tiam pravulo procesus kun Li, Kaj mi liberiĝus por ĉiam de mia Juĝanto.","Tiam pravulo procesus kun Li, Kaj mi liberiĝus por ĉiam de mia Juĝanto."],[23,8,"Sed jen mi iras antaŭen, kaj Li tie ne estas; Mi iras malantaŭen, kaj mi Lin ne rimarkas;","Sed jen mi iras antaŭen, kaj Li tie ne estas; Mi iras malantaŭen, kaj mi Lin ne rimarkas;"],[23,9,"Se Li faras ion maldekstre, mi Lin ne trovas; Se Li kaŝas Sin dekstre, mi Lin ne vidas.","Se Li faras ion maldekstre, mi Lin ne trovas; Se Li kaŝas Sin dekstre, mi Lin ne vidas."],[23,10,"Sed mian vojon Li konas; Se Li min elprovos, mi eliros kiel oro.","Sed mian vojon Li konas; Se Li min elprovos, mi eliros kiel oro."],[23,11,"Sur Lia irejo forte teniĝas mia piedo; Lian vojon mi konservis, kaj ne forkliniĝis.","Sur Lia irejo forte teniĝas mia piedo; Lian vojon mi konservis, kaj ne forkliniĝis."],[23,12,"Mi ne deturnas min de la ordonoj de Liaj lipoj; Pli ol mian propran leĝon mi konservis la dirojn de Lia buŝo.","Mi ne deturnas min de la ordonoj de Liaj lipoj; Pli ol mian propran leĝon mi konservis la dirojn de Lia buŝo."],[23,13,"Sed Li estas sola: kiu kontraŭstaros al Li? Kion Lia animo deziras, tion Li faras.","Sed Li estas sola: kiu kontraŭstaros al Li? Kion Lia animo deziras, tion Li faras."],[23,14,"Kio estas destinita por mi, tion Li plenumos; Kaj Li havas multe da similaj aferoj.","Kio estas destinita por mi, tion Li plenumos; Kaj Li havas multe da similaj aferoj."],[23,15,"Tial mi tremas antaŭ Lia vizaĝo, Mi primeditas, kaj mi timas Lin.","Tial mi tremas antaŭ Lia vizaĝo, Mi primeditas, kaj mi timas Lin."],[23,16,"Dio senkuraĝigis mian koron, Kaj la Plejpotenculo min konfuzis.","Dio senkuraĝigis mian koron, Kaj la Plejpotenculo min konfuzis."],[23,17,"Ĉar mi ne estas neniigita antaŭ la mallumo, Kaj antaŭ mia vizaĝo Li ne kovris la mallumon.","Ĉar mi ne estas neniigita antaŭ la mallumo, Kaj antaŭ mia vizaĝo Li ne kovris la mallumon."],[24,1,"Kial la Plejpotenculo ne destinis tempojn, Kaj Liaj konantoj ne vidas Liajn tagojn?","Kial la Plejpotenculo ne destinis tempojn, Kaj Liaj konantoj ne vidas Liajn tagojn?"],[24,2,"Oni forŝovas la limojn; Oni rabas la ŝafaron kaj paŝtas ĝin.","Oni forŝovas la limojn; Oni rabas la ŝafaron kaj paŝtas ĝin."],[24,3,"Oni forkondukas la azenon de orfoj, Oni prenas kiel garantiaĵon la bovon de vidvino.","Oni forkondukas la azenon de orfoj, Oni prenas kiel garantiaĵon la bovon de vidvino."],[24,4,"Oni forpuŝas malriĉulojn de la vojo; La suferantoj sur la tero devas sin kaŝi.","Oni forpuŝas malriĉulojn de la vojo; La suferantoj sur la tero devas sin kaŝi."],[24,5,"Jen kiel sovaĝaj azenoj ili eliras al sia laboro, por serĉi kaptaĵon; La stepo donas al ili panon por iliaj infanoj.","Jen kiel sovaĝaj azenoj ili eliras al sia laboro, por serĉi kaptaĵon; La stepo donas al ili panon por iliaj infanoj."],[24,6,"Sur fremda kampo ili rikoltas, Kaj en vinberĝardeno de malpiulo ili kolektas berojn.","Sur fremda kampo ili rikoltas, Kaj en vinberĝardeno de malpiulo ili kolektas berojn."],[24,7,"Nudaj ili tradormas la nokton, ĉar ili ne havas veston, Kaj dum la frosto ili havas nenion, por sin kovri.","Nudaj ili tradormas la nokton, ĉar ili ne havas veston, Kaj dum la frosto ili havas nenion, por sin kovri."],[24,8,"De la pluvego de la montoj ili malsekiĝas, Kaj pro nehavado de rifuĝejo ili ĉirkaŭprenas rokon.","De la pluvego de la montoj ili malsekiĝas, Kaj pro nehavado de rifuĝejo ili ĉirkaŭprenas rokon."],[24,9,"Oni forŝiras orfon de la mamoj, Kaj oni ruinigas malriĉulon.","Oni forŝiras orfon de la mamoj, Kaj oni ruinigas malriĉulon."],[24,10,"Ili iras nudaj, sen vestoj, Kaj malsataj ili portas garbojn;","Ili iras nudaj, sen vestoj, Kaj malsataj ili portas garbojn;"],[24,11,"Inter iliaj muroj oni pretigas oleon; Oni devigas ilin treti en vinpremejoj, dum ili mem estas soifantaj.","Inter iliaj muroj oni pretigas oleon; Oni devigas ilin treti en vinpremejoj, dum ili mem estas soifantaj."],[24,12,"El la urbo aŭdiĝas ĝemoj de homoj, Kaj la animoj de mortigatoj krias; Sed Dio ne atentas tiun blasfemadon.","El la urbo aŭdiĝas ĝemoj de homoj, Kaj la animoj de mortigatoj krias; Sed Dio ne atentas tiun blasfemadon."],[24,13,"Tiuj homoj estas kontraŭuloj de la lumo; Ili ne konas Liajn vojojn, Ne revenas al Lia irejo.","Tiuj homoj estas kontraŭuloj de la lumo; Ili ne konas Liajn vojojn, Ne revenas al Lia irejo."],[24,14,"Antaŭ tagiĝo leviĝas la mortigisto, Mortigas malriĉulon kaj senhavulon, Kaj en la nokto li estas kiel ŝtelisto.","Antaŭ tagiĝo leviĝas la mortigisto, Mortigas malriĉulon kaj senhavulon, Kaj en la nokto li estas kiel ŝtelisto."],[24,15,"La okulo de adultulo atendas la krepuskon, Dirante: Neniu okulo min vidu; Kaj li kovras sian vizaĝon.","La okulo de adultulo atendas la krepuskon, Dirante: Neniu okulo min vidu; Kaj li kovras sian vizaĝon."],[24,16,"En mallumo oni faras subfoson sub domoj; Dum la tago oni kaŝas sin ĉe si, ne konante lumon.","En mallumo oni faras subfoson sub domoj; Dum la tago oni kaŝas sin ĉe si, ne konante lumon."],[24,17,"Ĉar la mallumo estas mateno por ili ĉiuj, Ĉar ili interkonatiĝis kun la teruroj de la mallumo.","Ĉar la mallumo estas mateno por ili ĉiuj, Ĉar ili interkonatiĝis kun la teruroj de la mallumo."],[24,18,"Tia homo estas malpeza sur la supraĵo de akvo; Malgranda estas lia parto sur la tero; Li ne iras laŭ la vojo de vinberĝardenoj.","Tia homo estas malpeza sur la supraĵo de akvo; Malgranda estas lia parto sur la tero; Li ne iras laŭ la vojo de vinberĝardenoj."],[24,19,"Kiel seka tero kaj varmego englutas neĝan akvon, Tiel Ŝeol englutas la pekulojn.","Kiel seka tero kaj varmego englutas neĝan akvon, Tiel Ŝeol englutas la pekulojn."],[24,20,"Forgesu lin la interno de lia patrino; La vermoj frandu lin; Oni lin ne plu rememoru; Li rompiĝu kiel malbona arbo —","Forgesu lin la interno de lia patrino; La vermoj frandu lin; Oni lin ne plu rememoru; Li rompiĝu kiel malbona arbo —"],[24,21,"Li, kiu premas seninfanulinon, kiu ne naskis, Kaj kiu ne faras bonon al vidvino.","Li, kiu premas seninfanulinon, kiu ne naskis, Kaj kiu ne faras bonon al vidvino."],[24,22,"Kiu eĉ potenculojn maltrankviligas per sia forto, Tiel ke oni ne estas certa pri sia vivo, kiam li leviĝis.","Kiu eĉ potenculojn maltrankviligas per sia forto, Tiel ke oni ne estas certa pri sia vivo, kiam li leviĝis."],[24,23,"Dio donas al ili sendanĝerecon kaj apogon, Kaj Liaj okuloj estas super iliaj vojoj.","Dio donas al ili sendanĝerecon kaj apogon, Kaj Liaj okuloj estas super iliaj vojoj."],[24,24,"Ili leviĝis alte; sed subite ili ne plu ekzistas; Ili falas kaj estas forkaptataj kiel ĉiuj, Kaj kiel la kapo de spiko ili dehakiĝas.","Ili leviĝis alte; sed subite ili ne plu ekzistas; Ili falas kaj estas forkaptataj kiel ĉiuj, Kaj kiel la kapo de spiko ili dehakiĝas."],[24,25,"Ĉu ne estas tiel? Kiu pruvos, ke mi mensogas, kaj senvalorigos mian parolon?","Ĉu ne estas tiel? Kiu pruvos, ke mi mensogas, kaj senvalorigos mian parolon?"],[25,1,"Ekparolis Bildad, la Ŝuĥano, kaj diris:","Ekparolis Bildad, la Ŝuĥano, kaj diris:"],[25,2,"Regado kaj timigo estas ĉe Li, Kiu faras pacon en Siaj altaj sferoj.","Regado kaj timigo estas ĉe Li, Kiu faras pacon en Siaj altaj sferoj."],[25,3,"Ĉu oni povas kalkuli Liajn taĉmentojn? Kaj super kiu ne leviĝas Lia lumo?","Ĉu oni povas kalkuli Liajn taĉmentojn? Kaj super kiu ne leviĝas Lia lumo?"],[25,4,"Kiel povas homo esti prava antaŭ Dio? Kaj kiel naskito de virino povas esti pura?","Kiel povas homo esti prava antaŭ Dio? Kaj kiel naskito de virino povas esti pura?"],[25,5,"Vidu, eĉ la luno ne estas hela Kaj la steloj ne estas puraj antaŭ Liaj okuloj:","Vidu, eĉ la luno ne estas hela Kaj la steloj ne estas puraj antaŭ Liaj okuloj:"],[25,6,"Des pli homo, la vermo! Kaj homido, la tineo!","Des pli homo, la vermo! Kaj homido, la tineo!"],[26,1,"Ijob respondis kaj diris:","Ijob respondis kaj diris:"],[26,2,"Kiel vi helpas al tiu, kiu ne havas forton! Kiel vi subtenas tiun, kies brako estas senforta!","Kiel vi helpas al tiu, kiu ne havas forton! Kiel vi subtenas tiun, kies brako estas senforta!"],[26,3,"Kian konsilon vi donas al tiu, kiu ne havas saĝon, Kaj kiel grandan prudenton vi montras!","Kian konsilon vi donas al tiu, kiu ne havas saĝon, Kaj kiel grandan prudenton vi montras!"],[26,4,"Al kiu vi parolas vortojn? Kaj kies spirito eliras el vi?","Al kiu vi parolas vortojn? Kaj kies spirito eliras el vi?"],[26,5,"La mortintoj tremas sub la akvo, Kaj ankaŭ tiuj, kiuj vivas en ĝi.","La mortintoj tremas sub la akvo, Kaj ankaŭ tiuj, kiuj vivas en ĝi."],[26,6,"Ŝeol estas malkovrita antaŭ Li, Kaj la abismo ne havas kovron.","Ŝeol estas malkovrita antaŭ Li, Kaj la abismo ne havas kovron."],[26,7,"Li etendis la nordon super la malpleno, Li pendigis la teron sur nenio.","Li etendis la nordon super la malpleno, Li pendigis la teron sur nenio."],[26,8,"Li ligas la akvon en Siaj nuboj, Kaj nubo ne krevas sub tio.","Li ligas la akvon en Siaj nuboj, Kaj nubo ne krevas sub tio."],[26,9,"Li kovras la tronon Kaj etendas ĉirkaŭ ĝi Sian nubon.","Li kovras la tronon Kaj etendas ĉirkaŭ ĝi Sian nubon."],[26,10,"Li faris limon sur la akvo, Ĝis la loko, kie finiĝas la lumo kaj la mallumo.","Li faris limon sur la akvo, Ĝis la loko, kie finiĝas la lumo kaj la mallumo."],[26,11,"La kolonoj de la ĉielo ŝanceliĝas Kaj tremas de Lia krio.","La kolonoj de la ĉielo ŝanceliĝas Kaj tremas de Lia krio."],[26,12,"Per Sia forto Li kvietigas la maron, Kaj per Sia saĝo Li frakasas Rahabon.","Per Sia forto Li kvietigas la maron, Kaj per Sia saĝo Li frakasas Rahabon."],[26,13,"Per Lia spirito belegiĝis la ĉielo; Lia mano trapikas la tordiĝantan serpenton.","Per Lia spirito belegiĝis la ĉielo; Lia mano trapikas la tordiĝantan serpenton."],[26,14,"Jen tio estas parto de Liaj vojoj; Kaj nur iometon ni aŭdis pri Li. Kiu povas kompreni la tondron de Lia potenco?","Jen tio estas parto de Liaj vojoj; Kaj nur iometon ni aŭdis pri Li. Kiu povas kompreni la tondron de Lia potenco?"],[27,1,"Kaj Ijob daŭrigis siajn sentencojn, kaj diris:","Kaj Ijob daŭrigis siajn sentencojn, kaj diris:"],[27,2,"Kiel vivas Dio, kiu rifuzis al mi miajn rajtojn, Kaj la Plejpotenculo, kiu afliktas mian animon:","Kiel vivas Dio, kiu rifuzis al mi miajn rajtojn, Kaj la Plejpotenculo, kiu afliktas mian animon:"],[27,3,"Tiel longe, kiel mia animo estas en mi Kaj la spiro de Dio en mia nazo,","Tiel longe, kiel mia animo estas en mi Kaj la spiro de Dio en mia nazo,"],[27,4,"Miaj lipoj ne eldiros malĝustaĵon, Kaj mia lango ne diros malveraĵon.","Miaj lipoj ne eldiros malĝustaĵon, Kaj mia lango ne diros malveraĵon."],[27,5,"Malproksime estas de mi, Rigardi vin kiel pravajn; Ĝis mia morto mi ne ĉesos rigardi min kiel senkulpan.","Malproksime estas de mi, Rigardi vin kiel pravajn; Ĝis mia morto mi ne ĉesos rigardi min kiel senkulpan."],[27,6,"Mian pravecon mi tenas forte, kaj mi ne ellasos ĝin; Dum mia tuta vivo mia koro ne faros al mi riproĉon pri tio.","Mian pravecon mi tenas forte, kaj mi ne ellasos ĝin; Dum mia tuta vivo mia koro ne faros al mi riproĉon pri tio."],[27,7,"Mia malamiko estu rigardata kiel malvirtulo, Kaj mia kontraŭulo kiel malpiulo.","Mia malamiko estu rigardata kiel malvirtulo, Kaj mia kontraŭulo kiel malpiulo."],[27,8,"Ĉar kio estas la espero de hipokritulo, Kiam Dio faras al li finon, elŝiras lian animon?","Ĉar kio estas la espero de hipokritulo, Kiam Dio faras al li finon, elŝiras lian animon?"],[27,9,"Ĉu lian kriadon Dio aŭskultos, Kiam trafos lin malfeliĉo?","Ĉu lian kriadon Dio aŭskultos, Kiam trafos lin malfeliĉo?"],[27,10,"Ĉu li povas havi ĝuon de la Plejpotenculo, Voki al Dio en ĉiu tempo?","Ĉu li povas havi ĝuon de la Plejpotenculo, Voki al Dio en ĉiu tempo?"],[27,11,"Mi instruos vin pri la mano de Dio; Mi ne kaŝos antaŭ vi tion, kio estas ĉe la Plejpotenculo.","Mi instruos vin pri la mano de Dio; Mi ne kaŝos antaŭ vi tion, kio estas ĉe la Plejpotenculo."],[27,12,"Jen vi ĉiuj mem vidis; Kial do vi parolas senenhavaĵon?","Jen vi ĉiuj mem vidis; Kial do vi parolas senenhavaĵon?"],[27,13,"Tia estas la sorto de malbona homo ĉe Dio, Kaj la parto, kiun tiranoj ricevas de la Plejpotenculo:","Tia estas la sorto de malbona homo ĉe Dio, Kaj la parto, kiun tiranoj ricevas de la Plejpotenculo:"],[27,14,"Se li havos multe da filoj, ili iros sub la glavon; Kaj lia devenantaro ne havos sate panon.","Se li havos multe da filoj, ili iros sub la glavon; Kaj lia devenantaro ne havos sate panon."],[27,15,"Tiujn, kiuj restos ĉe li, enterigos la morto; Kaj liaj vidvinoj ne ploros.","Tiujn, kiuj restos ĉe li, enterigos la morto; Kaj liaj vidvinoj ne ploros."],[27,16,"Se li kolektos arĝenton kiel polvon Kaj pretigos al si vestojn kiel argilon,","Se li kolektos arĝenton kiel polvon Kaj pretigos al si vestojn kiel argilon,"],[27,17,"Tiam li pretigos, sed justulo metos sur sin la vestojn, Kaj senkulpulo dividos la arĝenton.","Tiam li pretigos, sed justulo metos sur sin la vestojn, Kaj senkulpulo dividos la arĝenton."],[27,18,"Li konstruas sian domon kiel tineo, Kaj kiel gardisto, kiu faras al si laŭbon.","Li konstruas sian domon kiel tineo, Kaj kiel gardisto, kiu faras al si laŭbon."],[27,19,"Li kuŝiĝas riĉa, kaj nenion kunportas; Li malfermas la okulojn, kaj jam nenio ekzistas.","Li kuŝiĝas riĉa, kaj nenion kunportas; Li malfermas la okulojn, kaj jam nenio ekzistas."],[27,20,"Teruro superfalos lin kiel akvo; En la nokto forportos lin ventego.","Teruro superfalos lin kiel akvo; En la nokto forportos lin ventego."],[27,21,"Levos lin vento orienta, kaj foriros, Kaj forblovos lin de lia loko.","Levos lin vento orienta, kaj foriros, Kaj forblovos lin de lia loko."],[27,22,"Li tion ĵetos sur lin senkompate; De Lia mano li kuros kaj kuros.","Li tion ĵetos sur lin senkompate; De Lia mano li kuros kaj kuros."],[27,23,"Oni kunfrapos pri li la manojn, Kaj oni fajfos pri li sur lia loko.","Oni kunfrapos pri li la manojn, Kaj oni fajfos pri li sur lia loko."],[28,1,"La arĝento havas lokon, kie oni ĝin elakiras; Kaj la oro havas lokon, kie oni ĝin fandas.","La arĝento havas lokon, kie oni ĝin elakiras; Kaj la oro havas lokon, kie oni ĝin fandas."],[28,2,"La fero estas ricevata el polvo, Kaj el ŝtono oni fandas la kupron.","La fero estas ricevata el polvo, Kaj el ŝtono oni fandas la kupron."],[28,3,"Oni faras finon al la mallumo, Kaj rezulte oni trovas la ŝtonojn el grandega mallumo.","Oni faras finon al la mallumo, Kaj rezulte oni trovas la ŝtonojn el grandega mallumo."],[28,4,"Oni fosas kavon tie, kie oni loĝas; Kaj tie, kie paŝas neniu piedo, ili laboras pendante, forgesitaj de homoj.","Oni fosas kavon tie, kie oni loĝas; Kaj tie, kie paŝas neniu piedo, ili laboras pendante, forgesitaj de homoj."],[28,5,"La tero, el kiu devenas pano, Estas trafosata sube kvazaŭ per fajro.","La tero, el kiu devenas pano, Estas trafosata sube kvazaŭ per fajro."],[28,6,"Ĝiaj ŝtonoj estas loko de safiroj, Kaj terbuloj enhavas oron.","Ĝiaj ŝtonoj estas loko de safiroj, Kaj terbuloj enhavas oron."],[28,7,"La vojon ne konas rabobirdo, Kaj la okulo de falko ĝin ne vidis.","La vojon ne konas rabobirdo, Kaj la okulo de falko ĝin ne vidis."],[28,8,"Ne paŝis sur ĝi sovaĝaj bestoj, Ne iris sur ĝi leono.","Ne paŝis sur ĝi sovaĝaj bestoj, Ne iris sur ĝi leono."],[28,9,"Sur rokon oni metas sian manon, Oni renversas montojn de ilia bazo.","Sur rokon oni metas sian manon, Oni renversas montojn de ilia bazo."],[28,10,"En rokoj oni elhakas riverojn, Kaj ĉion grandvaloran vidis la okulo de homo.","En rokoj oni elhakas riverojn, Kaj ĉion grandvaloran vidis la okulo de homo."],[28,11,"Oni haltigas la fluon de riveroj, Kaj kaŝitaĵon oni eltiras al la lumo.","Oni haltigas la fluon de riveroj, Kaj kaŝitaĵon oni eltiras al la lumo."],[28,12,"Sed kie oni trovas la saĝon? Kaj kie estas la loko de prudento?","Sed kie oni trovas la saĝon? Kaj kie estas la loko de prudento?"],[28,13,"La homo ne scias ĝian prezon; Kaj ĝi ne estas trovata sur la tero de vivantoj.","La homo ne scias ĝian prezon; Kaj ĝi ne estas trovata sur la tero de vivantoj."],[28,14,"La abismo diras: Ne en mi ĝi estas; La maro diras: Ĝi ne troviĝas ĉe mi.","La abismo diras: Ne en mi ĝi estas; La maro diras: Ĝi ne troviĝas ĉe mi."],[28,15,"Oni ne povas doni por ĝi plej bonan oron, Oni ne pesas arĝenton page por ĝi.","Oni ne povas doni por ĝi plej bonan oron, Oni ne pesas arĝenton page por ĝi."],[28,16,"Oni ne taksas ĝin per oro Ofira, Nek per multekosta onikso kaj safiro.","Oni ne taksas ĝin per oro Ofira, Nek per multekosta onikso kaj safiro."],[28,17,"Ne valoregalas al ĝi oro kaj vitro; Kaj oni ne povas ŝanĝi ĝin kontraŭ vazoj el pura oro.","Ne valoregalas al ĝi oro kaj vitro; Kaj oni ne povas ŝanĝi ĝin kontraŭ vazoj el pura oro."],[28,18,"Koraloj kaj kristalo ne estas atentataj; Kaj posedo de saĝo estas pli valora ol perloj.","Koraloj kaj kristalo ne estas atentataj; Kaj posedo de saĝo estas pli valora ol perloj."],[28,19,"Ne valoregalas al ĝi topazo el Etiopujo; Pura oro ne povas esti ĝia prezo.","Ne valoregalas al ĝi topazo el Etiopujo; Pura oro ne povas esti ĝia prezo."],[28,20,"De kie venas la saĝo? Kaj kie estas la loko de prudento?","De kie venas la saĝo? Kaj kie estas la loko de prudento?"],[28,21,"Kaŝita ĝi estas antaŭ la okuloj de ĉio vivanta, Nevidebla por la birdoj de la ĉielo.","Kaŝita ĝi estas antaŭ la okuloj de ĉio vivanta, Nevidebla por la birdoj de la ĉielo."],[28,22,"La abismo kaj la morto diras: Per niaj oreloj ni aŭdis nur famon pri ĝi.","La abismo kaj la morto diras: Per niaj oreloj ni aŭdis nur famon pri ĝi."],[28,23,"Dio komprenas ĝian vojon, Kaj Li scias ĝian lokon;","Dio komprenas ĝian vojon, Kaj Li scias ĝian lokon;"],[28,24,"Ĉar Li rigardas ĝis la fino de la tero, Li vidas sub la tuta ĉielo.","Ĉar Li rigardas ĝis la fino de la tero, Li vidas sub la tuta ĉielo."],[28,25,"Kiam Li donis pezon al la vento Kaj aranĝis la akvon laŭmezure,","Kiam Li donis pezon al la vento Kaj aranĝis la akvon laŭmezure,"],[28,26,"Kiam Li starigis leĝon por la pluvo Kaj vojon por la fulmo kaj tondro:","Kiam Li starigis leĝon por la pluvo Kaj vojon por la fulmo kaj tondro:"],[28,27,"Tiam Li vidis ĝin kaj anoncis ĝin, Pretigis ĝin kaj esploris ĝin;","Tiam Li vidis ĝin kaj anoncis ĝin, Pretigis ĝin kaj esploris ĝin;"],[28,28,"Kaj Li diris al la homoj: Vidu, timo antaŭ Dio estas saĝo, Kaj evitado de malbono estas prudento.","Kaj Li diris al la homoj: Vidu, timo antaŭ Dio estas saĝo, Kaj evitado de malbono estas prudento."],[29,1,"Kaj plue Ijob parolis siajn sentencojn, kaj diris:","Kaj plue Ijob parolis siajn sentencojn, kaj diris:"],[29,2,"Ho, se estus al mi tiel, kiel en la antaŭaj monatoj, Kiel en la tempo, kiam Dio min gardis;","Ho, se estus al mi tiel, kiel en la antaŭaj monatoj, Kiel en la tempo, kiam Dio min gardis;"],[29,3,"Kiam Lia lumilo lumis super mia kapo; Kaj sub Lia lumo mi povis iri en mallumo;","Kiam Lia lumilo lumis super mia kapo; Kaj sub Lia lumo mi povis iri en mallumo;"],[29,4,"Kiel estis al mi en la tagoj de mia juneco, Kiam la ŝirmado de Dio estis super mia tendo;","Kiel estis al mi en la tagoj de mia juneco, Kiam la ŝirmado de Dio estis super mia tendo;"],[29,5,"Kiam la Plejpotenculo estis ankoraŭ kun mi, Kaj ĉirkaŭ mi estis miaj infanoj;","Kiam la Plejpotenculo estis ankoraŭ kun mi, Kaj ĉirkaŭ mi estis miaj infanoj;"],[29,6,"Kiam miaj paŝoj laviĝadis en butero, Kaj la roko verŝadis al mi fluojn da oleo!","Kiam miaj paŝoj laviĝadis en butero, Kaj la roko verŝadis al mi fluojn da oleo!"],[29,7,"Kiam mi eliris el la pordego al la urbo Kaj aranĝis al mi sidon sur la placo,","Kiam mi eliris el la pordego al la urbo Kaj aranĝis al mi sidon sur la placo,"],[29,8,"Vidis min junuloj kaj kaŝis sin, Kaj maljunuloj leviĝis kaj staris;","Vidis min junuloj kaj kaŝis sin, Kaj maljunuloj leviĝis kaj staris;"],[29,9,"Eminentuloj ĉesis paroli Kaj metis la manon sur sian buŝon;","Eminentuloj ĉesis paroli Kaj metis la manon sur sian buŝon;"],[29,10,"La voĉo de altranguloj sin kaŝis, Kaj ilia lango algluiĝis al ilia palato.","La voĉo de altranguloj sin kaŝis, Kaj ilia lango algluiĝis al ilia palato."],[29,11,"Kiam orelo aŭdis, ĝi nomis min feliĉa; Kiam okulo vidis, ĝi gloris min;","Kiam orelo aŭdis, ĝi nomis min feliĉa; Kiam okulo vidis, ĝi gloris min;"],[29,12,"Ĉar mi savadis kriantan malriĉulon, Kaj orfon, kiu ne havis helpanton.","Ĉar mi savadis kriantan malriĉulon, Kaj orfon, kiu ne havis helpanton."],[29,13,"Beno de pereanto venadis sur min, Kaj la koro de vidvino estis ĝojigata de mi.","Beno de pereanto venadis sur min, Kaj la koro de vidvino estis ĝojigata de mi."],[29,14,"Virteco estis mia vesto, Kaj mia justeco vestis min kiel mantelo kaj kapornamo.","Virteco estis mia vesto, Kaj mia justeco vestis min kiel mantelo kaj kapornamo."],[29,15,"Mi estis okuloj por la blindulo, Kaj piedoj por la lamulo;","Mi estis okuloj por la blindulo, Kaj piedoj por la lamulo;"],[29,16,"Mi estis patro por la malriĉuloj, Kaj juĝan aferon de homoj nekonataj mi esploradis;","Mi estis patro por la malriĉuloj, Kaj juĝan aferon de homoj nekonataj mi esploradis;"],[29,17,"Mi rompadis la makzelojn al maljustulo, Kaj el liaj dentoj mi elŝiradis la kaptitaĵon.","Mi rompadis la makzelojn al maljustulo, Kaj el liaj dentoj mi elŝiradis la kaptitaĵon."],[29,18,"Kaj mi pensis: En mia nesto mi mortos, Kaj grandnombraj kiel sablo estos miaj tagoj;","Kaj mi pensis: En mia nesto mi mortos, Kaj grandnombraj kiel sablo estos miaj tagoj;"],[29,19,"Mia radiko estas malkovrita por la akvo, Kaj roso noktas sur miaj branĉoj.","Mia radiko estas malkovrita por la akvo, Kaj roso noktas sur miaj branĉoj."],[29,20,"Mia gloro estas ĉiam nova, Kaj mia pafarko ĉiam refortiĝas en mia mano.","Mia gloro estas ĉiam nova, Kaj mia pafarko ĉiam refortiĝas en mia mano."],[29,21,"Oni aŭskultadis min kaj atendadis, Kaj silentadis, kiam mi donadis konsilojn.","Oni aŭskultadis min kaj atendadis, Kaj silentadis, kiam mi donadis konsilojn."],[29,22,"Post miaj vortoj oni ne plu parolis; Kaj miaj vortoj gutadis sur ilin.","Post miaj vortoj oni ne plu parolis; Kaj miaj vortoj gutadis sur ilin."],[29,23,"Oni atendadis min kiel la pluvon, Kaj malfermadis sian buŝon, kiel por malfrua pluvo.","Oni atendadis min kiel la pluvon, Kaj malfermadis sian buŝon, kiel por malfrua pluvo."],[29,24,"Se mi iam ridis al ili, ili ne kredis tion; Kaj la lumo de mia vizaĝo ne falis.","Se mi iam ridis al ili, ili ne kredis tion; Kaj la lumo de mia vizaĝo ne falis."],[29,25,"Kiam mi iris al ili, mi sidis sur la ĉefa loko; Mi loĝis kiel reĝo inter taĉmentoj, Kiel konsolanto de funebruloj.","Kiam mi iris al ili, mi sidis sur la ĉefa loko; Mi loĝis kiel reĝo inter taĉmentoj, Kiel konsolanto de funebruloj."],[30,1,"Sed nun ridas pri mi homoj pli junaj ol mi, Kies patrojn mi ne volus starigi kun la hundoj de miaj ŝafaroj;","Sed nun ridas pri mi homoj pli junaj ol mi, Kies patrojn mi ne volus starigi kun la hundoj de miaj ŝafaroj;"],[30,2,"Kies forto de la manoj estis senbezona por mi, Kaj kiuj ne povis atingi maljunecon;","Kies forto de la manoj estis senbezona por mi, Kaj kiuj ne povis atingi maljunecon;"],[30,3,"Kiuj pro malriĉeco kaj malsato solece kuris En la dezerton mizeran kaj senvivan;","Kiuj pro malriĉeco kaj malsato solece kuris En la dezerton mizeran kaj senvivan;"],[30,4,"Kiuj elŝiras atriplon apud la arbetaĵoj, Kaj kies pano estas la radiko de genisto.","Kiuj elŝiras atriplon apud la arbetaĵoj, Kaj kies pano estas la radiko de genisto."],[30,5,"El meze de la homoj oni elpelas ilin; Oni krias sur ilin, kiel sur ŝteliston;","El meze de la homoj oni elpelas ilin; Oni krias sur ilin, kiel sur ŝteliston;"],[30,6,"En terfendoj ĉe la valoj ili loĝas, En truoj de la tero kaj de rokoj;","En terfendoj ĉe la valoj ili loĝas, En truoj de la tero kaj de rokoj;"],[30,7,"Inter la arbetaĵoj ili krias, Sub la kardoj ili kolektiĝas;","Inter la arbetaĵoj ili krias, Sub la kardoj ili kolektiĝas;"],[30,8,"Kiel infanoj de sentaŭguloj kaj sennomuloj, Ili estas elpelitaj el la lando.","Kiel infanoj de sentaŭguloj kaj sennomuloj, Ili estas elpelitaj el la lando."],[30,9,"Kaj nun mi fariĝis objekto de ilia mokokanto, Mi fariĝis por ili objekto de babilado.","Kaj nun mi fariĝis objekto de ilia mokokanto, Mi fariĝis por ili objekto de babilado."],[30,10,"Ili abomenas min, malproksimiĝas de mi, Ne timas kraĉi sur mian vizaĝon.","Ili abomenas min, malproksimiĝas de mi, Ne timas kraĉi sur mian vizaĝon."],[30,11,"Li malligis mian ŝnuron kaj turmentas min, Kaj ili forĵetis antaŭ mi la bridon.","Li malligis mian ŝnuron kaj turmentas min, Kaj ili forĵetis antaŭ mi la bridon."],[30,12,"Dekstre buboj stariĝis, kaj puŝas miajn piedojn; Ili ebenigis kontraŭ mi siajn pereigajn vojojn;","Dekstre buboj stariĝis, kaj puŝas miajn piedojn; Ili ebenigis kontraŭ mi siajn pereigajn vojojn;"],[30,13,"Ili disfosis mian vojon, facile pereigas min, Ne bezonante helpanton;","Ili disfosis mian vojon, facile pereigas min, Ne bezonante helpanton;"],[30,14,"Ili venas kiel tra larĝa breĉo, Ĵetas sin tumulte.","Ili venas kiel tra larĝa breĉo, Ĵetas sin tumulte."],[30,15,"Teruroj turnis sin kontraŭ min, Forpelis mian majeston kiel vento; Kiel nubo foriris mia feliĉo.","Teruroj turnis sin kontraŭ min, Forpelis mian majeston kiel vento; Kiel nubo foriris mia feliĉo."],[30,16,"Kaj nun elverŝiĝas mia animo; Kaptis min tagoj de mizero.","Kaj nun elverŝiĝas mia animo; Kaptis min tagoj de mizero."],[30,17,"En la nokto miaj ostoj traboriĝas en mi, Kaj miaj mordetantoj ne dormas.","En la nokto miaj ostoj traboriĝas en mi, Kaj miaj mordetantoj ne dormas."],[30,18,"Kun granda malfacileco demetiĝas mia vesto; Premas min la rando de mia ĉemizo.","Kun granda malfacileco demetiĝas mia vesto; Premas min la rando de mia ĉemizo."],[30,19,"Oni komparas min kun koto; Mi similiĝis al polvo kaj cindro.","Oni komparas min kun koto; Mi similiĝis al polvo kaj cindro."],[30,20,"Mi krias al Vi, sed Vi ne respondas al mi; Mi staras, ke Vi atentu min.","Mi krias al Vi, sed Vi ne respondas al mi; Mi staras, ke Vi atentu min."],[30,21,"Vi fariĝis kruelulo por mi; Per la forto de Via mano Vi montras al mi Vian malamon.","Vi fariĝis kruelulo por mi; Per la forto de Via mano Vi montras al mi Vian malamon."],[30,22,"Vi levis min en la venton, Lasis min kaj neniigis min en la ventego.","Vi levis min en la venton, Lasis min kaj neniigis min en la ventego."],[30,23,"Mi scias, ke Vi transdonos min al la morto, En la kunvenejon de ĉio vivanta.","Mi scias, ke Vi transdonos min al la morto, En la kunvenejon de ĉio vivanta."],[30,24,"Sed ĉu oni povas ne deziri eltiri manon, Kaj krii en sia malfeliĉo?","Sed ĉu oni povas ne deziri eltiri manon, Kaj krii en sia malfeliĉo?"],[30,25,"Ĉu mi ne ploris pri tiu, kiu havis malfeliĉan tempon? Ĉu mia animo ne afliktiĝis pri malriĉulo?","Ĉu mi ne ploris pri tiu, kiu havis malfeliĉan tempon? Ĉu mia animo ne afliktiĝis pri malriĉulo?"],[30,26,"Mi atendis bonon, sed venis malbono; Mi esperis lumon, sed venis mallumo.","Mi atendis bonon, sed venis malbono; Mi esperis lumon, sed venis mallumo."],[30,27,"Miaj internaĵoj bolas kaj ne ĉesas; Atakis min tempo de mizero.","Miaj internaĵoj bolas kaj ne ĉesas; Atakis min tempo de mizero."],[30,28,"Mi estas nigra, sed ne de la suno; Mi leviĝas en la komunumo kaj krias.","Mi estas nigra, sed ne de la suno; Mi leviĝas en la komunumo kaj krias."],[30,29,"Mi fariĝis frato al la ŝakaloj Kaj kamarado al la strutoj.","Mi fariĝis frato al la ŝakaloj Kaj kamarado al la strutoj."],[30,30,"Mia haŭto nigriĝis sur mi, Kaj miaj ostoj sekiĝis de varmego.","Mia haŭto nigriĝis sur mi, Kaj miaj ostoj sekiĝis de varmego."],[30,31,"Mia harpo fariĝis plendilo, Kaj mia fluto fariĝis voĉo de plorantoj.","Mia harpo fariĝis plendilo, Kaj mia fluto fariĝis voĉo de plorantoj."],[31,1,"Mi faris interligon kun miaj okuloj, Ke mi ne atentu virgulinon.","Mi faris interligon kun miaj okuloj, Ke mi ne atentu virgulinon."],[31,2,"Kia estas la parto, kiun donas Dio de supre? Kaj kion destinas la Plejpotenculo el la altaj sferoj?","Kia estas la parto, kiun donas Dio de supre? Kaj kion destinas la Plejpotenculo el la altaj sferoj?"],[31,3,"Ĉu ne malfeliĉon al malpiulo, Kaj forpuŝon de malbonagantoj?","Ĉu ne malfeliĉon al malpiulo, Kaj forpuŝon de malbonagantoj?"],[31,4,"Ĉu Li ne vidas mian konduton, Ne kalkulas ĉiujn miajn paŝojn?","Ĉu Li ne vidas mian konduton, Ne kalkulas ĉiujn miajn paŝojn?"],[31,5,"Ĉu mi iradis en malvero, Kaj miaj piedoj rapidis al trompo?","Ĉu mi iradis en malvero, Kaj miaj piedoj rapidis al trompo?"],[31,6,"Li pesu min per justa pesilo, Kaj tiam Dio konvinkiĝos pri mia senkulpeco.","Li pesu min per justa pesilo, Kaj tiam Dio konvinkiĝos pri mia senkulpeco."],[31,7,"Se mia paŝo forkliniĝis de la vojo, Se mia koro sekvis miajn okulojn, Kaj se al mia mano algluiĝis makulo:","Se mia paŝo forkliniĝis de la vojo, Se mia koro sekvis miajn okulojn, Kaj se al mia mano algluiĝis makulo:"],[31,8,"Tiam mi semu kaj alia manĝu, Kaj mia idaro elradikiĝu.","Tiam mi semu kaj alia manĝu, Kaj mia idaro elradikiĝu."],[31,9,"Se mia koro forlogiĝis al virino, Kaj mi kaŝe atendis ĉe la pordo de mia amiko:","Se mia koro forlogiĝis al virino, Kaj mi kaŝe atendis ĉe la pordo de mia amiko:"],[31,10,"Tiam mia edzino estu adultigata de aliulo, Kaj aliuloj kliniĝu super ŝi.","Tiam mia edzino estu adultigata de aliulo, Kaj aliuloj kliniĝu super ŝi."],[31,11,"Ĉar tio estus malvirto, Tio estus krimo, kiun devas puni juĝistoj.","Ĉar tio estus malvirto, Tio estus krimo, kiun devas puni juĝistoj."],[31,12,"Tio estas fajro, kiu ekstermas ĝis la abismo, Kaj mian tutan akiritaĵon ĝi elradikigus.","Tio estas fajro, kiu ekstermas ĝis la abismo, Kaj mian tutan akiritaĵon ĝi elradikigus."],[31,13,"Ĉu mi malŝatis la rajton de mia servisto aŭ de mia servistino, Kiam ili havis juĝan aferon kun mi?","Ĉu mi malŝatis la rajton de mia servisto aŭ de mia servistino, Kiam ili havis juĝan aferon kun mi?"],[31,14,"Tiam kion mi farus, kiam Dio leviĝus? Kaj kion mi respondus al Li, kiam Li esplordemandus?","Tiam kion mi farus, kiam Dio leviĝus? Kaj kion mi respondus al Li, kiam Li esplordemandus?"],[31,15,"Lin kreis ja Tiu sama, kiu kreis min en la ventro, Kaj Tiu sama pretigis en la ventro ankaŭ lin.","Lin kreis ja Tiu sama, kiu kreis min en la ventro, Kaj Tiu sama pretigis en la ventro ankaŭ lin."],[31,16,"Ĉu mi rifuzis la deziron de senhavuloj? Aŭ ĉu mi turmentis la okulojn de vidvino?","Ĉu mi rifuzis la deziron de senhavuloj? Aŭ ĉu mi turmentis la okulojn de vidvino?"],[31,17,"Ĉu mian panpecon mi manĝis sola? Ĉu ne manĝis de ĝi ankaŭ orfo?","Ĉu mian panpecon mi manĝis sola? Ĉu ne manĝis de ĝi ankaŭ orfo?"],[31,18,"Ĉar detempe de mia juneco mi estis kiel patro, Kaj de post la eliro el la ventro de mia patrino mi estis gvidisto.","Ĉar detempe de mia juneco mi estis kiel patro, Kaj de post la eliro el la ventro de mia patrino mi estis gvidisto."],[31,19,"Kiam mi vidis malfeliĉulon sen vesto Kaj malriĉulon sen kovro,","Kiam mi vidis malfeliĉulon sen vesto Kaj malriĉulon sen kovro,"],[31,20,"Ĉu tiam ne benis min liaj lumboj, Ĉu li ne estis varmigata per la lano de miaj ŝafoj?","Ĉu tiam ne benis min liaj lumboj, Ĉu li ne estis varmigata per la lano de miaj ŝafoj?"],[31,21,"Se mi levis mian manon kontraŭ orfon, Ĉar mi vidis en la pordego helpon al mi,","Se mi levis mian manon kontraŭ orfon, Ĉar mi vidis en la pordego helpon al mi,"],[31,22,"En tia okazo mia ŝultro defalu de la dorso, Kaj mia brako rompiĝu de kano.","En tia okazo mia ŝultro defalu de la dorso, Kaj mia brako rompiĝu de kano."],[31,23,"Ĉar mi timas la punon de Dio, Kaj ĝian pezon mi ne povus elteni.","Ĉar mi timas la punon de Dio, Kaj ĝian pezon mi ne povus elteni."],[31,24,"Ĉu mi faris la oron mia espero, Kaj la orbulon mi nomis mia fido?","Ĉu mi faris la oron mia espero, Kaj la orbulon mi nomis mia fido?"],[31,25,"Ĉu mi ĝojis, ke mia riĉeco estas granda Kaj ke mia mano multe akiris?","Ĉu mi ĝojis, ke mia riĉeco estas granda Kaj ke mia mano multe akiris?"],[31,26,"Kiam mi vidis la lumon brilantan Kaj la lunon majeste irantan,","Kiam mi vidis la lumon brilantan Kaj la lunon majeste irantan,"],[31,27,"Ĉu tiam sekrete forlogiĝis mia koro Kaj mi sendis kisojn per mia mano?","Ĉu tiam sekrete forlogiĝis mia koro Kaj mi sendis kisojn per mia mano?"],[31,28,"Ankaŭ tio estus krimo juĝinda, Ĉar mi forneus per tio Dion en la alto.","Ankaŭ tio estus krimo juĝinda, Ĉar mi forneus per tio Dion en la alto."],[31,29,"Ĉu mi ĝojis pri malfeliĉo de mia malamiko? Aŭ ĉu mi estis ravita, se lin trafis malbono?","Ĉu mi ĝojis pri malfeliĉo de mia malamiko? Aŭ ĉu mi estis ravita, se lin trafis malbono?"],[31,30,"Mi ne permesis al mia gorĝo peki Per eldiro de malbeno kontraŭ lia animo.","Mi ne permesis al mia gorĝo peki Per eldiro de malbeno kontraŭ lia animo."],[31,31,"Ĉu la homoj de mia tendo ne diris: Ho, se oni ne satiĝus de lia karno!","Ĉu la homoj de mia tendo ne diris: Ho, se oni ne satiĝus de lia karno!"],[31,32,"Ne noktis fremdulo sur la strato; Miajn pordojn mi malfermadis al migrantoj.","Ne noktis fremdulo sur la strato; Miajn pordojn mi malfermadis al migrantoj."],[31,33,"Ĉu mi hommaniere kovradis miajn kulpojn, Por kaŝi en mia brusto miajn pekojn?","Ĉu mi hommaniere kovradis miajn kulpojn, Por kaŝi en mia brusto miajn pekojn?"],[31,34,"En tia okazo mi timus grandan homamason, Kaj malestimo de familioj min timigus; Mi silentus, kaj ne elirus ekster la pordon.","En tia okazo mi timus grandan homamason, Kaj malestimo de familioj min timigus; Mi silentus, kaj ne elirus ekster la pordon."],[31,35,"Ho, se iu aŭskultus min! Jen estas mia signo; la Plejpotenculo respondu al mi. Se mia akuzanto skribus libron,","Ho, se iu aŭskultus min! Jen estas mia signo; la Plejpotenculo respondu al mi. Se mia akuzanto skribus libron,"],[31,36,"Mi portus ĝin sur mia ŝultro, Mi metus ĝin sur min kiel kronon,","Mi portus ĝin sur mia ŝultro, Mi metus ĝin sur min kiel kronon,"],[31,37,"Mi raportus al li pri la nombro de miaj paŝoj; Mi alproksimiĝus al li kiel al princo.","Mi raportus al li pri la nombro de miaj paŝoj; Mi alproksimiĝus al li kiel al princo."],[31,38,"Se mia lando kriis kontraŭ mi, Kaj ĝiaj sulkoj ploris,","Se mia lando kriis kontraŭ mi, Kaj ĝiaj sulkoj ploris,"],[31,39,"Se ĝiajn fruktojn mi manĝis senpage, Kaj mi afliktis la animon de ĝiaj mastroj:","Se ĝiajn fruktojn mi manĝis senpage, Kaj mi afliktis la animon de ĝiaj mastroj:"],[31,40,"Tiam anstataŭ tritiko kresku por mi kardo, Kaj anstataŭ hordeo dornoj. Finiĝis la paroloj de Ijob.","Tiam anstataŭ tritiko kresku por mi kardo, Kaj anstataŭ hordeo dornoj. Finiĝis la paroloj de Ijob."],[32,1,"Kaj tiuj tri viroj ĉesis respondi al Ijob, ĉar li opiniis sin prava.","Kaj tiuj tri viroj ĉesis respondi al Ijob, ĉar li opiniis sin prava."],[32,2,"Tiam ekflamis la kolero de Elihu, filo de Baraĥel, Buzano, el la familio de Ram. Kontraŭ Ijob ekflamis lia kolero pro tio, ke li opiniis sin pli prava ol Dio;","Tiam ekflamis la kolero de Elihu, filo de Baraĥel, Buzano, el la familio de Ram. Kontraŭ Ijob ekflamis lia kolero pro tio, ke li opiniis sin pli prava ol Dio;"],[32,3,"kaj kontraŭ liaj tri amikoj ekflamis lia kolero pro tio, ke ili ne trovis respondon kaj akuzis Ijobon.","kaj kontraŭ liaj tri amikoj ekflamis lia kolero pro tio, ke ili ne trovis respondon kaj akuzis Ijobon."],[32,4,"Elihu atendis, dum ili parolis kun Ijob, ĉar ili estis pli aĝaj ol li.","Elihu atendis, dum ili parolis kun Ijob, ĉar ili estis pli aĝaj ol li."],[32,5,"Sed kiam Elihu vidis, ke ne troviĝas respondo en la buŝo de la tri viroj, ekflamis lia kolero.","Sed kiam Elihu vidis, ke ne troviĝas respondo en la buŝo de la tri viroj, ekflamis lia kolero."],[32,6,"Kaj ekparolis Elihu, filo de Baraĥel, la Buzano, kaj diris: Mi estas juna, kaj vi estas maljunuloj; Tial mi hezitis kaj timis eldiri al vi mian opinion.","Kaj ekparolis Elihu, filo de Baraĥel, la Buzano, kaj diris: Mi estas juna, kaj vi estas maljunuloj; Tial mi hezitis kaj timis eldiri al vi mian opinion."],[32,7,"Mi pensis: La aĝo parolu, Kaj la jarmulto montru saĝon.","Mi pensis: La aĝo parolu, Kaj la jarmulto montru saĝon."],[32,8,"Sed la spirito en la homoj kaj la spiro de la Plejpotenculo Donas al ili prudenton.","Sed la spirito en la homoj kaj la spiro de la Plejpotenculo Donas al ili prudenton."],[32,9,"Ne la grandaj estas la plej prudentaj, Kaj ne la maljunuloj sole scias juĝi,","Ne la grandaj estas la plej prudentaj, Kaj ne la maljunuloj sole scias juĝi,"],[32,10,"Tial mi diras: Aŭskultu min; Mi ankaŭ eldiros mian opinion.","Tial mi diras: Aŭskultu min; Mi ankaŭ eldiros mian opinion."],[32,11,"Jen mi atendis viajn vortojn, Mi atentis vian kompetentecon, Ĝis vi trovos la ĝustan parolon.","Jen mi atendis viajn vortojn, Mi atentis vian kompetentecon, Ĝis vi trovos la ĝustan parolon."],[32,12,"Sed atentante vin, mi vidis, Ke neniu el vi donas al Ijob moralinstruon, Respondante al liaj paroloj.","Sed atentante vin, mi vidis, Ke neniu el vi donas al Ijob moralinstruon, Respondante al liaj paroloj."],[32,13,"Ne diru: Ni trovis la saĝon. Dio instruu lin, ne homo.","Ne diru: Ni trovis la saĝon. Dio instruu lin, ne homo."],[32,14,"Li ne direktis al mi siajn vortojn, Kaj per viaj diroj mi ne respondos al li.","Li ne direktis al mi siajn vortojn, Kaj per viaj diroj mi ne respondos al li."],[32,15,"Ili perdis la kuraĝon, ili ne plu respondis; Mankas al ili vortoj.","Ili perdis la kuraĝon, ili ne plu respondis; Mankas al ili vortoj."],[32,16,"Mi atendis, ĝis ili ĉesos paroli; Sed ĉar ili haltis kaj ne plu respondis,","Mi atendis, ĝis ili ĉesos paroli; Sed ĉar ili haltis kaj ne plu respondis,"],[32,17,"Tial ankaŭ mi de mia flanko respondos, Mi ankaŭ eldiros mian opinion.","Tial ankaŭ mi de mia flanko respondos, Mi ankaŭ eldiros mian opinion."],[32,18,"Ĉar mi estas plena de vortoj; La spirito de mia interno min premas.","Ĉar mi estas plena de vortoj; La spirito de mia interno min premas."],[32,19,"Mia interno estas kiel vino ŝtopfermita, Kiu krevigas novan felsakon.","Mia interno estas kiel vino ŝtopfermita, Kiu krevigas novan felsakon."],[32,20,"Mi ekparolos, kaj tiam fariĝos al mi pli facile; Mi malfermos mian buŝon, kaj mi respondos.","Mi ekparolos, kaj tiam fariĝos al mi pli facile; Mi malfermos mian buŝon, kaj mi respondos."],[32,21,"Mi ne atentos la vizaĝon de persono, Kaj mi ne flatos al homo;","Mi ne atentos la vizaĝon de persono, Kaj mi ne flatos al homo;"],[32,22,"Ĉar mi ne povoscias flati; Aliokaze pereigu min mia Kreinto.","Ĉar mi ne povoscias flati; Aliokaze pereigu min mia Kreinto."],[33,1,"Aŭskultu do, Ijob, miajn parolojn, Kaj atentu ĉiujn miajn vortojn.","Aŭskultu do, Ijob, miajn parolojn, Kaj atentu ĉiujn miajn vortojn."],[33,2,"Jen mi malfermis mian buŝon, Parolas mia lango en mia gorĝo.","Jen mi malfermis mian buŝon, Parolas mia lango en mia gorĝo."],[33,3,"Ĝuste el mia koro estas miaj paroloj, Kaj puran scion eldiros miaj lipoj.","Ĝuste el mia koro estas miaj paroloj, Kaj puran scion eldiros miaj lipoj."],[33,4,"La spirito de Dio min kreis, Kaj la spiro de la Plejpotenculo min vivigas.","La spirito de Dio min kreis, Kaj la spiro de la Plejpotenculo min vivigas."],[33,5,"Se vi povas, respondu al mi; Armu vin kontraŭ mi, kaj stariĝu.","Se vi povas, respondu al mi; Armu vin kontraŭ mi, kaj stariĝu."],[33,6,"Jen mi simile al vi estas de Dio; Mi ankaŭ estas farita el argilo.","Jen mi simile al vi estas de Dio; Mi ankaŭ estas farita el argilo."],[33,7,"Vidu, vi ne bezonas timi min, Kaj mia ŝarĝo ne pezos sur vi.","Vidu, vi ne bezonas timi min, Kaj mia ŝarĝo ne pezos sur vi."],[33,8,"Vi parolis antaŭ miaj oreloj, Kaj mi aŭdis la sonon de tiaj vortoj:","Vi parolis antaŭ miaj oreloj, Kaj mi aŭdis la sonon de tiaj vortoj:"],[33,9,"Mi estas pura, sen malbonagoj; Senkulpa, mi ne havas pekon;","Mi estas pura, sen malbonagoj; Senkulpa, mi ne havas pekon;"],[33,10,"Jen Li trovis ion riproĉindan en mi, Li rigardas min kiel Lian malamikon;","Jen Li trovis ion riproĉindan en mi, Li rigardas min kiel Lian malamikon;"],[33,11,"Li metis miajn piedojn en ŝtipon; Li observas ĉiujn miajn vojojn.","Li metis miajn piedojn en ŝtipon; Li observas ĉiujn miajn vojojn."],[33,12,"Sed en tio vi ne estas prava, mi respondas al vi; Ĉar Dio estas pli granda ol homo.","Sed en tio vi ne estas prava, mi respondas al vi; Ĉar Dio estas pli granda ol homo."],[33,13,"Kial vi havas pretendon kontraŭ Li pro tio, Ke Li ne donas al vi kalkulraporton pri ĉiuj Siaj faroj?","Kial vi havas pretendon kontraŭ Li pro tio, Ke Li ne donas al vi kalkulraporton pri ĉiuj Siaj faroj?"],[33,14,"Cetere Dio parolas en unu maniero kaj en alia maniero, Sed oni tion ne rimarkas.","Cetere Dio parolas en unu maniero kaj en alia maniero, Sed oni tion ne rimarkas."],[33,15,"En sonĝo, en nokta vizio, Kiam sur la homojn falis dormo, Kiam ili dormas sur la lito,","En sonĝo, en nokta vizio, Kiam sur la homojn falis dormo, Kiam ili dormas sur la lito,"],[33,16,"Tiam Li malfermas la orelon de la homoj, Kaj, doninte instruon, sigelas ĝin,","Tiam Li malfermas la orelon de la homoj, Kaj, doninte instruon, sigelas ĝin,"],[33,17,"Por deturni homon de ia faro Kaj gardi viron kontraŭ fiereco,","Por deturni homon de ia faro Kaj gardi viron kontraŭ fiereco,"],[33,18,"Por ŝirmi lian animon kontraŭ pereo Kaj lian vivon kontraŭ falo sub glavon.","Por ŝirmi lian animon kontraŭ pereo Kaj lian vivon kontraŭ falo sub glavon."],[33,19,"Ankaŭ per malsano sur lia lito Li avertas lin, Kiam ĉiuj liaj ostoj estas ankoraŭ fortaj.","Ankaŭ per malsano sur lia lito Li avertas lin, Kiam ĉiuj liaj ostoj estas ankoraŭ fortaj."],[33,20,"Kaj abomenata fariĝas por li en lia vivo la manĝaĵo, Kaj por lia animo la frandaĵo.","Kaj abomenata fariĝas por li en lia vivo la manĝaĵo, Kaj por lia animo la frandaĵo."],[33,21,"Lia karno konsumiĝas tiel, ke oni ĝin jam ne vidas; Kaj elstaras liaj ostoj, kiuj antaŭe estis nevideblaj.","Lia karno konsumiĝas tiel, ke oni ĝin jam ne vidas; Kaj elstaras liaj ostoj, kiuj antaŭe estis nevideblaj."],[33,22,"Kaj lia animo alproksimiĝas al la pereo, Kaj lia vivo al la mortigo.","Kaj lia animo alproksimiĝas al la pereo, Kaj lia vivo al la mortigo."],[33,23,"Sed se li havas por si anĝelon proparolanton, Kvankam unu el mil, Kiu elmontrus pri la homo lian pravecon,","Sed se li havas por si anĝelon proparolanton, Kvankam unu el mil, Kiu elmontrus pri la homo lian pravecon,"],[33,24,"Tiam Li indulgas lin, kaj diras: Liberigu lin, ke li ne malsupreniru en la tombon, Ĉar Mi trovis pardonigon.","Tiam Li indulgas lin, kaj diras: Liberigu lin, ke li ne malsupreniru en la tombon, Ĉar Mi trovis pardonigon."],[33,25,"Tiam lia korpo fariĝas denove freŝa, kiel en la juneco; Li revenas al la tagoj de sia knabeco.","Tiam lia korpo fariĝas denove freŝa, kiel en la juneco; Li revenas al la tagoj de sia knabeco."],[33,26,"Li preĝas al Dio, Kaj ĉi Tiu korfavoras lin, Kaj montras al li Sian vizaĝon kun ĝojo, Kaj rekompencas la homon laŭ lia virteco.","Li preĝas al Dio, Kaj ĉi Tiu korfavoras lin, Kaj montras al li Sian vizaĝon kun ĝojo, Kaj rekompencas la homon laŭ lia virteco."],[33,27,"Li rigardas la homojn, kaj diras: Mi pekis, la veron mi kripligis, Kaj Li ne repagis al mi;","Li rigardas la homojn, kaj diras: Mi pekis, la veron mi kripligis, Kaj Li ne repagis al mi;"],[33,28,"Li liberigis mian animon, ke ĝi ne iru en pereon, Kaj mia vivo vidas la lumon.","Li liberigis mian animon, ke ĝi ne iru en pereon, Kaj mia vivo vidas la lumon."],[33,29,"Ĉion ĉi tion Dio faras Du aŭ tri fojojn kun homo,","Ĉion ĉi tion Dio faras Du aŭ tri fojojn kun homo,"],[33,30,"Por deturni lian animon de pereo Kaj prilumi lin per la lumo de vivo.","Por deturni lian animon de pereo Kaj prilumi lin per la lumo de vivo."],[33,31,"Atentu, Ijob, aŭskultu min; Silentu, kaj mi parolos.","Atentu, Ijob, aŭskultu min; Silentu, kaj mi parolos."],[33,32,"Se vi havas, kion diri, respondu al mi; Parolu, ĉar mi dezirus, ke vi montriĝu prava.","Se vi havas, kion diri, respondu al mi; Parolu, ĉar mi dezirus, ke vi montriĝu prava."],[33,33,"Se ne, tiam aŭskultu min; Silentu, kaj mi instruos al vi saĝon.","Se ne, tiam aŭskultu min; Silentu, kaj mi instruos al vi saĝon."],[34,1,"Elihu parolis plue, kaj diris:","Elihu parolis plue, kaj diris:"],[34,2,"Aŭskultu, saĝuloj, miajn vortojn; Kaj vi, kompetentuloj, atentu min.","Aŭskultu, saĝuloj, miajn vortojn; Kaj vi, kompetentuloj, atentu min."],[34,3,"Ĉar la orelo esploras la parolon, Kiel la palato gustumas la manĝaĵon.","Ĉar la orelo esploras la parolon, Kiel la palato gustumas la manĝaĵon."],[34,4,"Decidon ni elektu al ni; Ni esploru inter ni, kio estas bona.","Decidon ni elektu al ni; Ni esploru inter ni, kio estas bona."],[34,5,"Ĉar Ijob diris: Mi estas prava, Sed Dio forigis mian rajton;","Ĉar Ijob diris: Mi estas prava, Sed Dio forigis mian rajton;"],[34,6,"En mia juĝa afero mi estas refutata; Turmentas min mia sago, kvankam mi estas senkulpa.","En mia juĝa afero mi estas refutata; Turmentas min mia sago, kvankam mi estas senkulpa."],[34,7,"Kiu homo estas simila al Ijob, Kiu trinkas mokojn kiel akvon?","Kiu homo estas simila al Ijob, Kiu trinkas mokojn kiel akvon?"],[34,8,"Kaj li estas preta aliĝi al malbonaguloj Kaj iri kun malpiuloj;","Kaj li estas preta aliĝi al malbonaguloj Kaj iri kun malpiuloj;"],[34,9,"Ĉar li diras: Homo ne havas utilon, Se li serĉas favoron de Dio.","Ĉar li diras: Homo ne havas utilon, Se li serĉas favoron de Dio."],[34,10,"Tial aŭskultu min, ho saĝaj homoj: Dio estas malproksima de malbonagoj, Kaj la Plejpotenculo estas malproksima de maljusteco;","Tial aŭskultu min, ho saĝaj homoj: Dio estas malproksima de malbonagoj, Kaj la Plejpotenculo estas malproksima de maljusteco;"],[34,11,"Sed Li repagas al homo laŭ liaj agoj, Kaj laŭ la vojo de ĉiu Li renkontas lin.","Sed Li repagas al homo laŭ liaj agoj, Kaj laŭ la vojo de ĉiu Li renkontas lin."],[34,12,"Vere, Dio ne malbonagas, Kaj la Plejpotenculo ne kurbigas la veron.","Vere, Dio ne malbonagas, Kaj la Plejpotenculo ne kurbigas la veron."],[34,13,"Kiu komisiis al Li la teron? Kaj kiu starigis Lin super la tuta mondo?","Kiu komisiis al Li la teron? Kaj kiu starigis Lin super la tuta mondo?"],[34,14,"Se Li pensus nur pri Si, Se Li prenus al Si Sian spiriton kaj spiron,","Se Li pensus nur pri Si, Se Li prenus al Si Sian spiriton kaj spiron,"],[34,15,"Tiam pereus absolute ĉiu karno, Kaj homo refariĝus polvo.","Tiam pereus absolute ĉiu karno, Kaj homo refariĝus polvo."],[34,16,"Se vi havas prudenton, aŭskultu ĉi tion; Atentu la voĉon de miaj paroloj.","Se vi havas prudenton, aŭskultu ĉi tion; Atentu la voĉon de miaj paroloj."],[34,17,"Ĉu povas regi malamanto de justeco? Ĉu vi povas akuzi la Plejjustulon?","Ĉu povas regi malamanto de justeco? Ĉu vi povas akuzi la Plejjustulon?"],[34,18,"Ĉu oni povas diris al reĝo: Sentaŭgulo; Aŭ al altranguloj: Malpiulo?","Ĉu oni povas diris al reĝo: Sentaŭgulo; Aŭ al altranguloj: Malpiulo?"],[34,19,"Sed Li ne atentas la vizaĝon de princoj, Kaj ne preferas riĉulon antaŭ malriĉulo; Ĉar ĉiuj estas faritaĵo de Liaj manoj.","Sed Li ne atentas la vizaĝon de princoj, Kaj ne preferas riĉulon antaŭ malriĉulo; Ĉar ĉiuj estas faritaĵo de Liaj manoj."],[34,20,"Momente ili mortas, noktomeze ili tumultiĝas kaj malaperas; Ne de homa mano estas forigataj la potenculoj.","Momente ili mortas, noktomeze ili tumultiĝas kaj malaperas; Ne de homa mano estas forigataj la potenculoj."],[34,21,"Ĉar Liaj okuloj estas super la vojoj de homo, Kaj ĉiujn liajn paŝojn Li vidas.","Ĉar Liaj okuloj estas super la vojoj de homo, Kaj ĉiujn liajn paŝojn Li vidas."],[34,22,"Ne ekzistas mallumo nek ombrego, Kie povus sin kaŝi malbonaguloj.","Ne ekzistas mallumo nek ombrego, Kie povus sin kaŝi malbonaguloj."],[34,23,"Li ne bezonas multe klopodi kun homo, Ke li iru al Dio por juĝo.","Li ne bezonas multe klopodi kun homo, Ke li iru al Dio por juĝo."],[34,24,"Li pereigas la fortulojn sennombre Kaj starigas sur ilia loko aliajn;","Li pereigas la fortulojn sennombre Kaj starigas sur ilia loko aliajn;"],[34,25,"Ĉar Li scias iliajn farojn; Li renversas ilin en la nokto, kaj ili frakasiĝas.","Ĉar Li scias iliajn farojn; Li renversas ilin en la nokto, kaj ili frakasiĝas."],[34,26,"Kiel malpiulojn Li frapas ilin sur loko, kie ĉiuj vidas;","Kiel malpiulojn Li frapas ilin sur loko, kie ĉiuj vidas;"],[34,27,"Pro tio, ke ili forturniĝis de Li Kaj ne penis kompreni ĉiujn Liajn vojojn,","Pro tio, ke ili forturniĝis de Li Kaj ne penis kompreni ĉiujn Liajn vojojn,"],[34,28,"Sed venigis al Li la kriadon de malriĉulo, Kaj Li aŭdis la kriadon de mizeruloj.","Sed venigis al Li la kriadon de malriĉulo, Kaj Li aŭdis la kriadon de mizeruloj."],[34,29,"Se Li kvietigas, tiam kiu povas ribeligi? Se Li kaŝas Sian vizaĝon, tiam kiu povas Lin vidi? Tiel estas egale kun nacio kaj kun aparta homo,","Se Li kvietigas, tiam kiu povas ribeligi? Se Li kaŝas Sian vizaĝon, tiam kiu povas Lin vidi? Tiel estas egale kun nacio kaj kun aparta homo,"],[34,30,"Por ke ne regu homo hipokrita, El la pekigantoj de popolo.","Por ke ne regu homo hipokrita, El la pekigantoj de popolo."],[34,31,"Al Dio oni devas diri: Mi fieriĝis, mi ne plu faros malbonon;","Al Dio oni devas diri: Mi fieriĝis, mi ne plu faros malbonon;"],[34,32,"Kion mi ne vidas, pri tio instruu min; Se mi faris maljustaĵon, mi ne plu faros.","Kion mi ne vidas, pri tio instruu min; Se mi faris maljustaĵon, mi ne plu faros."],[34,33,"Ĉu konforme al via opinio Li devas repagi? Al vi ja ne plaĉis. Vi elektu, ne mi; Kaj kion vi scias, tion diru.","Ĉu konforme al via opinio Li devas repagi? Al vi ja ne plaĉis. Vi elektu, ne mi; Kaj kion vi scias, tion diru."],[34,34,"Saĝaj homoj diros al mi, Kaj prudenta homo, kiu min aŭskultas:","Saĝaj homoj diros al mi, Kaj prudenta homo, kiu min aŭskultas:"],[34,35,"Ijob parolas malsaĝe, Kaj liaj vortoj estas malprudentaj.","Ijob parolas malsaĝe, Kaj liaj vortoj estas malprudentaj."],[34,36,"Ho, se Ijob estus elprovita ĝis la fino, Pro tio, ke li aliĝas al homoj pekaj;","Ho, se Ijob estus elprovita ĝis la fino, Pro tio, ke li aliĝas al homoj pekaj;"],[34,37,"Ĉar al sia peko li aldonas blasfemon; Inter ni li mokas, kaj multe parolas kontraŭ Dio.","Ĉar al sia peko li aldonas blasfemon; Inter ni li mokas, kaj multe parolas kontraŭ Dio."],[35,1,"Elihu parolis plue, kaj diris:","Elihu parolis plue, kaj diris:"],[35,2,"Ĉu tion vi opinias justa, ke vi diras: Mi estas pli prava ol Dio?","Ĉu tion vi opinias justa, ke vi diras: Mi estas pli prava ol Dio?"],[35,3,"Ĉar vi diras: Kiom tio utilas al vi? Kian profiton mi havas kompare kun tiu okazo, se mi pekus?","Ĉar vi diras: Kiom tio utilas al vi? Kian profiton mi havas kompare kun tiu okazo, se mi pekus?"],[35,4,"Mi respondos al vi, Kaj kune ankaŭ al viaj amikoj:","Mi respondos al vi, Kaj kune ankaŭ al viaj amikoj:"],[35,5,"Rigardu la ĉielon, kaj vidu; Rigardu la nubojn, kiel tro alte ili estas por vi.","Rigardu la ĉielon, kaj vidu; Rigardu la nubojn, kiel tro alte ili estas por vi."],[35,6,"Se vi pekas, kiom vi malutilas al Li? Kaj se viaj malbonagoj estas multaj, kion vi faras al Li?","Se vi pekas, kiom vi malutilas al Li? Kaj se viaj malbonagoj estas multaj, kion vi faras al Li?"],[35,7,"Se vi estas virta, kion vi donas al Li? Aŭ kion Li prenas el via mano?","Se vi estas virta, kion vi donas al Li? Aŭ kion Li prenas el via mano?"],[35,8,"Al homo, simila al vi, povas ion fari via malbonago, Kaj via virteco havas signifon nur por homido.","Al homo, simila al vi, povas ion fari via malbonago, Kaj via virteco havas signifon nur por homido."],[35,9,"Pro multe da premado oni krias; Oni ĝemas pro la brako de potenculoj.","Pro multe da premado oni krias; Oni ĝemas pro la brako de potenculoj."],[35,10,"Sed oni ne diras: Kie estas Dio, kiu min kreis, Kiu donas kantojn en la nokto,","Sed oni ne diras: Kie estas Dio, kiu min kreis, Kiu donas kantojn en la nokto,"],[35,11,"Kiu instruas nin pli ol la brutojn sur la tero, Prudentigas nin pli ol la birdojn de la ĉielo?","Kiu instruas nin pli ol la brutojn sur la tero, Prudentigas nin pli ol la birdojn de la ĉielo?"],[35,12,"Tie ili krias pri la fiereco de la malbonuloj, Sed Li ne respondas.","Tie ili krias pri la fiereco de la malbonuloj, Sed Li ne respondas."],[35,13,"Tamen malvere estas, ke Dio ne aŭdas Kaj ke la Plejpotenculo ne vidas.","Tamen malvere estas, ke Dio ne aŭdas Kaj ke la Plejpotenculo ne vidas."],[35,14,"Kvankam vi diras, ke vi Lin ne vidas, Ekzistas tamen juĝo ĉe Li; Kaj vi atendu Lin.","Kvankam vi diras, ke vi Lin ne vidas, Ekzistas tamen juĝo ĉe Li; Kaj vi atendu Lin."],[35,15,"Sed ĉar Li nun ne montras Sian koleron Kaj ne atentas la tro grandan malvirtecon,","Sed ĉar Li nun ne montras Sian koleron Kaj ne atentas la tro grandan malvirtecon,"],[35,16,"Tial Ijob vante malfermis sian buŝon Kaj tre multe parolas malprudente.","Tial Ijob vante malfermis sian buŝon Kaj tre multe parolas malprudente."],[36,1,"Kaj plue parolis Elihu, kaj diris:","Kaj plue parolis Elihu, kaj diris:"],[36,2,"Atendu ankoraŭ iom; mi montros al vi, Ĉar mi havas ankoraŭ kion paroli pro Dio.","Atendu ankoraŭ iom; mi montros al vi, Ĉar mi havas ankoraŭ kion paroli pro Dio."],[36,3,"Mi prenos mian scion de malproksime, Kaj mi montros, ke mia Kreinto estas prava.","Mi prenos mian scion de malproksime, Kaj mi montros, ke mia Kreinto estas prava."],[36,4,"Ĉar vere miaj vortoj ne estas mensogaj; Homo sincera estas antaŭ vi.","Ĉar vere miaj vortoj ne estas mensogaj; Homo sincera estas antaŭ vi."],[36,5,"Vidu, Dio estas potenca, kaj tamen Li neniun malŝatas; Li estas potenca per la forto de la koro.","Vidu, Dio estas potenca, kaj tamen Li neniun malŝatas; Li estas potenca per la forto de la koro."],[36,6,"Al malpiulo Li ne permesas vivi, Kaj al mizeruloj Li donas justecon.","Al malpiulo Li ne permesas vivi, Kaj al mizeruloj Li donas justecon."],[36,7,"Li ne forturnas de virtuloj Siajn okulojn, Sed kun reĝoj sur trono Li sidigas ilin por ĉiam, Por ke ili estu altaj.","Li ne forturnas de virtuloj Siajn okulojn, Sed kun reĝoj sur trono Li sidigas ilin por ĉiam, Por ke ili estu altaj."],[36,8,"Kaj se ili estas ligitaj per ĉenoj, Malliberigitaj mizere per ŝnuroj,","Kaj se ili estas ligitaj per ĉenoj, Malliberigitaj mizere per ŝnuroj,"],[36,9,"Tiam Li montras al ili iliajn farojn kaj kulpojn, Kiel grandaj ili estas.","Tiam Li montras al ili iliajn farojn kaj kulpojn, Kiel grandaj ili estas."],[36,10,"Li malfermas ilian orelon por la moralinstruo, Kaj diras, ke ili deturnu sin de malbonagoj.","Li malfermas ilian orelon por la moralinstruo, Kaj diras, ke ili deturnu sin de malbonagoj."],[36,11,"Se ili obeas kaj servas al Li, Tiam ili finas siajn tagojn en bono Kaj siajn jarojn en stato agrabla;","Se ili obeas kaj servas al Li, Tiam ili finas siajn tagojn en bono Kaj siajn jarojn en stato agrabla;"],[36,12,"Sed se ili ne obeas, Tiam ili pereas per glavo Kaj mortas en malprudento.","Sed se ili ne obeas, Tiam ili pereas per glavo Kaj mortas en malprudento."],[36,13,"La hipokrituloj portas en si koleron; Ili ne vokas, kiam Li ilin ligis;","La hipokrituloj portas en si koleron; Ili ne vokas, kiam Li ilin ligis;"],[36,14,"Ilia animo mortas en juneco, Kaj ilia vivo pereas inter la malĉastuloj.","Ilia animo mortas en juneco, Kaj ilia vivo pereas inter la malĉastuloj."],[36,15,"Li savas la suferanton en lia mizero, Kaj per la sufero Li malfermas ilian orelon.","Li savas la suferanton en lia mizero, Kaj per la sufero Li malfermas ilian orelon."],[36,16,"Ankaŭ vin Li elkondukus el la suferoj En spacon vastan, kie ne ekzistas premateco; Kaj vi havus pacon ĉe via tablo, plena de grasaĵoj.","Ankaŭ vin Li elkondukus el la suferoj En spacon vastan, kie ne ekzistas premateco; Kaj vi havus pacon ĉe via tablo, plena de grasaĵoj."],[36,17,"Sed vi fariĝis plena de kulpoj de malvirtulo; Kulpo kaj juĝo tenas sin kune.","Sed vi fariĝis plena de kulpoj de malvirtulo; Kulpo kaj juĝo tenas sin kune."],[36,18,"Via kolero ne forlogu vin al mokado, Kaj grandeco de elaĉeto ne deklinu vin.","Via kolero ne forlogu vin al mokado, Kaj grandeco de elaĉeto ne deklinu vin."],[36,19,"Ĉu Li atentos vian riĉecon? Ne, nek oron, nek forton aŭ potencon.","Ĉu Li atentos vian riĉecon? Ne, nek oron, nek forton aŭ potencon."],[36,20,"Ne strebu al tiu nokto, Kiu forigas popolojn de ilia loko.","Ne strebu al tiu nokto, Kiu forigas popolojn de ilia loko."],[36,21,"Gardu vin, ne kliniĝu al malpieco; Ĉar tion vi komencis pro la mizero.","Gardu vin, ne kliniĝu al malpieco; Ĉar tion vi komencis pro la mizero."],[36,22,"Vidu, Dio estas alta en Sia forto. Kiu estas tia instruanto, kiel Li?","Vidu, Dio estas alta en Sia forto. Kiu estas tia instruanto, kiel Li?"],[36,23,"Kiu povas preskribi al Li vojon? Kaj kiu povas diri: Vi agis maljuste?","Kiu povas preskribi al Li vojon? Kaj kiu povas diri: Vi agis maljuste?"],[36,24,"Memoru, ke vi honoru Liajn farojn, Pri kiuj kantas la homoj.","Memoru, ke vi honoru Liajn farojn, Pri kiuj kantas la homoj."],[36,25,"Ĉiuj homoj ilin vidas; Homo rigardas ilin de malproksime.","Ĉiuj homoj ilin vidas; Homo rigardas ilin de malproksime."],[36,26,"Vidu, Dio estas granda kaj nekonata; La nombro de Liaj jaroj estas neesplorebla.","Vidu, Dio estas granda kaj nekonata; La nombro de Liaj jaroj estas neesplorebla."],[36,27,"Kiam Li malgrandigas la gutojn de akvo, Ili verŝiĝas pluve el la nebulo;","Kiam Li malgrandigas la gutojn de akvo, Ili verŝiĝas pluve el la nebulo;"],[36,28,"Verŝiĝas la nuboj Kaj gutas sur multe da homoj.","Verŝiĝas la nuboj Kaj gutas sur multe da homoj."],[36,29,"Kaj kiam Li intencas etendi la nubojn Kiel tapiŝojn de Sia tendo,","Kaj kiam Li intencas etendi la nubojn Kiel tapiŝojn de Sia tendo,"],[36,30,"Tiam Li etendas sur ilin Sian lumon Kaj kovras la radikojn de la maro.","Tiam Li etendas sur ilin Sian lumon Kaj kovras la radikojn de la maro."],[36,31,"Ĉar per ili Li juĝas la popolojn Kaj donas ankaŭ manĝaĵon abunde.","Ĉar per ili Li juĝas la popolojn Kaj donas ankaŭ manĝaĵon abunde."],[36,32,"Per la manoj Li kovras la lumon Kaj ordonas al ĝi aperi denove.","Per la manoj Li kovras la lumon Kaj ordonas al ĝi aperi denove."],[36,33,"Antaŭdiras pri ĝi ĝia bruo, Kaj eĉ la brutaroj, kiam ĝi alproksimiĝas.","Antaŭdiras pri ĝi ĝia bruo, Kaj eĉ la brutaroj, kiam ĝi alproksimiĝas."],[37,1,"Pri tio tremas mia koro Kaj saltas de sia loko.","Pri tio tremas mia koro Kaj saltas de sia loko."],[37,2,"Aŭskultu atente en la bruo Lian voĉon, Kaj la sonojn, kiuj eliras el Lia buŝo.","Aŭskultu atente en la bruo Lian voĉon, Kaj la sonojn, kiuj eliras el Lia buŝo."],[37,3,"Sub la tutan ĉielon Li kurigas tion, Kaj Sian lumon al la randoj de la tero.","Sub la tutan ĉielon Li kurigas tion, Kaj Sian lumon al la randoj de la tero."],[37,4,"Post ĝi ekbruas la tondro; Li tondras per Sia majesta voĉo, Kaj oni ne povas tion haltigi, kiam aŭdiĝas Lia voĉo.","Post ĝi ekbruas la tondro; Li tondras per Sia majesta voĉo, Kaj oni ne povas tion haltigi, kiam aŭdiĝas Lia voĉo."],[37,5,"Mirinde tondras Dio per Sia voĉo; Li faras ion grandan, sed ne konatan.","Mirinde tondras Dio per Sia voĉo; Li faras ion grandan, sed ne konatan."],[37,6,"Al la neĝo Li diras: Falu sur la teron; Ankaŭ al la pluvego, al Siaj fortaj pluvegoj.","Al la neĝo Li diras: Falu sur la teron; Ankaŭ al la pluvego, al Siaj fortaj pluvegoj."],[37,7,"Sur la manon de ĉiu homo Li metas sigelon, Por ke ĉiuj homoj sciu Lian faron.","Sur la manon de ĉiu homo Li metas sigelon, Por ke ĉiuj homoj sciu Lian faron."],[37,8,"La sovaĝa besto iras en sian kavon Kaj restas en sia loĝejo.","La sovaĝa besto iras en sian kavon Kaj restas en sia loĝejo."],[37,9,"El la sudo venas ventego, Kaj de la nordo venas malvarmo.","El la sudo venas ventego, Kaj de la nordo venas malvarmo."],[37,10,"De la spiro de Dio venas frosto, Kaj vasta akvo fariĝas kvazaŭ fandaĵo.","De la spiro de Dio venas frosto, Kaj vasta akvo fariĝas kvazaŭ fandaĵo."],[37,11,"La nubojn Li pezigas per akvo, Kaj nubo disŝutas Lian lumon.","La nubojn Li pezigas per akvo, Kaj nubo disŝutas Lian lumon."],[37,12,"Li direktas ilin ĉirkaŭen, kien Li volas, Por ke ili plenumu ĉion, kion Li ordonas al ili, sur la tero:","Li direktas ilin ĉirkaŭen, kien Li volas, Por ke ili plenumu ĉion, kion Li ordonas al ili, sur la tero:"],[37,13,"Ĉu por puno de ia lando, Ĉu por favorkoraĵo Li ilin direktas.","Ĉu por puno de ia lando, Ĉu por favorkoraĵo Li ilin direktas."],[37,14,"Atentu tion, Ijob; Staru, kaj konsideru la miraklojn de Dio.","Atentu tion, Ijob; Staru, kaj konsideru la miraklojn de Dio."],[37,15,"Ĉu vi scias, kiamaniere Dio agigas ilin Kaj aperigas lumon el Sia nubo?","Ĉu vi scias, kiamaniere Dio agigas ilin Kaj aperigas lumon el Sia nubo?"],[37,16,"Ĉu vi komprenas, ĉe la distiro de nubo, La miraklojn de Tiu, kiu estas la plej perfekta en la sciado?","Ĉu vi komprenas, ĉe la distiro de nubo, La miraklojn de Tiu, kiu estas la plej perfekta en la sciado?"],[37,17,"Kiamaniere viaj vestoj varmiĝas, Kiam la tero kvietiĝas de sude?","Kiamaniere viaj vestoj varmiĝas, Kiam la tero kvietiĝas de sude?"],[37,18,"Ĉu vi povas etendi kun Li la ĉielon, Firman kiel fandita spegulo?","Ĉu vi povas etendi kun Li la ĉielon, Firman kiel fandita spegulo?"],[37,19,"Sciigu al ni, kion ni devas diri al Li; Mi nenion povas elkonjekti pro mallumo.","Sciigu al ni, kion ni devas diri al Li; Mi nenion povas elkonjekti pro mallumo."],[37,20,"Ĉu estos rakontita al Li tio, kion mi parolas? Se iu parolos, li pereos.","Ĉu estos rakontita al Li tio, kion mi parolas? Se iu parolos, li pereos."],[37,21,"Nun oni ne povas rigardi la lumon, kiu hele lumas en la ĉielo, Kiam la vento pasas kaj purigas ĝin.","Nun oni ne povas rigardi la lumon, kiu hele lumas en la ĉielo, Kiam la vento pasas kaj purigas ĝin."],[37,22,"De norde venas oro; Ĉirkaŭ Dio estas terura brilo.","De norde venas oro; Ĉirkaŭ Dio estas terura brilo."],[37,23,"La Plejpotenculon ni ne povas kompreni. Li estas granda en forto, justo, kaj vero; Li neniun premas.","La Plejpotenculon ni ne povas kompreni. Li estas granda en forto, justo, kaj vero; Li neniun premas."],[37,24,"Tial respektegas Lin la homoj; Kaj Li atentas neniun el la saĝuloj.","Tial respektegas Lin la homoj; Kaj Li atentas neniun el la saĝuloj."],[38,1,"La Eternulo el ventego ekparolis al Ijob, kaj diris:","La Eternulo el ventego ekparolis al Ijob, kaj diris:"],[38,2,"Kiu estas tiu, kiu mallumigas la plej altan decidon Per vortoj sensencaj?","Kiu estas tiu, kiu mallumigas la plej altan decidon Per vortoj sensencaj?"],[38,3,"Zonu kiel viro viajn lumbojn; Mi vin demandos, kaj vi sciigu al Mi.","Zonu kiel viro viajn lumbojn; Mi vin demandos, kaj vi sciigu al Mi."],[38,4,"Kie vi estis, kiam Mi fondis la teron? Diru, se vi havas scion.","Kie vi estis, kiam Mi fondis la teron? Diru, se vi havas scion."],[38,5,"Kiu starigis ĝiajn mezurojn, se vi tion scias? Aŭ kiu etendis super ĝi rektoŝnuron?","Kiu starigis ĝiajn mezurojn, se vi tion scias? Aŭ kiu etendis super ĝi rektoŝnuron?"],[38,6,"Sur kio estas enfortikigitaj ĝiaj bazoj, Aŭ kiu kuŝigis ĝian angulŝtonon,","Sur kio estas enfortikigitaj ĝiaj bazoj, Aŭ kiu kuŝigis ĝian angulŝtonon,"],[38,7,"Dum komuna glorkantado de la matenaj steloj Kaj ĝojkriado de ĉiuj filoj de Dio?","Dum komuna glorkantado de la matenaj steloj Kaj ĝojkriado de ĉiuj filoj de Dio?"],[38,8,"Kiu fermis la maron per pordoj, Kiam ĝi elpuŝiĝis kvazaŭ el la ventro de patrino;","Kiu fermis la maron per pordoj, Kiam ĝi elpuŝiĝis kvazaŭ el la ventro de patrino;"],[38,9,"Kiam Mi faris la nubon ĝia vesto Kaj mallumon ĝiaj vindaĵoj,","Kiam Mi faris la nubon ĝia vesto Kaj mallumon ĝiaj vindaĵoj,"],[38,10,"Kaj starigis al ĝi limon Kaj faris riglilojn kaj pordojn,","Kaj starigis al ĝi limon Kaj faris riglilojn kaj pordojn,"],[38,11,"Kaj diris: Ĝis ĉi tie aliru, sed ne plu, Kaj ĉi tie rompiĝados viaj majestaj ondoj?","Kaj diris: Ĝis ĉi tie aliru, sed ne plu, Kaj ĉi tie rompiĝados viaj majestaj ondoj?"],[38,12,"Ĉu vi en via vivo iam ordonis al la mateno, Montris al la matenruĝo ĝian lokon,","Ĉu vi en via vivo iam ordonis al la mateno, Montris al la matenruĝo ĝian lokon,"],[38,13,"Ke ĝi kaptu la randojn de la tero, Kaj ke la malpiuloj deskuiĝu el ĝi;","Ke ĝi kaptu la randojn de la tero, Kaj ke la malpiuloj deskuiĝu el ĝi;"],[38,14,"Ke ilia internaĵo renversiĝu kiel koto, Kaj ke ili tute konfuziĝu;","Ke ilia internaĵo renversiĝu kiel koto, Kaj ke ili tute konfuziĝu;"],[38,15,"Ke de la malpiuloj forpreniĝu ilia lumo, Kaj ilia malhumila brako estu rompita?","Ke de la malpiuloj forpreniĝu ilia lumo, Kaj ilia malhumila brako estu rompita?"],[38,16,"Ĉu vi venis ĝis la fontoj de la maro? Kaj ĉu vi iradis sur la fundo de la abismo?","Ĉu vi venis ĝis la fontoj de la maro? Kaj ĉu vi iradis sur la fundo de la abismo?"],[38,17,"Ĉu malfermiĝis antaŭ vi la pordego de la morto? Kaj ĉu vi vidis la pordegon de la mallumego?","Ĉu malfermiĝis antaŭ vi la pordego de la morto? Kaj ĉu vi vidis la pordegon de la mallumego?"],[38,18,"Ĉu vi pririgardis la larĝon de la tero? Diru, ĉu vi scias ĉion ĉi tion?","Ĉu vi pririgardis la larĝon de la tero? Diru, ĉu vi scias ĉion ĉi tion?"],[38,19,"Kie estas la vojo al la loĝejo de la lumo, Kaj kie estas la loko de la mallumo,","Kie estas la vojo al la loĝejo de la lumo, Kaj kie estas la loko de la mallumo,"],[38,20,"Ke vi konduku ĝin al ĝia limo, Kaj ke vi rimarku la vojetojn al ĝia domo?","Ke vi konduku ĝin al ĝia limo, Kaj ke vi rimarku la vojetojn al ĝia domo?"],[38,21,"Ĉu vi sciis, kiam vi naskiĝos Kaj kiel granda estos la nombro de viaj tagoj?","Ĉu vi sciis, kiam vi naskiĝos Kaj kiel granda estos la nombro de viaj tagoj?"],[38,22,"Ĉu vi venis al la devenejo de la neĝo, Kaj ĉu vi vidis la devenejon de la hajlo,","Ĉu vi venis al la devenejo de la neĝo, Kaj ĉu vi vidis la devenejon de la hajlo,"],[38,23,"Kiujn Mi konservas por la tempo de suferado, Por la tago de batalo kaj milito?","Kiujn Mi konservas por la tempo de suferado, Por la tago de batalo kaj milito?"],[38,24,"Kie estas la vojo, laŭ kiu dividiĝas la lumo, Diskuras la orienta vento super la teron?","Kie estas la vojo, laŭ kiu dividiĝas la lumo, Diskuras la orienta vento super la teron?"],[38,25,"Kiu destinis direkton por la fluo Kaj vojon por la tondra fulmo,","Kiu destinis direkton por la fluo Kaj vojon por la tondra fulmo,"],[38,26,"Por doni pluvon sur teron, kie neniu troviĝas, Sur dezerton senhoman,","Por doni pluvon sur teron, kie neniu troviĝas, Sur dezerton senhoman,"],[38,27,"Por nutri dezerton kaj stepon Kaj kreskigi verdan herbon?","Por nutri dezerton kaj stepon Kaj kreskigi verdan herbon?"],[38,28,"Ĉu la pluvo havas patron? Aŭ kiu naskigis la gutojn de roso?","Ĉu la pluvo havas patron? Aŭ kiu naskigis la gutojn de roso?"],[38,29,"El kies ventro eliris la glacio? Kaj kiu naskis la prujnon sub la ĉielo?","El kies ventro eliris la glacio? Kaj kiu naskis la prujnon sub la ĉielo?"],[38,30,"Simile al ŝtono malmoliĝas la akvo, Kaj la supraĵo de la abismo kunfirmiĝas.","Simile al ŝtono malmoliĝas la akvo, Kaj la supraĵo de la abismo kunfirmiĝas."],[38,31,"Ĉu vi povas ligi la ligilon de la Plejadoj? Aŭ ĉu vi povas malligi la ligon de Oriono?","Ĉu vi povas ligi la ligilon de la Plejadoj? Aŭ ĉu vi povas malligi la ligon de Oriono?"],[38,32,"Ĉu vi povas elirigi iliatempe la planedojn, Kaj konduki la Ursinon kun ĝiaj infanoj?","Ĉu vi povas elirigi iliatempe la planedojn, Kaj konduki la Ursinon kun ĝiaj infanoj?"],[38,33,"Ĉu vi konas la leĝojn de la ĉielo? Aŭ ĉu vi povas aranĝi ĝian regadon super la tero?","Ĉu vi konas la leĝojn de la ĉielo? Aŭ ĉu vi povas aranĝi ĝian regadon super la tero?"],[38,34,"Ĉu vi povas levi al la nubo vian voĉon, Ke abundo da akvo vin kovru?","Ĉu vi povas levi al la nubo vian voĉon, Ke abundo da akvo vin kovru?"],[38,35,"Ĉu vi povas sendi fulmojn, Ke ili iru kaj diru al vi: Jen ni estas?","Ĉu vi povas sendi fulmojn, Ke ili iru kaj diru al vi: Jen ni estas?"],[38,36,"Kiu metis en la internon la saĝon? Kaj kiu donis al la koro la prudenton?","Kiu metis en la internon la saĝon? Kaj kiu donis al la koro la prudenton?"],[38,37,"Kiu estas tiel saĝa, ke li povu kalkuli la nubojn? Kaj kiu elverŝas la felsakojn de la ĉielo,","Kiu estas tiel saĝa, ke li povu kalkuli la nubojn? Kaj kiu elverŝas la felsakojn de la ĉielo,"],[38,38,"Kiam la polvo kunfandiĝas Kaj la terbuloj kungluiĝas?","Kiam la polvo kunfandiĝas Kaj la terbuloj kungluiĝas?"],[38,39,"Ĉu vi ĉasas kaptaĵon por la leonino, Kaj satigas la leonidojn,","Ĉu vi ĉasas kaptaĵon por la leonino, Kaj satigas la leonidojn,"],[38,40,"Kiam ili kuŝas en la nestegoj, Sidas embuske en la laŭbo?","Kiam ili kuŝas en la nestegoj, Sidas embuske en la laŭbo?"],[38,41,"Kiu pretigas al la korvo ĝian manĝaĵon, Kiam ĝiaj idoj krias al Dio, Vagflugas, ne havante, kion manĝi?","Kiu pretigas al la korvo ĝian manĝaĵon, Kiam ĝiaj idoj krias al Dio, Vagflugas, ne havante, kion manĝi?"],[39,1,"Ĉu vi scias la tempon, en kiu naskas la ibeksoj sur la rokoj? Ĉu vi observis la akuŝiĝon de la cervinoj?","Ĉu vi scias la tempon, en kiu naskas la ibeksoj sur la rokoj? Ĉu vi observis la akuŝiĝon de la cervinoj?"],[39,2,"Ĉu vi kalkulis la monatojn de ilia gravedeco? Aŭ ĉu vi scias la tempon, kiam ili devas naski?","Ĉu vi kalkulis la monatojn de ilia gravedeco? Aŭ ĉu vi scias la tempon, kiam ili devas naski?"],[39,3,"Ili fleksiĝas, elĵetas siajn idojn, Liberiĝas de siaj doloroj.","Ili fleksiĝas, elĵetas siajn idojn, Liberiĝas de siaj doloroj."],[39,4,"Iliaj infanoj fortiĝas, kreskas en libereco, Foriras, ke ne revenas al ili.","Iliaj infanoj fortiĝas, kreskas en libereco, Foriras, ke ne revenas al ili."],[39,5,"Kiu donis liberecon al la sovaĝa azeno? Kaj kiu malligis ĝiajn ligilojn?","Kiu donis liberecon al la sovaĝa azeno? Kaj kiu malligis ĝiajn ligilojn?"],[39,6,"La dezerton Mi faris ĝia domo, Kaj stepon ĝia loĝejo;","La dezerton Mi faris ĝia domo, Kaj stepon ĝia loĝejo;"],[39,7,"Ĝi ridas pri la bruo de la urbo, La kriojn de pelanto ĝi ne aŭdas;","Ĝi ridas pri la bruo de la urbo, La kriojn de pelanto ĝi ne aŭdas;"],[39,8,"La produktaĵoj de la montoj estas ĝia manĝaĵo, Kaj ĝi serĉas ĉian verdaĵon.","La produktaĵoj de la montoj estas ĝia manĝaĵo, Kaj ĝi serĉas ĉian verdaĵon."],[39,9,"Ĉu bubalo volos servi al vi? Ĉu ĝi volos nokti ĉe via manĝujo?","Ĉu bubalo volos servi al vi? Ĉu ĝi volos nokti ĉe via manĝujo?"],[39,10,"Ĉu vi povas alligi bubalon per ŝnuro al bedo? Ĉu ĝi erpos post vi valojn?","Ĉu vi povas alligi bubalon per ŝnuro al bedo? Ĉu ĝi erpos post vi valojn?"],[39,11,"Ĉu vi fidos ĝin pro ĝia granda forto? Kaj ĉu vi komisios al ĝi vian laboron?","Ĉu vi fidos ĝin pro ĝia granda forto? Kaj ĉu vi komisios al ĝi vian laboron?"],[39,12,"Ĉu vi havos konfidon al ĝi, ke ĝi reportos viajn semojn Kaj kolektos en vian grenejon?","Ĉu vi havos konfidon al ĝi, ke ĝi reportos viajn semojn Kaj kolektos en vian grenejon?"],[39,13,"La flugilo de struto leviĝas gaje, Simile al la flugilo de cikonio kaj de akcipitro;","La flugilo de struto leviĝas gaje, Simile al la flugilo de cikonio kaj de akcipitro;"],[39,14,"Ĉar ĝi lasas sur la tero siajn ovojn Kaj varmigas ilin en la sablo;","Ĉar ĝi lasas sur la tero siajn ovojn Kaj varmigas ilin en la sablo;"],[39,15,"Ĝi forgesas, ke piedo povas ilin dispremi Kaj sovaĝa besto povas ilin disbati.","Ĝi forgesas, ke piedo povas ilin dispremi Kaj sovaĝa besto povas ilin disbati."],[39,16,"Ĝi estas kruela por siaj idoj, kvazaŭ ili ne estus ĝiaj; Ĝi ne zorgas pri tio, ke ĝia laboro estas vana;","Ĝi estas kruela por siaj idoj, kvazaŭ ili ne estus ĝiaj; Ĝi ne zorgas pri tio, ke ĝia laboro estas vana;"],[39,17,"Ĉar Dio senigis ĝin je saĝo Kaj ne donis al ĝi prudenton.","Ĉar Dio senigis ĝin je saĝo Kaj ne donis al ĝi prudenton."],[39,18,"Kiam ĝi leviĝas alten, Ĝi mokas ĉevalon kaj ĝian rajdanton.","Kiam ĝi leviĝas alten, Ĝi mokas ĉevalon kaj ĝian rajdanton."],[39,19,"Ĉu vi donas forton al la ĉevalo? Ĉu vi vestas ĝian kolon per kolharoj?","Ĉu vi donas forton al la ĉevalo? Ĉu vi vestas ĝian kolon per kolharoj?"],[39,20,"Ĉu vi povas saltigi ĝin kiel akrido? Terura estas la beleco de ĝia ronkado.","Ĉu vi povas saltigi ĝin kiel akrido? Terura estas la beleco de ĝia ronkado."],[39,21,"Ĝi fosas en la valo kaj estas gaja pro forteco; Ĝi eliras kontraŭ armiton;","Ĝi fosas en la valo kaj estas gaja pro forteco; Ĝi eliras kontraŭ armiton;"],[39,22,"Ĝi ridas pri timo kaj ne senkuraĝiĝas, Kaj ne retiras sin de glavo.","Ĝi ridas pri timo kaj ne senkuraĝiĝas, Kaj ne retiras sin de glavo."],[39,23,"Super ĝi sonoras la sagujo, Brilas lanco kaj ponardego.","Super ĝi sonoras la sagujo, Brilas lanco kaj ponardego."],[39,24,"Kun bruo kaj kolero ĝi glutas teron, Kaj ne povas stari trankvile ĉe sonado de trumpeto.","Kun bruo kaj kolero ĝi glutas teron, Kaj ne povas stari trankvile ĉe sonado de trumpeto."],[39,25,"Kiam eksonas la trumpeto, ĝi ekkrias: Ho, ho! Kaj de malproksime ĝi flarsentas la batalon, Kriadon de la kondukantoj, kaj bruon.","Kiam eksonas la trumpeto, ĝi ekkrias: Ho, ho! Kaj de malproksime ĝi flarsentas la batalon, Kriadon de la kondukantoj, kaj bruon."],[39,26,"Ĉu pro via saĝo flugas la akcipitro Kaj etendas siajn flugilojn al sudo?","Ĉu pro via saĝo flugas la akcipitro Kaj etendas siajn flugilojn al sudo?"],[39,27,"Ĉu pro via ordono leviĝas la aglo Kaj faras alte sian neston?","Ĉu pro via ordono leviĝas la aglo Kaj faras alte sian neston?"],[39,28,"Sur roko ĝi loĝas, Noktas sur dento de roko kaj de monta pinto.","Sur roko ĝi loĝas, Noktas sur dento de roko kaj de monta pinto."],[39,29,"De tie ĝi elrigardas por si manĝaĵon; Malproksime vidas ĝiaj okuloj.","De tie ĝi elrigardas por si manĝaĵon; Malproksime vidas ĝiaj okuloj."],[39,30,"Ĝiaj idoj trinkas sangon; Kaj kie estas mortigitoj, tie ĝi estas.","Ĝiaj idoj trinkas sangon; Kaj kie estas mortigitoj, tie ĝi estas."],[40,1,"Kaj la Eternulo plue parolis al Ijob, kaj diris:","Kaj la Eternulo plue parolis al Ijob, kaj diris:"],[40,2,"Ĉu povas blasfemanto disputi kun la Plejpotenculo? La mallaŭdanto de Dio tion respondu.","Ĉu povas blasfemanto disputi kun la Plejpotenculo? La mallaŭdanto de Dio tion respondu."],[40,3,"Kaj Ijob respondis al la Eternulo, kaj diris:","Kaj Ijob respondis al la Eternulo, kaj diris:"],[40,4,"Jen mi estis facilanima; kion mi povas respondi al Vi? Mi metas mian manon sur mian buŝon.","Jen mi estis facilanima; kion mi povas respondi al Vi? Mi metas mian manon sur mian buŝon."],[40,5,"Unu fojon mi parolis, kaj mi ne respondos; Tion mi ne faros duan fojon.","Unu fojon mi parolis, kaj mi ne respondos; Tion mi ne faros duan fojon."],[40,6,"Kaj la Eternulo respondis al Ijob el la ventego, kaj diris:","Kaj la Eternulo respondis al Ijob el la ventego, kaj diris:"],[40,7,"Zonu kiel viro viajn lumbojn; Mi vin demandos, kaj vi sciigu al Mi.","Zonu kiel viro viajn lumbojn; Mi vin demandos, kaj vi sciigu al Mi."],[40,8,"Ĉu vi volas senvalorigi Mian verdikton, Akuzi Min, por ke vi montriĝu prava?","Ĉu vi volas senvalorigi Mian verdikton, Akuzi Min, por ke vi montriĝu prava?"],[40,9,"Se vi havas tian brakon, kiel Dio, Kaj se vi povas tondri per voĉo simile al Li,","Se vi havas tian brakon, kiel Dio, Kaj se vi povas tondri per voĉo simile al Li,"],[40,10,"Tiam ornamu vin per majesto, kaj altiĝu, Vestu vin per gloro kaj belegeco;","Tiam ornamu vin per majesto, kaj altiĝu, Vestu vin per gloro kaj belegeco;"],[40,11,"Elverŝu la furiozon de via kolero; Ekrigardu ĉion fieran kaj humiligu ĝin;","Elverŝu la furiozon de via kolero; Ekrigardu ĉion fieran kaj humiligu ĝin;"],[40,12,"Ekrigardu ĉiun fierulon kaj konfuzu lin; Kaj frakasu la malpiulojn sur ilia loko;","Ekrigardu ĉiun fierulon kaj konfuzu lin; Kaj frakasu la malpiulojn sur ilia loko;"],[40,13,"Kaŝu ilin ĉiujn en la tero; Ilian vizaĝon kovru per mallumo.","Kaŝu ilin ĉiujn en la tero; Ilian vizaĝon kovru per mallumo."],[40,14,"Tiam Mi gloros vin, Se via dekstra mano vin helpos.","Tiam Mi gloros vin, Se via dekstra mano vin helpos."],[40,15,"Vidu la hipopotamon, kiun Mi kreis apud vi; Herbon ĝi manĝas, kiel bovo.","Vidu la hipopotamon, kiun Mi kreis apud vi; Herbon ĝi manĝas, kiel bovo."],[40,16,"Vidu, ĝia forto estas en ĝiaj lumboj, Kaj ĝia fortikeco estas en la muskoloj de ĝia ventro.","Vidu, ĝia forto estas en ĝiaj lumboj, Kaj ĝia fortikeco estas en la muskoloj de ĝia ventro."],[40,17,"Ĝi streĉas sian voston kiel cedron, La tendenoj de ĝiaj femuroj estas interplektitaj.","Ĝi streĉas sian voston kiel cedron, La tendenoj de ĝiaj femuroj estas interplektitaj."],[40,18,"Ĝiaj ostoj estas kiel kupraj tuboj, Ĝiaj ostoj estas kiel feraj stangoj.","Ĝiaj ostoj estas kiel kupraj tuboj, Ĝiaj ostoj estas kiel feraj stangoj."],[40,19,"Ĝi estas la komenco de la vojoj de Dio; Ĝia Kreinto donis al ĝi ĝian glavon.","Ĝi estas la komenco de la vojoj de Dio; Ĝia Kreinto donis al ĝi ĝian glavon."],[40,20,"La montoj alportas al ĝi manĝaĵon, Kaj ĉiuj bestoj de la kampo tie ludas.","La montoj alportas al ĝi manĝaĵon, Kaj ĉiuj bestoj de la kampo tie ludas."],[40,21,"Sub ombroriĉaj arboj ĝi kuŝas, Sub kovro de kanoj kaj en ŝlimo.","Sub ombroriĉaj arboj ĝi kuŝas, Sub kovro de kanoj kaj en ŝlimo."],[40,22,"Ombroriĉaj arboj ŝirmas ĝin per sia ombro, Ĉirkaŭas ĝin salikoj apud torentoj.","Ombroriĉaj arboj ŝirmas ĝin per sia ombro, Ĉirkaŭas ĝin salikoj apud torentoj."],[40,23,"Se la rivero tumultas, ĝi ne konfuziĝas; Ĝi staras trankvile, se eĉ Jordan enverŝiĝus en ĝian buŝon.","Se la rivero tumultas, ĝi ne konfuziĝas; Ĝi staras trankvile, se eĉ Jordan enverŝiĝus en ĝian buŝon."],[40,24,"Ĉu iu povas preni ĝin antaŭ ĝiaj okuloj, Ĉu iu povas trabori per ŝnuroj ĝian nazon?","Ĉu iu povas preni ĝin antaŭ ĝiaj okuloj, Ĉu iu povas trabori per ŝnuroj ĝian nazon?"],[41,1,"Ĉu vi povas eltiri levjatanon per fiŝhoko, Aŭ ligi per ŝnuro ĝian langon?","Ĉu vi povas eltiri levjatanon per fiŝhoko, Aŭ ligi per ŝnuro ĝian langon?"],[41,2,"Ĉu vi povas trameti kanon tra ĝia nazo Kaj trapiki ĝian vangon per pikilo?","Ĉu vi povas trameti kanon tra ĝia nazo Kaj trapiki ĝian vangon per pikilo?"],[41,3,"Ĉu ĝi multe petegos vin, Aŭ parolos al vi flataĵojn?","Ĉu ĝi multe petegos vin, Aŭ parolos al vi flataĵojn?"],[41,4,"Ĉu ĝi faros interligon kun vi? Ĉu vi povas preni ĝin kiel porĉiaman sklavon?","Ĉu ĝi faros interligon kun vi? Ĉu vi povas preni ĝin kiel porĉiaman sklavon?"],[41,5,"Ĉu vi amuziĝos kun ĝi kiel kun birdo? Aŭ ĉu vi ligos ĝin por viaj knabinoj?","Ĉu vi amuziĝos kun ĝi kiel kun birdo? Aŭ ĉu vi ligos ĝin por viaj knabinoj?"],[41,6,"Ĉu kamaradoj ĝin dishakos, Kaj dividos inter komercistoj?","Ĉu kamaradoj ĝin dishakos, Kaj dividos inter komercistoj?"],[41,7,"Ĉu vi povas plenigi per pikiloj ĝian haŭton Kaj per fiŝistaj hokoj ĝian kapon?","Ĉu vi povas plenigi per pikiloj ĝian haŭton Kaj per fiŝistaj hokoj ĝian kapon?"],[41,8,"Metu sur ĝin vian manon; Tiam vi bone memoros la batalon, kaj ĝin ne plu entreprenos.","Metu sur ĝin vian manon; Tiam vi bone memoros la batalon, kaj ĝin ne plu entreprenos."],[41,9,"Vidu, la espero ĉiun trompos; Jam ekvidinte ĝin, li falos.","Vidu, la espero ĉiun trompos; Jam ekvidinte ĝin, li falos."],[41,10,"Neniu estas tiel kuraĝa, por inciti ĝin; Kiu do povas stari antaŭ Mi?","Neniu estas tiel kuraĝa, por inciti ĝin; Kiu do povas stari antaŭ Mi?"],[41,11,"Kiu antaŭe ion donis al Mi, ke Mi redonu al li? Sub la tuta ĉielo ĉio estas Mia.","Kiu antaŭe ion donis al Mi, ke Mi redonu al li? Sub la tuta ĉielo ĉio estas Mia."],[41,12,"Mi ne silentos pri ĝiaj membroj, Pri ĝia forto kaj bela staturo.","Mi ne silentos pri ĝiaj membroj, Pri ĝia forto kaj bela staturo."],[41,13,"Kiu povas levi ĝian veston? Kiu aliros al ĝia paro da makzeloj?","Kiu povas levi ĝian veston? Kiu aliros al ĝia paro da makzeloj?"],[41,14,"Kiu povas malfermi la pordon de ĝia vizaĝo? Teruro ĉirkaŭas ĝiajn dentojn.","Kiu povas malfermi la pordon de ĝia vizaĝo? Teruro ĉirkaŭas ĝiajn dentojn."],[41,15,"Ĝiaj fieraj skvamoj estas kiel ŝildoj, Interligitaj per fortika sigelo;","Ĝiaj fieraj skvamoj estas kiel ŝildoj, Interligitaj per fortika sigelo;"],[41,16,"Unu kuntuŝiĝas kun la alia tiel, Ke aero ne povas trairi tra ili;","Unu kuntuŝiĝas kun la alia tiel, Ke aero ne povas trairi tra ili;"],[41,17,"Unu alfortikiĝis al la alia, Interkuniĝis kaj ne disiĝas.","Unu alfortikiĝis al la alia, Interkuniĝis kaj ne disiĝas."],[41,18,"Ĝia terno briligas lumon, Kaj ĝiaj okuloj estas kiel la palpebroj de la ĉielruĝo.","Ĝia terno briligas lumon, Kaj ĝiaj okuloj estas kiel la palpebroj de la ĉielruĝo."],[41,19,"El ĝia buŝo eliras torĉoj, Elkuras flamaj fajreroj.","El ĝia buŝo eliras torĉoj, Elkuras flamaj fajreroj."],[41,20,"El ĝiaj nazotruoj eliras fumo, Kiel el bolanta poto aŭ kaldrono.","El ĝiaj nazotruoj eliras fumo, Kiel el bolanta poto aŭ kaldrono."],[41,21,"Ĝia spiro ekbruligas karbojn, Kaj flamo eliras el ĝia buŝo.","Ĝia spiro ekbruligas karbojn, Kaj flamo eliras el ĝia buŝo."],[41,22,"Sur ĝia kolo loĝas forto, Kaj antaŭ ĝi kuras teruro.","Sur ĝia kolo loĝas forto, Kaj antaŭ ĝi kuras teruro."],[41,23,"La partoj de ĝia karno estas firme kunligitaj inter si, Tenas sin fortike sur ĝi, kaj ne ŝanceliĝas.","La partoj de ĝia karno estas firme kunligitaj inter si, Tenas sin fortike sur ĝi, kaj ne ŝanceliĝas."],[41,24,"Ĝia koro estas malmola kiel ŝtono, Kaj fortika kiel suba muelŝtono.","Ĝia koro estas malmola kiel ŝtono, Kaj fortika kiel suba muelŝtono."],[41,25,"Kiam ĝi sin levas, ektremas fortuloj, Konsterniĝas de teruro.","Kiam ĝi sin levas, ektremas fortuloj, Konsterniĝas de teruro."],[41,26,"Glavo, kiu alproksimiĝas al ĝi, ne povas sin teni, Nek lanco, sago, aŭ kiraso.","Glavo, kiu alproksimiĝas al ĝi, ne povas sin teni, Nek lanco, sago, aŭ kiraso."],[41,27,"Feron ĝi rigardas kiel pajlon, Kupron kiel putran lignon.","Feron ĝi rigardas kiel pajlon, Kupron kiel putran lignon."],[41,28,"Ne forpelos ĝin sago; Ŝtonoj el ŝtonĵetilo fariĝas pajleroj antaŭ ĝi.","Ne forpelos ĝin sago; Ŝtonoj el ŝtonĵetilo fariĝas pajleroj antaŭ ĝi."],[41,29,"Bastonegon ĝi rigardas kiel pajlon, Kaj ĝi mokas la sonon de lanco.","Bastonegon ĝi rigardas kiel pajlon, Kaj ĝi mokas la sonon de lanco."],[41,30,"Sube ĝi havas akrajn pecetojn; Kiel draŝrulo ĝi kuŝas sur la ŝlimo.","Sube ĝi havas akrajn pecetojn; Kiel draŝrulo ĝi kuŝas sur la ŝlimo."],[41,31,"Kiel kaldronon ĝi ondigas la profundon; La maron ĝi kirlas kiel ŝmiraĵon.","Kiel kaldronon ĝi ondigas la profundon; La maron ĝi kirlas kiel ŝmiraĵon."],[41,32,"La vojo post ĝi lumas; La abismo aperas kiel grizaĵo.","La vojo post ĝi lumas; La abismo aperas kiel grizaĵo."],[41,33,"Ne ekzistas sur la tero io simila al ĝi; Ĝi estas kreita sentima.","Ne ekzistas sur la tero io simila al ĝi; Ĝi estas kreita sentima."],[41,34,"Ĝi rigardas malestime ĉion altan; Ĝi estas reĝo super ĉiuj sovaĝaj bestoj.","Ĝi rigardas malestime ĉion altan; Ĝi estas reĝo super ĉiuj sovaĝaj bestoj."],[42,1,"Ijob respondis al la Eternulo, kaj diris:","Ijob respondis al la Eternulo, kaj diris:"],[42,2,"Mi scias, ke Vi ĉion povas fari, Kaj ke nenio, kion Vi entreprenas, estas malfacila por Vi.","Mi scias, ke Vi ĉion povas fari, Kaj ke nenio, kion Vi entreprenas, estas malfacila por Vi."],[42,3,"Kiu estas tiu, kiu kovras malkompetente la plej altan decidon? Jes, mi parolis sen komprenado pri aferoj, Kiuj estas tro misteraj por mi, kaj kiujn mi ne konas.","Kiu estas tiu, kiu kovras malkompetente la plej altan decidon? Jes, mi parolis sen komprenado pri aferoj, Kiuj estas tro misteraj por mi, kaj kiujn mi ne konas."],[42,4,"Aŭskultu, kaj mi parolos; Mi demandos Vin, kaj Vi sciigu al mi.","Aŭskultu, kaj mi parolos; Mi demandos Vin, kaj Vi sciigu al mi."],[42,5,"Nur per la oreloj mi aŭdis pri Vi; Sed nun mia okulo Vin vidis.","Nur per la oreloj mi aŭdis pri Vi; Sed nun mia okulo Vin vidis."],[42,6,"Tial mi faras al mi riproĉon, Kaj mi pentas en polvo kaj cindro.","Tial mi faras al mi riproĉon, Kaj mi pentas en polvo kaj cindro."],[42,7,"Post kiam la Eternulo parolis tiujn vortojn al Ijob, la Eternulo diris al Elifaz, la Temanano: Mia kolero ekflamis kontraŭ vi kaj kontraŭ viaj du amikoj, pro tio, ke vi ne parolis antaŭ Mi tiel ĝuste, kiel Mia servanto Ijob.","Post kiam la Eternulo parolis tiujn vortojn al Ijob, la Eternulo diris al Elifaz, la Temanano: Mia kolero ekflamis kontraŭ vi kaj kontraŭ viaj du amikoj, pro tio, ke vi ne parolis antaŭ Mi tiel ĝuste, kiel Mia servanto Ijob."],[42,8,"Prenu do nun al vi sep bovojn kaj sep ŝafojn, kaj iru al Mia servanto Ijob, kaj alportu bruloferon pro vi; kaj Mia servanto Ijob preĝos por vi; ĉar nur lin Mi atentos, por ne fari al vi punon pro tio, ke vi ne parolis antaŭ Mi tiel ĝuste, kiel Mia servanto Ijob.","Prenu do nun al vi sep bovojn kaj sep ŝafojn, kaj iru al Mia servanto Ijob, kaj alportu bruloferon pro vi; kaj Mia servanto Ijob preĝos por vi; ĉar nur lin Mi atentos, por ne fari al vi punon pro tio, ke vi ne parolis antaŭ Mi tiel ĝuste, kiel Mia servanto Ijob."],[42,9,"Kaj iris Elifaz, la Temanano, kaj Bildad, la Ŝuĥano, kaj Cofar, la Naamano, kaj faris tion, kion diris al ili la Eternulo. Kaj la Eternulo atentis Ijobon.","Kaj iris Elifaz, la Temanano, kaj Bildad, la Ŝuĥano, kaj Cofar, la Naamano, kaj faris tion, kion diris al ili la Eternulo. Kaj la Eternulo atentis Ijobon."],[42,10,"Kaj la Eternulo redonis la forprenitaĵon al Ijob, kiam li preĝis por siaj amikoj. Kaj la Eternulo donis al Ijob duoble pli ol ĉio, kion li havis antaŭe.","Kaj la Eternulo redonis la forprenitaĵon al Ijob, kiam li preĝis por siaj amikoj. Kaj la Eternulo donis al Ijob duoble pli ol ĉio, kion li havis antaŭe."],[42,11,"Kaj venis al li ĉiuj liaj fratoj kaj ĉiuj liaj fratinoj kaj ĉiuj liaj antaŭaj konatoj, kaj ili manĝis kun li en lia domo, kaj esprimis al li sian kunsenton, kaj konsolis lin pri la tuta malbono, kiun la Eternulo venigis sur lin; kaj ĉiu el ili donis al li po unu kesito, kaj ĉiu po unu ora ringo.","Kaj venis al li ĉiuj liaj fratoj kaj ĉiuj liaj fratinoj kaj ĉiuj liaj antaŭaj konatoj, kaj ili manĝis kun li en lia domo, kaj esprimis al li sian kunsenton, kaj konsolis lin pri la tuta malbono, kiun la Eternulo venigis sur lin; kaj ĉiu el ili donis al li po unu kesito, kaj ĉiu po unu ora ringo."],[42,12,"Kaj la Eternulo benis la lastajn jarojn de Ijob pli ol la komencajn; kaj li havis dek kvar mil ŝafojn kaj ses mil kamelojn kaj mil parojn da bovoj kaj mil azeninojn.","Kaj la Eternulo benis la lastajn jarojn de Ijob pli ol la komencajn; kaj li havis dek kvar mil ŝafojn kaj ses mil kamelojn kaj mil parojn da bovoj kaj mil azeninojn."],[42,13,"Kaj li havis sep filojn kaj tri filinojn.","Kaj li havis sep filojn kaj tri filinojn."],[42,14,"Al unu el ĉi tiuj li donis al nomon Jemima, al la dua la nomon Kecia, kaj al la tria la nomon Keren-Hapuĥ.","Al unu el ĉi tiuj li donis al nomon Jemima, al la dua la nomon Kecia, kaj al la tria la nomon Keren-Hapuĥ."],[42,15,"Kaj en la tuta lando ne troviĝis virinoj tiel belaj, kiel la filinoj de Ijob; kaj ilia patro donis al ili heredan posedaĵon inter iliaj fratoj.","Kaj en la tuta lando ne troviĝis virinoj tiel belaj, kiel la filinoj de Ijob; kaj ilia patro donis al ili heredan posedaĵon inter iliaj fratoj."],[42,16,"Kaj post tio Ijob vivis cent kvardek jarojn, kaj li vidis siajn filojn kaj nepojn ĝis la kvara generacio.","Kaj post tio Ijob vivis cent kvardek jarojn, kaj li vidis siajn filojn kaj nepojn ĝis la kvara generacio."],[42,17,"Kaj Ijob mortis, maljuna kaj satiĝinta de la vivo.","Kaj Ijob mortis, maljuna kaj satiĝinta de la vivo."]]}};